/** Top app bar with premium wave header matching exact uploaded design */
@Composable
fun GradientTopBar(
    title: String,
    subtitle: String? = null,
    onBack: (() -> Unit)? = null,
    gradient: List<Color> = GradPrimary,
    actions: @Composable RowScope.() -> Unit = {}
) {
    val isDark = isDarkModeGlobal
    val bgHeader = if (isDark) Color(0xFF070705) else Color.White
    val titleColor = if (isDark) Color(0xFFF5C518) else Color(0xFF0F172A)
    val subtitleColor = if (isDark) Color(0xFFE5E7EB) else Color(0xFF64748B)

    Box(
        modifier = Modifier
            .fillMaxWidth()
            .background(bgHeader)
            .statusBarsPadding()
    ) {
        if (isDark) {
            // Sweeping Golden Mesh / Wave Lines canvas background in top right matching settings header design
            Canvas(
                modifier = Modifier.matchParentSize()
            ) {
                val w = size.width
                val h = size.height

                // Glowing golden radial highlight in top right
                drawRect(
                    brush = Brush.radialGradient(
                        colors = listOf(Color(0xFF8C6B1C).copy(alpha = 0.35f), Color.Transparent),
                        center = Offset(w * 0.95f, h * 0.2f),
                        radius = w * 0.7f
                    )
                )

                // Multiple elegant sweeping golden mesh lines matching Settings header design
                for (i in 0..12) {
                    val alpha = (0.12f + i * 0.05f).coerceAtMost(0.65f)
                    val offsetY = i * 4.dp.toPx()
                    val path = Path().apply {
                        moveTo(w * 0.35f + i * 8.dp.toPx(), h)
                        cubicTo(
                            w * 0.55f + i * 5.dp.toPx(), h * 0.7f,
                            w * 0.75f, h * 0.1f + offsetY,
                            w, offsetY
                        )
                    }
                    drawPath(
                        path = path,
                        color = Color(0xFFF5C518).copy(alpha = alpha),
                        style = Stroke(
                            width = (1.2.dp.toPx()).coerceAtLeast(1f),
                            cap = StrokeCap.Round
                        )
                    )
                }
            }
        } else {
            // Light / White mode: Exact warm golden sweeping wave from uploaded image
            Canvas(
                modifier = Modifier.matchParentSize()
            ) {
                val w = size.width
                val h = size.height

                // Wave curve starting around top middle (x = 0.40w), sweeping down to bottom right
                val wavePath = Path().apply {
                    moveTo(w * 0.38f, 0f)
                    cubicTo(
                        w * 0.54f, h * 0.25f,
                        w * 0.72f, h * 0.82f,
                        w * 1.02f, h * 0.98f
                    )
                    lineTo(w, 0f)
                    close()
                }

                // Smooth golden radial / linear gradient fill
                drawPath(
                    path = wavePath,
                    brush = Brush.linearGradient(
                        colors = listOf(
                            Color(0xFFFFFBEB).copy(alpha = 0.2f),
                            Color(0xFFFEF3C7).copy(alpha = 0.85f),
                            Color(0xFFFDE68A).copy(alpha = 0.95f),
                            Color(0xFFFBBF24).copy(alpha = 0.70f)
                        ),
                        start = Offset(w * 0.38f, 0f),
                        end = Offset(w, h)
                    )
                )

                // Soft radial golden glow highlight on top right
                drawRect(
                    brush = Brush.radialGradient(
                        colors = listOf(
                            Color(0xFFFBBF24).copy(alpha = 0.40f),
                            Color.Transparent
                        ),
                        center = Offset(w * 0.92f, h * 0.25f),
                        radius = w * 0.55f
                    )
                )

                // Delicate gold boundary line along curve
                val curveStrokePath = Path().apply {
                    moveTo(w * 0.38f, 0f)
                    cubicTo(
                        w * 0.54f, h * 0.25f,
                        w * 0.72f, h * 0.82f,
                        w * 1.02f, h * 0.98f
                    )
                }
                drawPath(
                    path = curveStrokePath,
                    color = Color(0xFFF59E0B).copy(alpha = 0.50f),
                    style = Stroke(
                        width = 1.8.dp.toPx(),
                        cap = StrokeCap.Round
                    )
                )
            }
        }

        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = 16.dp, vertical = 14.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            if (onBack != null) {
                Surface(
                    modifier = Modifier
                        .size(46.dp)
                        .clip(RoundedCornerShape(16.dp))
                        .clickable { onBack() },
                    shape = RoundedCornerShape(16.dp),
                    color = if (isDark) Color(0xFF0D0B07) else Color.White,
                    shadowElevation = if (isDark) 0.dp else 3.dp,
                    border = BorderStroke(1.dp, if (isDark) Color(0xFF5A441B) else Color(0xFFF1F5F9))
                ) {
                    Box(contentAlignment = Alignment.Center) {
                        Icon(
                            imageVector = Icons.AutoMirrored.Filled.ArrowBack,
                            contentDescription = "Back",
                            tint = if (isDark) Color(0xFFF5C518) else Color(0xFF0F172A),
                            modifier = Modifier.size(20.dp)
                        )
                    }
                }
                Spacer(modifier = Modifier.width(14.dp))
            }

            Column(modifier = Modifier.weight(1f)) {
                Text(
                    text = title,
                    fontWeight = FontWeight.ExtraBold,
                    fontSize = 21.sp,
                    color = titleColor,
                    maxLines = 1,
                    overflow = androidx.compose.ui.text.style.TextOverflow.Ellipsis
                )
                if (subtitle != null) {
                    Spacer(modifier = Modifier.height(2.dp))
                    Text(
                        text = subtitle,
                        fontSize = 12.5.sp,
                        color = subtitleColor,
                        maxLines = 1,
                        overflow = androidx.compose.ui.text.style.TextOverflow.Ellipsis
                    )
                }
            }

            Row(
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(8.dp),
                content = actions
            )
        }
    }
}

