/**
 * Enterprise gesture-driven modal bottom sheet for modern multinational applications.
 * Features:
 * - Smooth slide up/down spring animations from bottom
 * - Gesture control: Swipe/drag down to dismiss or minimize
 * - Prominent pill drag handle indicating swipe control
 * - Dark & light mode enterprise aesthetics
 * - Back-drop tap gesture to dismiss
 */
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun EnterpriseGestureModal(
    onDismissRequest: () -> Unit,
    title: String? = null,
    subtitle: String? = null,
    icon: ImageVector? = null,
    sheetState: SheetState = rememberModalBottomSheetState(skipPartiallyExpanded = true),
    content: @Composable ColumnScope.() -> Unit
) {
    val isDark = isDarkModeGlobal
    val containerBg = if (isDark) Color(0xFF121216) else Color.White
    val contentColor = if (isDark) Color.White else Color(0xFF0F172A)

    ModalBottomSheet(
        onDismissRequest = onDismissRequest,
        sheetState = sheetState,
        containerColor = containerBg,
        contentColor = contentColor,
        tonalElevation = 12.dp,
        scrimColor = Color.Black.copy(alpha = 0.65f),
        dragHandle = {
            Column(
                horizontalAlignment = Alignment.CenterHorizontally,
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(top = 10.dp, bottom = 8.dp)
            ) {
                // Drag handle pill for intuitive gesture control
                Box(
                    modifier = Modifier
                        .width(48.dp)
                        .height(5.dp)
                        .clip(CircleShape)
                        .background(if (isDark) Color(0xFF52525B) else Color(0xFFCBD5E1))
                )
            }
        },
        shape = RoundedCornerShape(topStart = 28.dp, topEnd = 28.dp)
    ) {
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .navigationBarsPadding()
                .padding(start = 20.dp, end = 20.dp, bottom = 20.dp)
        ) {
            if (title != null) {
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(12.dp),
                    modifier = Modifier.padding(bottom = 16.dp)
                ) {
                    if (icon != null) {
                        Box(
                            modifier = Modifier
                                .size(40.dp)
                                .clip(CircleShape)
                                .background(if (isDark) Color(0xFF27272A) else Color(0xFFF1F5F9))
                                .border(BorderStroke(1.dp, if (isDark) Color(0xFF3F3F46) else Color(0xFFE2E8F0)), CircleShape),
                            contentAlignment = Alignment.Center
                        ) {
                            Icon(icon, null, tint = if (isDark) Color(0xFFF5C518) else Color(0xFF0F172A), modifier = Modifier.size(20.dp))
                        }
                    }
                    Column(modifier = Modifier.weight(1f)) {
                        Text(
                            text = title,
                            fontSize = 19.sp,
                            fontWeight = FontWeight.Bold,
                            color = if (isDark) Color.White else Color(0xFF0F172A)
                        )
                        if (subtitle != null) {
                            Text(
                                text = subtitle,
                                fontSize = 12.5.sp,
                                color = if (isDark) Color(0xFFA1A1AA) else Color(0xFF64748B)
                            )
                        }
                    }
                }
            }
            content()
        }
    }
}

