// Reusable High-Performance Shimmer Brush for Skeletons
@Composable
fun rememberShimmerBrush(isDarkMode: Boolean): Brush {
    val transition = rememberInfiniteTransition(label = "shimmer_transition")
    val translateAnim = transition.animateFloat(
        initialValue = 0f,
        targetValue = 1000f,
        animationSpec = infiniteRepeatable(
            animation = tween(durationMillis = 1200, easing = LinearEasing),
            repeatMode = RepeatMode.Restart
        ),
        label = "shimmer_translation"
    )
    
    val shimmerColors = if (isDarkMode) {
        listOf(
            Color(0xFF1E1F26).copy(alpha = 0.6f),
            Color(0xFF474555).copy(alpha = 0.9f),
            Color(0xFF1E1F26).copy(alpha = 0.6f)
        )
    } else {
        listOf(
            Color(0xFFE2E8F0).copy(alpha = 0.6f),
            Color(0xFFF1F5F9).copy(alpha = 0.9f),
            Color(0xFFE2E8F0).copy(alpha = 0.6f)
        )
    }
    
    return Brush.linearGradient(
        colors = shimmerColors,
        start = Offset(translateAnim.value - 300f, translateAnim.value - 300f),
        end = Offset(translateAnim.value, translateAnim.value)
    )
}

// Custom High-Fidelity Vector drawn MFS Logos (bKash, Nagad, Rocket, Upay)
@Composable
fun MfsLogo(method: String, modifier: Modifier = Modifier) {
    Box(
        modifier = modifier
            .clip(RoundedCornerShape(12.dp))
            .background(Color.White)
            .padding(4.dp),
        contentAlignment = Alignment.Center
    ) {
        val drawableId = when (method.lowercase()) {
            "bkash" -> R.drawable.ic_bkash
            "nagad" -> R.drawable.ic_nagad
            "rocket" -> R.drawable.ic_rocket
            "upay" -> R.drawable.ic_upay
            else -> null
        }
        
        if (drawableId != null) {
            androidx.compose.foundation.Image(
                painter = painterResource(id = drawableId),
                contentDescription = "$method Logo",
                modifier = Modifier.fillMaxSize(),
                contentScale = androidx.compose.ui.layout.ContentScale.Fit
            )
        } else {
            // High-fidelity fallback for custom methods or broken assets
            Box(
                modifier = Modifier
                    .fillMaxSize()
                    .background(Color(0xFF5D45FF).copy(alpha = 0.08f)),
                contentAlignment = Alignment.Center
            ) {
                Text(
                    text = method.take(2).uppercase(),
                    color = Color(0xFF5D45FF),
                    fontWeight = FontWeight.Bold,
                    fontSize = 14.sp
                )
            }
        }
    }
}

