                }
            }
        }
    }

    // Global Admin Notice & Broadcast Popup Modal (Connected to Admin Panel)
    val adminNoticePopup by viewModel.adminNoticePopup.collectAsState()
    adminNoticePopup?.let { notice ->
        val isDark = viewModel.isDarkMode.value
