// 1. Splash Screen — Enterprise Design
@Composable
fun SplashScreen(viewModel: AppViewModel) {
    val isDarkMode by viewModel.isDarkMode.collectAsState()
    SideEffect { isDarkModeGlobal = isDarkMode }

    val userEmail by viewModel.userEmail.collectAsState()
    val splashProgress by viewModel.splashProgress.collectAsState()
    val splashStatusText by viewModel.splashStatusText.collectAsState()
    val splashSteps by viewModel.splashSteps.collectAsState()

    LaunchedEffect(Unit) {
        viewModel.performSplashInitialization { _ -> }
    }

    val infTrans = rememberInfiniteTransition(label = "splash")
    val logoScale by infTrans.animateFloat(
        initialValue = 0.96f, targetValue = 1.04f,
        animationSpec = infiniteRepeatable(tween(1800, easing = FastOutSlowInEasing), RepeatMode.Reverse),
        label = "logoScale"
    )
    val glowAlpha by infTrans.animateFloat(
        initialValue = 0.3f, targetValue = 0.7f,
        animationSpec = infiniteRepeatable(tween(1800), RepeatMode.Reverse),
        label = "glowAlpha"
    )

    val splashImgRes = if (isDarkMode) R.drawable.splash_dark else R.drawable.splash_light
    val splashBgColor = if (isDarkMode) Color(0xFF000000) else Color(0xFFFFFFFF)
    val splashTextColor = if (isDarkMode) Color.White else Color(0xFF0F172A)
    val splashSubTextColor = if (isDarkMode) Color(0xFF818CF8) else Color(0xFF4F46E5)
    val cardBgColor = if (isDarkMode) Color(0xFF13102B).copy(alpha = 0.88f) else Color(0xFFF8FAFC).copy(alpha = 0.95f)
    val cardBorderColor = if (isDarkMode) Color(0xFF818CF8).copy(alpha = 0.25f) else Color(0xFFE2E8F0)

    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(splashBgColor),
        contentAlignment = Alignment.Center
    ) {
        // Full splash background branding image (fully visible without cropping)
        AsyncImage(
            model = ImageRequest.Builder(LocalContext.current)
                .data(splashImgRes)
                .crossfade(true)
                .build(),
            contentDescription = "SwapnoPay Branding Splash",
            contentScale = ContentScale.Fit,
            modifier = Modifier.fillMaxSize()
        )

        // Loading indicator and security footer positioned cleanly at bottom
        Column(
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.Bottom,
            modifier = Modifier
                .fillMaxSize()
                .navigationBarsPadding()
                .padding(bottom = 28.dp)
        ) {
            CircularProgressIndicator(
                color = splashSubTextColor,
                strokeWidth = 2.5.dp,
                modifier = Modifier.size(30.dp)
            )

            Spacer(modifier = Modifier.height(14.dp))

            // Real-time security log footer
            Row(
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(6.dp)
            ) {
                Icon(
                    imageVector = Icons.Default.Lock,
                    contentDescription = "Encrypted",
                    tint = if (isDarkMode) Color(0xFF818CF8).copy(alpha = 0.8f) else Color(0xFF4F46E5),
                    modifier = Modifier.size(13.dp)
                )
                Text(
                    text = "Secure Local Session • Supabase Auth",
                    fontSize = 11.sp,
                    color = if (isDarkMode) Color.White.copy(alpha = 0.5f) else Color(0xFF475569)
                )
            }
        }
    }
}

// Interactive Biometric & PIN Security Lock Screen
@Composable
fun LockScreen(viewModel: AppViewModel) {
    val isDarkMode by viewModel.isDarkMode.collectAsState()
    SideEffect { isDarkModeGlobal = isDarkMode }

    val activeProfile by viewModel.activeProfile.collectAsState()
    val appPin by viewModel.appPin.collectAsState()
    val isBiometricLocked by viewModel.isBiometricLocked.collectAsState()
    val context = androidx.compose.ui.platform.LocalContext.current

    var pinInput by remember { mutableStateOf("") }
    var pinError by remember { mutableStateOf(false) }

    // Forgot PIN State
    var showForgotPinDialog by remember { mutableStateOf(false) }
    var forgotPinStep by remember { mutableStateOf(1) } // 1 = Phone, 2 = OTP, 3 = New PIN
    var recoveryPhoneInput by remember { mutableStateOf(activeProfile.phone.ifEmpty { "01700000000" }) }
    var sentOtpCode by remember { mutableStateOf("") }
    var otpInput by remember { mutableStateOf("") }
    var newPinInput by remember { mutableStateOf("") }
    var confirmNewPinInput by remember { mutableStateOf("") }
    var resetErrorMessage by remember { mutableStateOf("") }

    // Helper to extract FragmentActivity
    fun getFragmentActivity(ctx: android.content.Context): androidx.fragment.app.FragmentActivity? {
        var currentCtx = ctx
        while (currentCtx is android.content.ContextWrapper) {
            if (currentCtx is androidx.fragment.app.FragmentActivity) {
                return currentCtx
            }
            currentCtx = currentCtx.baseContext
        }
        return null
    }

    // Function to launch real system biometric prompt
    fun triggerBiometricPrompt() {
        val activity = getFragmentActivity(context)
        if (activity != null) {
            val biometricManager = androidx.biometric.BiometricManager.from(context)
            val canAuth = biometricManager.canAuthenticate(
                androidx.biometric.BiometricManager.Authenticators.BIOMETRIC_STRONG or
                androidx.biometric.BiometricManager.Authenticators.BIOMETRIC_WEAK
            )
            if (canAuth == androidx.biometric.BiometricManager.BIOMETRIC_ERROR_NO_HARDWARE) {
                android.widget.Toast.makeText(context, "No fingerprint hardware found on this device", android.widget.Toast.LENGTH_SHORT).show()
                return
            } else if (canAuth == androidx.biometric.BiometricManager.BIOMETRIC_ERROR_NONE_ENROLLED) {
                android.widget.Toast.makeText(context, "No fingerprint enrolled. Please add one in device Settings", android.widget.Toast.LENGTH_SHORT).show()
                return
            }

            val executor = androidx.core.content.ContextCompat.getMainExecutor(activity)
            val biometricPrompt = androidx.biometric.BiometricPrompt(
                activity,
                executor,
                object : androidx.biometric.BiometricPrompt.AuthenticationCallback() {
                    override fun onAuthenticationSucceeded(result: androidx.biometric.BiometricPrompt.AuthenticationResult) {
                        super.onAuthenticationSucceeded(result)
                        viewModel.unlockAppAndRestore()
                    }

                    override fun onAuthenticationError(errorCode: Int, errString: CharSequence) {
                        super.onAuthenticationError(errorCode, errString)
                        if (errorCode != androidx.biometric.BiometricPrompt.ERROR_USER_CANCELED &&
                            errorCode != androidx.biometric.BiometricPrompt.ERROR_NEGATIVE_BUTTON &&
                            errorCode != androidx.biometric.BiometricPrompt.ERROR_CANCELED) {
                            android.widget.Toast.makeText(context, "Biometric error: $errString", android.widget.Toast.LENGTH_SHORT).show()
                        }
                    }

                    override fun onAuthenticationFailed() {
                        super.onAuthenticationFailed()
                        pinError = true
                    }
                }
            )

            val promptInfo = androidx.biometric.BiometricPrompt.PromptInfo.Builder()
                .setTitle("Biometric Unlock")
                .setSubtitle("Authenticate using your fingerprint")
                .setNegativeButtonText("Use PIN")
                .build()

            try {
                biometricPrompt.authenticate(promptInfo)
            } catch (e: Exception) {
                android.widget.Toast.makeText(context, "Biometrics unavailable: ${e.message}", android.widget.Toast.LENGTH_SHORT).show()
            }
        } else {
            android.widget.Toast.makeText(context, "Biometrics unavailable on this device", android.widget.Toast.LENGTH_SHORT).show()
        }
    }

    // Auto-trigger on screen entry if biometric is enabled
    LaunchedEffect(Unit) {
        if (isBiometricLocked) {
            triggerBiometricPrompt()
        }
    }

    // Check PIN once entered 4 characters
    LaunchedEffect(pinInput) {
        if (pinInput.length == 4) {
            if (viewModel.verifyPin(pinInput)) {
                pinError = false
                kotlinx.coroutines.delay(200)
                viewModel.unlockAppAndRestore()
            } else {
                pinError = true
                kotlinx.coroutines.delay(800)
                pinInput = ""
                pinError = false
            }
        }
    }

    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(
                if (isDarkMode)
                    Brush.verticalGradient(colors = listOf(Color(0xFF111319), Color(0xFF0C0E14)))
                else
                    Brush.verticalGradient(colors = listOf(Color(0xFFF8FAFC), Color(0xFFF1F5F9)))
            )
            .padding(24.dp)
    ) {
        Column(
            modifier = Modifier.fillMaxSize(),
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.SpaceBetween
        ) {
            // Top Section (Profile and Logo)
            Column(
                horizontalAlignment = Alignment.CenterHorizontally,
                modifier = Modifier.padding(top = 48.dp)
            ) {
                Box(
                    modifier = Modifier
                        .size(80.dp)
                        .background(Color(0xFF4F46E5).copy(alpha = 0.2f), CircleShape)
                        .border(2.dp, Color(0xFF4F46E5), CircleShape),
                    contentAlignment = Alignment.Center
                ) {
                    Icon(
                        imageVector = Icons.Default.Lock,
                        contentDescription = "Lock",
                        tint = if (isDarkMode) Color.White else Color(0xFF4F46E5),
                        modifier = Modifier.size(36.dp)
                    )
                }

                Spacer(modifier = Modifier.height(16.dp))

                Text(
                    text = activeProfile.businessName,
                    fontSize = 22.sp,
                    fontWeight = FontWeight.Bold,
                    color = if (isDarkMode) Color.White else Color(0xFF0F172A)
                )

                Text(
                    text = "App is locked for your security",
                    fontSize = 13.sp,
                    color = if (isDarkMode) Color(0xFF818CF8) else Color(0xFF4F46E5),
                    modifier = Modifier.padding(top = 4.dp)
                )
            }

            val keypadKeyColor = if (isDarkMode) Color.White else Color(0xFF0F172A)
            val keypadKeyBg = if (isDarkMode)
                Brush.linearGradient(listOf(Color.White.copy(alpha = 0.08f), Color.White.copy(alpha = 0.04f)))
            else
                Brush.linearGradient(listOf(Color.White, Color(0xFFF1F5F9)))
            val keypadKeyBorder = if (isDarkMode) Color.White.copy(alpha = 0.12f) else Color(0xFFCBD5E1)
            val keypadDeleteTint = if (isDarkMode) Color.White.copy(alpha = 0.7f) else Color(0xFF334155)
            val pinInstructionColor = if (pinError) Color(0xFFEF4444) else if (isDarkMode) Color.White.copy(alpha = 0.8f) else Color(0xFF475569)
            val emptyDotColor = if (isDarkMode) Color.White.copy(alpha = 0.2f) else Color(0xFFE2E8F0)
            val emptyDotBorder = if (isDarkMode) Color.White.copy(alpha = 0.4f) else Color(0xFF94A3B8)
            val forgotPinColor = if (isDarkMode) Color(0xFFA5B4FC) else Color(0xFF4F46E5)

            // Middle Section (PIN Dot Indicators)
            Column(
                horizontalAlignment = Alignment.CenterHorizontally,
                modifier = Modifier.weight(1f, fill = false)
            ) {
                Text(
                    text = if (pinError) "Incorrect PIN, please try again" else "Enter 4-Digit Security PIN",
                    fontSize = 14.sp,
                    color = pinInstructionColor,
                    fontWeight = if (pinError) FontWeight.Bold else FontWeight.Medium,
                    modifier = Modifier.padding(bottom = 24.dp)
                )

                Row(
                    horizontalArrangement = Arrangement.spacedBy(24.dp),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    repeat(4) { index ->
                        val isFilled = index < pinInput.length
                        val dotColor = when {
                            pinError -> Color(0xFFEF4444)
                            isFilled -> Color(0xFF4F46E5)
                            else -> emptyDotColor
                        }
                        Box(
                            modifier = Modifier
                                .size(18.dp)
                                .background(dotColor, CircleShape)
                                .border(
                                    1.dp,
                                    if (isFilled) Color.Transparent else emptyDotBorder,
                                    CircleShape
                                )
                        )
                    }
                }
            }

            // Keypad Section
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(bottom = 24.dp),
                verticalArrangement = Arrangement.spacedBy(16.dp),
                horizontalAlignment = Alignment.CenterHorizontally
            ) {
                val keys = listOf(
                    listOf("1", "2", "3"),
                    listOf("4", "5", "6"),
                    listOf("7", "8", "9"),
                    listOf("bio", "0", "del")
                )

                keys.forEach { row ->
                    Row(
                        modifier = Modifier.fillMaxWidth(0.85f),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        row.forEach { key ->
                            // Tactile high-contrast keypad button
                            val isSpecial = key == "bio" || key == "del"
                            Box(
                                modifier = Modifier
                                    .size(72.dp)
                                    .clip(CircleShape)
                                    .background(
                                        if (isSpecial) androidx.compose.ui.graphics.SolidColor(Color.Transparent)
                                        else keypadKeyBg
                                    )
                                    .border(
                                        BorderStroke(1.dp,
                                            if (isSpecial) Color.Transparent
                                            else keypadKeyBorder
                                        ),
                                        CircleShape
                                    )
                                    .clickable {
                                        when (key) {
                                            "bio" -> triggerBiometricPrompt()
                                            "del" -> { if (pinInput.isNotEmpty()) pinInput = pinInput.dropLast(1) }
                                            else  -> { if (pinInput.length < 4) pinInput += key }
                                        }
                                    },
                                contentAlignment = Alignment.Center
                            ) {
                                when (key) {
                                    "bio" -> Icon(
                                        imageVector = Icons.Default.Fingerprint,
                                        contentDescription = "Biometrics",
                                        tint = if (isDarkMode) Color(0xFF818CF8) else Color(0xFF4F46E5),
                                        modifier = Modifier.size(32.dp)
                                    )
                                    "del" -> Icon(
                                        imageVector = Icons.Default.ArrowBack,
                                        contentDescription = "Delete",
                                        tint = keypadDeleteTint,
                                        modifier = Modifier.size(24.dp)
                                    )
                                    else -> Text(
                                        text = key,
                                        fontSize = 24.sp,
                                        fontWeight = FontWeight.SemiBold,
                                        color = keypadKeyColor
                                    )
                                }
                            }
                        }
                    }
                }

                // Forgot PIN / Password Button
                TextButton(
                    onClick = { showForgotPinDialog = true },
                    modifier = Modifier.padding(top = 4.dp)
                ) {
                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(6.dp)
                    ) {
                        Icon(
                            imageVector = Icons.Outlined.HelpOutline,
                            contentDescription = "Forgot PIN",
                            tint = forgotPinColor,
                            modifier = Modifier.size(16.dp)
                        )
                        Text(
                            text = "পিন বা পাসওয়ার্ড ভুলে গেছেন? (Forgot PIN?)",
                            color = forgotPinColor,
                            fontSize = 13.sp,
                            fontWeight = FontWeight.SemiBold
                        )
                    }
                }
            }
        }

        // Forgot PIN Reset Dialog
        if (showForgotPinDialog) {
            EnterpriseGestureModal(
                onDismissRequest = {
                    showForgotPinDialog = false
                    forgotPinStep = 1
                    resetErrorMessage = ""
                },
                title = "পিন রিসেট করুন (Reset 4-Digit PIN)",
                subtitle = "Swipe down or drag handle to dismiss",
                icon = Icons.Outlined.LockReset
            ) {
                Column(verticalArrangement = Arrangement.spacedBy(14.dp)) {
                    if (forgotPinStep == 1) {
                        Card(
                            colors = CardDefaults.cardColors(containerColor = if (isDarkMode) Color(0xFF1E293B) else Color(0xFFF1F5F9)),
                            border = BorderStroke(1.dp, Color(0xFF818CF8).copy(alpha = 0.4f)),
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            Column(modifier = Modifier.padding(14.dp), verticalArrangement = Arrangement.spacedBy(6.dp)) {
                                Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                                    Icon(Icons.Default.Info, contentDescription = null, tint = Color(0xFF818CF8), modifier = Modifier.size(18.dp))
                                    Text("পিন সিস্টেম", fontWeight = FontWeight.Bold, color = Color(0xFF818CF8), fontSize = 13.sp)
                                }
                                Text(
                                    "আপনার পিন মার্চেন্ট অ্যাকাউন্টের সাথে সংযুক্ত। পিন পুনরুদ্ধার করতে দুটি বিকল্প রয়েছে:",
                                    fontSize = 12.sp, color = AppTextSecondary, lineHeight = 18.sp
                                )
                            }
                        }

                        if (resetErrorMessage.isNotEmpty()) {
                            Text(resetErrorMessage,
                                color = if (resetErrorMessage.startsWith("✅")) Color(0xFF10B981) else Color(0xFFEF4444),
                                fontSize = 12.sp, fontWeight = FontWeight.Bold)
                        }

                        Button(
                            onClick = { showForgotPinDialog = false; viewModel.navigateTo("Login") },
                            colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF4F46E5), contentColor = Color.White),
                            shape = RoundedCornerShape(12.dp),
                            modifier = Modifier.fillMaxWidth().height(50.dp)
                        ) {
                            Icon(Icons.Default.VpnKey, contentDescription = null, modifier = Modifier.size(18.dp))
                            Spacer(modifier = Modifier.width(8.dp))
                            Column {
                                Text("পাসওয়ার্ড দিয়ে লগইন করুন", fontWeight = FontWeight.Bold, fontSize = 14.sp)
                                Text("লগইনের পরে নতুন পিন সেট করুন", fontSize = 11.sp, color = Color.White.copy(alpha = 0.8f))
                            }
                        }

                        OutlinedButton(
                            onClick = { forgotPinStep = 2; resetErrorMessage = "" },
                            colors = ButtonDefaults.outlinedButtonColors(contentColor = Color(0xFF818CF8)),
                            border = BorderStroke(1.dp, Color(0xFF818CF8)),
                            shape = RoundedCornerShape(12.dp),
                            modifier = Modifier.fillMaxWidth().height(50.dp)
                        ) {
                            Icon(Icons.Default.AdminPanelSettings, contentDescription = null, modifier = Modifier.size(18.dp))
                            Spacer(modifier = Modifier.width(8.dp))
                            Column {
                                Text("এডমিনের কাছে রিসেটের অনুরোধ", fontWeight = FontWeight.Bold, fontSize = 14.sp)
                                Text("এডমিন পিন মুছে দেবেন, নতুন পিন সেট করতে হবে", fontSize = 11.sp)
                            }
                        }

                    } else if (forgotPinStep == 2) {
                        Text("এডমিনের কাছে পিন রিসেটের অনুরোধ পাঠান",
                            fontWeight = FontWeight.Bold, fontSize = 15.sp, color = AppTextPrimary)
                        Text(
                            "অনুরোধ পাঠানোর পরে এডমিন আপনার পিন মুছে দেবেন। " +
                            "এরপরে পাসওয়ার্ড দিয়ে লগইন করে নতুন পিন সেট করুন।",
                            fontSize = 12.sp, color = AppTextSecondary, lineHeight = 18.sp
                        )
                        if (resetErrorMessage.isNotEmpty()) {
                            Text(resetErrorMessage,
                                color = if (resetErrorMessage.startsWith("✅")) Color(0xFF10B981) else Color(0xFFEF4444),
                                fontSize = 12.sp, fontWeight = FontWeight.Bold)
                        }
                        Button(
                            onClick = {
                                viewModel.requestPinReset { success, msg ->
                                    resetErrorMessage = if (success) "✅ $msg" else "❌ $msg"
                                    if (success) forgotPinStep = 3
                                }
                            },
                            colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF818CF8), contentColor = Color.White),
                            shape = RoundedCornerShape(12.dp),
                            modifier = Modifier.fillMaxWidth().height(50.dp)
                        ) {
                            Icon(Icons.Default.Send, contentDescription = null, modifier = Modifier.size(18.dp))
                            Spacer(modifier = Modifier.width(8.dp))
                            Text("এডমিনের কাছে অনুরোধ পাঠান", fontWeight = FontWeight.Bold, fontSize = 14.sp)
                        }
                        OutlinedButton(
                            onClick = { forgotPinStep = 1; resetErrorMessage = "" },
                            colors = ButtonDefaults.outlinedButtonColors(contentColor = AppTextSecondary),
                            border = BorderStroke(1.dp, AppCardBorderColor),
                            shape = RoundedCornerShape(12.dp), modifier = Modifier.fillMaxWidth()
                        ) { Text("পিছনে যান", fontSize = 13.sp) }

                    } else if (forgotPinStep == 3) {
                        Icon(Icons.Default.CheckCircle, contentDescription = null,
                            tint = Color(0xFF10B981), modifier = Modifier.size(56.dp))
                        Text("অনুরোধ পাঠানো হয়েছে!",
                            fontWeight = FontWeight.Bold, fontSize = 16.sp, color = Color(0xFF10B981))
                        Text(
                            "এডমিন যাচাই করে আপনার পিন মুছে দেবেন। " +
                            "এরপরে পাসওয়ার্ড দিয়ে লগইন করে নতুন পিন সেট করতে পারবেন।",
                            fontSize = 12.sp, color = AppTextSecondary, lineHeight = 18.sp
                        )
                        Button(
                            onClick = {
                                showForgotPinDialog = false; forgotPinStep = 1; resetErrorMessage = ""
                                viewModel.navigateTo("Login")
                            },
                            colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF4F46E5), contentColor = Color.White),
                            shape = RoundedCornerShape(12.dp),
                            modifier = Modifier.fillMaxWidth().height(50.dp)
                        ) {
                            Icon(Icons.Default.VpnKey, contentDescription = null, modifier = Modifier.size(18.dp))
                            Spacer(modifier = Modifier.width(8.dp))
                            Text("পাসওয়ার্ড দিয়ে লগইন করুন", fontWeight = FontWeight.Bold, fontSize = 14.sp)
                        }
                    }
                }
            }
        }
    }
}

// 2. Onboarding Screen
@Composable
fun TypewriterText(
    text: String,
    modifier: Modifier = Modifier,
    color: Color = Color.Unspecified,
    fontSize: androidx.compose.ui.unit.TextUnit = androidx.compose.ui.unit.TextUnit.Unspecified,
    fontWeight: FontWeight? = null,
    lineHeight: androidx.compose.ui.unit.TextUnit = androidx.compose.ui.unit.TextUnit.Unspecified,
    textAlign: TextAlign? = null
) {
    var displayedText by remember(text) { mutableStateOf("") }
    LaunchedEffect(text) {
        displayedText = ""
        for (i in 1..text.length) {
            displayedText = text.substring(0, i)
            kotlinx.coroutines.delay(12) // Ultra fast typing
        }
    }
    Text(
        text = displayedText,
        modifier = modifier,
        color = color,
        fontSize = fontSize,
        fontWeight = fontWeight,
        lineHeight = lineHeight,
        textAlign = textAlign
    )
}

@Composable
fun SupabaseKeysGuideAnimation(isDarkMode: Boolean, isBangla: Boolean) {
    var activeScene by remember { mutableStateOf(0) }
    
    // Automatically cycle scenes every 4 seconds
    LaunchedEffect(Unit) {
        while (true) {
            kotlinx.coroutines.delay(4500)
            activeScene = (activeScene + 1) % 4
        }
    }
    
    Card(
        modifier = Modifier
            .fillMaxWidth()
            .padding(vertical = 4.dp),
        shape = RoundedCornerShape(16.dp),
        colors = CardDefaults.cardColors(
            containerColor = if (isDarkMode) Color.White.copy(alpha = 0.04f) else Color.Black.copy(alpha = 0.03f)
        ),
        border = BorderStroke(1.dp, if (isDarkMode) Color.White.copy(alpha = 0.1f) else Color.Black.copy(alpha = 0.08f))
    ) {
        Column(modifier = Modifier.padding(14.dp)) {
            // Header with Scene Selector Pills and Icon
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(6.dp)
                ) {
                    Icon(
                        imageVector = Icons.Default.VpnKey,
                        contentDescription = null,
                        tint = if (isDarkMode) Color(0xFFFFD700) else Color(0xFF4F46E5),
                        modifier = Modifier.size(14.dp)
                    )
                    Text(
                        text = if (isBangla) "কীভাবে সুপাবেস কী পাবেন?" else "HOW TO GET SUPABASE KEYS",
                        fontSize = 11.sp,
                        fontWeight = FontWeight.Bold,
                        color = if (isDarkMode) Color(0xFFFFD700) else Color(0xFF4F46E5),
                        letterSpacing = 0.5.sp
                    )
                }
                
                // Indicators
                Row(horizontalArrangement = Arrangement.spacedBy(4.dp)) {
                    for (i in 0 until 4) {
                        Box(
                            modifier = Modifier
                                .size(width = if (activeScene == i) 16.dp else 6.dp, height = 6.dp)
                                .clip(CircleShape)
                                .background(
                                    if (activeScene == i) {
                                        Color(0xFF6366F1)
                                    } else {
                                        (if (isDarkMode) Color.White.copy(alpha = 0.2f) else Color.Black.copy(alpha = 0.15f))
                                    }
                                )
                                .clickable { activeScene = i }
                        )
                    }
                }
            }
            
            Spacer(modifier = Modifier.height(10.dp))
            
            // Pulsing animation for pointers to simulate clicking/copying
            val infiniteTransition = rememberInfiniteTransition(label = "pulse")
            val pulseScale by infiniteTransition.animateFloat(
                initialValue = 0.8f,
                targetValue = 1.3f,
                animationSpec = infiniteRepeatable(
                    animation = tween(1000, easing = FastOutSlowInEasing),
                    repeatMode = RepeatMode.Reverse
                ),
                label = "scale"
            )
            val pulseAlpha by infiniteTransition.animateFloat(
                initialValue = 0.8f,
                targetValue = 0.2f,
                animationSpec = infiniteRepeatable(
                    animation = tween(1000, easing = FastOutSlowInEasing),
                    repeatMode = RepeatMode.Reverse
                ),
                label = "alpha"
            )

            // The Simulated UI Mockup Browser Box
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .height(130.dp)
                    .clip(RoundedCornerShape(12.dp))
                    .background(if (isDarkMode) Color(0xFF0F172A) else Color(0xFFF1F5F9))
                    .border(1.dp, if (isDarkMode) Color.White.copy(alpha = 0.08f) else Color.Black.copy(alpha = 0.08f), RoundedCornerShape(12.dp))
            ) {
                // Top Browser window bar with dots
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .height(24.dp)
                        .background(if (isDarkMode) Color(0xFF020617) else Color(0xFFE2E8F0))
                        .padding(horizontal = 8.dp),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(6.dp)
                ) {
                    Box(modifier = Modifier.size(6.dp).background(Color(0xFFEF4444), CircleShape))
                    Box(modifier = Modifier.size(6.dp).background(Color(0xFFF59E0B), CircleShape))
                    Box(modifier = Modifier.size(6.dp).background(Color(0xFF10B981), CircleShape))
                    Spacer(modifier = Modifier.width(6.dp))
                    Text(
                        text = "supabase.com/dashboard/project/ovhumjaaeh...",
                        color = if (isDarkMode) Color.White.copy(alpha = 0.4f) else Color.Black.copy(alpha = 0.4f),
                        fontSize = 9.sp,
                        fontFamily = FontFamily.Monospace
                    )
                }
                
                // Browser content
                Row(
                    modifier = Modifier
                        .fillMaxSize()
                        .padding(top = 24.dp)
                ) {
                    // Left sidebar
                    Column(
                        modifier = Modifier
                            .fillMaxHeight()
                            .width(44.dp)
                            .background(if (isDarkMode) Color(0xFF020617).copy(alpha = 0.5f) else Color(0xFFE2E8F0).copy(alpha = 0.5f))
                            .padding(vertical = 6.dp, horizontal = 4.dp),
                        verticalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        // Table/SQL Editor Mock
                        Icon(
                            imageVector = Icons.Default.GridOn,
                            contentDescription = null,
                            modifier = Modifier.size(10.dp).align(Alignment.CenterHorizontally),
                            tint = if (isDarkMode) Color.White.copy(alpha = 0.3f) else Color.Black.copy(alpha = 0.3f)
                        )
                        Icon(
                            imageVector = Icons.Default.Terminal,
                            contentDescription = null,
                            modifier = Modifier.size(10.dp).align(Alignment.CenterHorizontally),
                            tint = if (isDarkMode) Color.White.copy(alpha = 0.3f) else Color.Black.copy(alpha = 0.3f)
                        )
                        Icon(
                            imageVector = Icons.Default.Storage,
                            contentDescription = null,
                            modifier = Modifier.size(10.dp).align(Alignment.CenterHorizontally),
                            tint = if (isDarkMode) Color.White.copy(alpha = 0.3f) else Color.Black.copy(alpha = 0.3f)
                        )

                        Spacer(modifier = Modifier.weight(1f))

                        // Project Settings Cog (Step 1 highlight)
                        val cogHighlighted = activeScene == 1
                        Box(
                            modifier = Modifier
                                .fillMaxWidth()
                                .height(18.dp)
                                .clip(RoundedCornerShape(4.dp))
                                .background(
                                    if (cogHighlighted) Color(0xFF10B981).copy(alpha = 0.2f) else Color.Transparent
                                )
                                .border(
                                    1.dp,
                                    if (cogHighlighted) Color(0xFF10B981) else Color.Transparent,
                                    RoundedCornerShape(4.dp)
                                ),
