                ) {
                    Column(modifier = Modifier.padding(20.dp)) {
                        Row(verticalAlignment = Alignment.CenterVertically) {
                            Icon(imageVector = Icons.Default.Settings, contentDescription = null, tint = BrandPurple, modifier = Modifier.size(24.dp))
                            Spacer(modifier = Modifier.width(10.dp))
                            Column {
                                Text(
                                    text = if (isBangla) "ফায়ারবেস ক্লাউড প্রজেক্ট কনফিগারেশন" else "Firebase Cloud Project Setup",
                                    fontWeight = FontWeight.Bold,
                                    fontSize = 16.sp,
                                    color = textPrimary
                                )
                                Text(
                                    text = if (isBangla) "আপনার প্রোডাকশন ফায়ারবেস ক্রেডেনশিয়াল ও রিয়েলটাইম ডাটাবেস URL প্রদান করুন।" else "Manage active Firebase Web API key, Project ID, Realtime DB URL, and Cloud Messaging sender ID.",
                                    fontSize = 11.sp,
                                    color = textSecondary
                                )
                            }
                        }

                        Spacer(modifier = Modifier.height(16.dp))

                        OutlinedTextField(
                            value = apiKeyInput,
                            onValueChange = { apiKeyInput = it },
                            label = { Text("Web API Key") },
                            placeholder = { Text("AIzaSy...") },
                            modifier = Modifier.fillMaxWidth(),
                            shape = RoundedCornerShape(12.dp)
                        )
                        Spacer(modifier = Modifier.height(10.dp))

                        OutlinedTextField(
                            value = projectIdInput,
                            onValueChange = { projectIdInput = it },
                            label = { Text("Firebase Project ID") },
                            placeholder = { Text("e.g. swapnopay-enterprise") },
                            modifier = Modifier.fillMaxWidth(),
                            shape = RoundedCornerShape(12.dp)
                        )
                        Spacer(modifier = Modifier.height(10.dp))

                        OutlinedTextField(
                            value = rtdbUrlInput,
                            onValueChange = { rtdbUrlInput = it },
                            label = { Text("Realtime Database URL") },
                            placeholder = { Text("https://your-app.firebaseio.com") },
                            modifier = Modifier.fillMaxWidth(),
                            shape = RoundedCornerShape(12.dp)
                        )
                        Spacer(modifier = Modifier.height(10.dp))

                        OutlinedTextField(
                            value = senderIdInput,
                            onValueChange = { senderIdInput = it },
                            label = { Text("Messaging Sender ID") },
                            placeholder = { Text("e.g. 108493029482") },
                            modifier = Modifier.fillMaxWidth(),
                            shape = RoundedCornerShape(12.dp)
                        )

                        Spacer(modifier = Modifier.height(16.dp))

                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.spacedBy(10.dp)
                        ) {
                            OutlinedButton(
                                onClick = {
                                    apiKeyInput = viewModel.firebaseApiKey.value
                                    projectIdInput = viewModel.firebaseProjectId.value
                                    rtdbUrlInput = ""
                                    senderIdInput = ""
                                },
                                shape = RoundedCornerShape(12.dp),
                                modifier = Modifier.weight(1f)
                            ) {
                                Icon(imageVector = Icons.Default.AutoFixHigh, contentDescription = null, modifier = Modifier.size(16.dp))
                                Spacer(modifier = Modifier.width(6.dp))
                                Text("Preset Config", fontSize = 11.sp)
                            }

                            Button(
                                onClick = {
                                    if (apiKeyInput.isNotEmpty() && projectIdInput.isNotEmpty()) {
                                        viewModel.setFirebaseConfig(apiKeyInput, projectIdInput)
                                        viewModel.logFirebaseStatus("Updated Firebase Project Config: $projectIdInput")
                                        android.widget.Toast.makeText(context, "Credentials Saved!", android.widget.Toast.LENGTH_SHORT).show()
                                    }
                                },
                                colors = ButtonDefaults.buttonColors(containerColor = BrandPurple),
                                shape = RoundedCornerShape(12.dp),
                                modifier = Modifier.weight(1.2f)
                            ) {
                                Icon(imageVector = Icons.Default.Check, contentDescription = null, modifier = Modifier.size(16.dp))
                                Spacer(modifier = Modifier.width(6.dp))
                                Text("Save Credentials", fontSize = 11.sp, color = Color.White, fontWeight = FontWeight.Bold)
                            }
                        }
                    }
                }
            }

            // Section 4: Real-time Telemetry & Logs Console
            if (selectedSection == "LOGS") {
                Card(
                    shape = RoundedCornerShape(24.dp),
                    colors = CardDefaults.cardColors(containerColor = cardBg),
                    elevation = CardDefaults.cardElevation(defaultElevation = 2.dp),
                    modifier = Modifier.fillMaxWidth()
                ) {
                    Column(modifier = Modifier.padding(20.dp)) {
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.SpaceBetween,
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            Row(verticalAlignment = Alignment.CenterVertically) {
                                Icon(imageVector = Icons.Default.Analytics, contentDescription = null, tint = BrandPurple, modifier = Modifier.size(24.dp))
                                Spacer(modifier = Modifier.width(10.dp))
                                Column {
                                    Text(
                                        text = if (isBangla) "ফায়ারবেস ইভেন্ট ও নোটিফিকেশন লগ" else "Telemetry & FCM Stream Logs",
                                        fontWeight = FontWeight.Bold,
                                        fontSize = 16.sp,
                                        color = textPrimary
                                    )
                                    Text(
                                        text = "Real-time stream of notices, FCM events, and Auth status",
                                        fontSize = 11.sp,
                                        color = textSecondary
                                    )
                                }
                            }

                            IconButton(
                                onClick = { viewModel.logFirebaseStatus("Telemetry log refreshed.") }
                            ) {
                                Icon(imageVector = Icons.Default.Refresh, contentDescription = "Refresh", tint = BrandPurple)
                            }
                        }

                        Spacer(modifier = Modifier.height(14.dp))

                        if (firebaseLogs.isEmpty()) {
                            Box(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .height(120.dp)
                                    .background(if (isDarkMode) Color(0xFF262838) else Color(0xFFF1F5F9), RoundedCornerShape(12.dp)),
                                contentAlignment = Alignment.Center
                            ) {
                                Text("No telemetry events recorded yet.", fontSize = 12.sp, color = textSecondary)
                            }
                        } else {
                            Column(
                                verticalArrangement = Arrangement.spacedBy(6.dp),
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .heightIn(max = 350.dp)
                                    .verticalScroll(rememberScrollState())
                            ) {
                                firebaseLogs.forEach { log ->
                                    Row(
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .background(if (isDarkMode) Color(0xFF262838) else Color(0xFFF8F9FA), RoundedCornerShape(8.dp))
                                            .padding(10.dp),
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        Icon(
                                            imageVector = when {
                                                log.contains("Notice") -> Icons.Default.Campaign
                                                log.contains("FCM") -> Icons.Default.CloudSync
                                                log.contains("Auth") -> Icons.Default.Lock
                                                else -> Icons.Default.Info
                                            },
                                            contentDescription = null,
                                            tint = when {
                                                log.contains("Notice") -> Color(0xFFD97706)
                                                log.contains("FCM") -> Color(0xFF10B981)
                                                log.contains("Auth") -> BrandPurple
                                                else -> Color(0xFF3B82F6)
                                            },
                                            modifier = Modifier.size(16.dp)
                                        )
                                        Spacer(modifier = Modifier.width(8.dp))
                                        Text(
                                            text = log,
                                            fontSize = 10.5.sp,
                                            fontFamily = FontFamily.Monospace,
                                            color = textPrimary
                                        )
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}
}

// 5. Main Application Layout (App Frame)
@Composable
fun MainAppFrame(viewModel: AppViewModel) {
    val activeTab by viewModel.currentTab.collectAsState()
    val activeProfile by viewModel.activeProfile.collectAsState()
    var showProfileDropdown by remember { mutableStateOf(false) }
    val isDarkMode by viewModel.isDarkMode.collectAsState()

    Scaffold(
        containerColor = if (isDarkMode) Color(0xFF111319) else Color(0xFFF8F9FD),
        topBar = {},
        bottomBar = {
            BottomNavigationBar(
                viewModel = viewModel,
                activeTab = activeTab,
                onTabSelected = { tab -> viewModel.setTab(tab) },
                onFabClick = { viewModel.navigateTo("PaymentForms") }
            )
        }
    ) { innerPadding ->
        Box(
            modifier = Modifier
                .fillMaxSize()
                .background(if (isDarkMode) Color(0xFF111319) else Color(0xFFF8F9FD))
        ) {
            Box(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(
                        top = if (activeTab == "Dashboard" || activeTab == "More" || activeTab == "Setup" || activeTab == "Forms" || activeTab == "AiCopilot" || activeTab == "Transactions") 0.dp else innerPadding.calculateTopPadding(),
                        bottom = innerPadding.calculateBottomPadding()
                    )
            ) {
                when (activeTab) {
                    "Dashboard" -> DashboardScreen(viewModel)
                    "Transactions" -> TransactionLedgerScreen(viewModel)
                    "Forms" -> PaymentFormsScreen(viewModel)
                    "Setup" -> SetupScreen(viewModel)
                    "More" -> MoreScreen(viewModel)
                    "AiCopilot" -> AiCopilotScreen(viewModel)
                }

            }
        }
    }
}

