                                    val width = size.width
                                    val height = size.height
                                    if (sparklinePoints.size >= 2) {
                                        val stepX = width / (sparklinePoints.size - 1)
                                        val path = Path().apply {
                                            moveTo(0f, height - (sparklinePoints[0] * height))
                                            for (i in 1 until sparklinePoints.size) {
                                                val x = i * stepX
                                                val y = height - (sparklinePoints[i] * height)
                                                val prevX = (i - 1) * stepX
                                                val prevY = height - (sparklinePoints[i - 1] * height)
                                                cubicTo(
                                                    prevX + stepX / 2f, prevY,
                                                    x - stepX / 2f, y,
                                                    x, y
                                                )
                                            }
                                        }
                                        val fillPath = Path().apply {
                                            addPath(path)
                                            lineTo(width, height)
                                            lineTo(0f, height)
                                            close()
                                        }
                                        
