                        Spacer(modifier = Modifier.height(16.dp))
                        
                        val chartPoints = listOf(12000.0, 18500.0, 15000.0, 24000.0, 21000.0, 31000.0, 28000.0)
                        val maxVal = chartPoints.maxOrNull() ?: 1.0
                        
                        Box(
                            modifier = Modifier
                                .fillMaxWidth()
                                .height(120.dp)
                        ) {
                            Canvas(modifier = Modifier.fillMaxSize()) {
                                val w = size.width
                                val h = size.height
                                val stepX = w / (chartPoints.size - 1)
                                
                                val path = Path()
                                val fillPath = Path()
                                
                                val points = chartPoints.mapIndexed { idx, value ->
                                    val x = idx * stepX
                                    val y = h - ((value / maxVal) * (h * 0.75f)).toFloat() - (h * 0.1f).toFloat()
                                    Offset(x, y)
                                }
                                
                                path.moveTo(points[0].x, points[0].y)
                                for (i in 0 until points.size - 1) {
                                    val p0 = points[i]
                                    val p1 = points[i + 1]
                                    val cpX1 = p0.x + (p1.x - p0.x) / 2f
                                    val cpY1 = p0.y
                                    val cpX2 = p0.x + (p1.x - p0.x) / 2f
                                    val cpY2 = p1.y
                                    path.cubicTo(cpX1, cpY1, cpX2, cpY2, p1.x, p1.y)
                                }
                                
