// 7. SETUP SCREEN (SUPABASE BACKEND SETUP)
@Composable
fun SetupScreen(viewModel: AppViewModel) {
    val languageState by viewModel.language.collectAsState()
    val isBangla = languageState == "bn" || languageState == "Bangla"
    val supabaseUrl by viewModel.supabaseUrl.collectAsState()
    val supabaseAnonKey by viewModel.supabaseAnonKey.collectAsState()
    val supabaseConnectionName by viewModel.supabaseConnectionName.collectAsState()
    val supabaseConnected by viewModel.supabaseConnected.collectAsState()
    val supabaseSetupProgress by viewModel.supabaseSetupProgress.collectAsState()
    val isRunningSystemTest by viewModel.isRunningSystemTest.collectAsState()
    val systemTestError by viewModel.systemTestError.collectAsState()
    val systemTestSuccess by viewModel.systemTestSuccess.collectAsState()
    val systemTestSuccessTrigger by viewModel.systemTestSuccessTrigger.collectAsState()

    val step3SqlState by viewModel.step3SqlState.collectAsState()
    val step2EmailAuth by viewModel.step2EmailAuth.collectAsState()
    val step6CreatedBucket by viewModel.step6CreatedBucket.collectAsState()
    val step4CliState by viewModel.step4CliState.collectAsState()
    val step5HookState by viewModel.step5HookState.collectAsState()
    val supabaseUrlInput by viewModel.supabaseUrlInput.collectAsState()
    val supabaseAnonKeyInput by viewModel.supabaseAnonKeyInput.collectAsState()

    val isStep1Completed = supabaseUrl.isNotEmpty() && supabaseAnonKey.isNotEmpty() || (supabaseUrlInput.isNotEmpty() && supabaseAnonKeyInput.isNotEmpty())
    val isStep2Completed = step3SqlState == "DONE" || supabaseConnected
    val isStep3Completed = step2EmailAuth || supabaseConnected
    val isStep4Completed = step6CreatedBucket || supabaseConnected
    val isStep5Completed = step4CliState == "DONE" || supabaseConnected
    val isStep6Completed = step3SqlState == "DONE" || supabaseConnected
    val isStep7Completed = step5HookState == "DONE" || supabaseConnected
    val isStep8Completed = supabaseUrl.isNotEmpty() && supabaseAnonKey.isNotEmpty() || (supabaseUrlInput.isNotEmpty() && supabaseAnonKeyInput.isNotEmpty())
    val isStep9Completed = supabaseSetupProgress == 9

    val dynamicSetupProgress = remember(
        supabaseConnected,
        isStep1Completed,
        isStep2Completed,
        isStep3Completed,
        isStep4Completed,
        isStep5Completed,
        isStep6Completed,
        isStep7Completed,
        isStep8Completed,
        supabaseSetupProgress
    ) {
        if (supabaseConnected || supabaseSetupProgress == 9) 9
        else {
            var completedCount = 0
            if (isStep1Completed) completedCount++
            if (isStep2Completed) completedCount++
            if (isStep3Completed) completedCount++
            if (isStep4Completed) completedCount++
            if (isStep5Completed) completedCount++
            if (isStep6Completed) completedCount++
            if (isStep7Completed) completedCount++
            if (isStep8Completed) completedCount++
            completedCount
        }
    }

    val isDarkMode by viewModel.isDarkMode.collectAsState()
    val setupContext = androidx.compose.ui.platform.LocalContext.current

    var showHelpDialog by remember { mutableStateOf(false) }

    // Input fields (for when editing connection)
    var urlInput by remember { mutableStateOf(supabaseUrl) }
    var anonKeyInput by remember { mutableStateOf(supabaseAnonKey) }
    var connectionNameInput by remember { mutableStateOf(supabaseConnectionName) }
    var isPasswordVisible by remember { mutableStateOf(false) }
    var useSecureProxyMode by remember { mutableStateOf(false) }

    // Video guide state
    var showVideoDialog by remember { mutableStateOf(false) }

    // Sync input state if they change in viewModel
    LaunchedEffect(supabaseUrl, supabaseAnonKey, supabaseConnectionName) {
        urlInput = supabaseUrl
        anonKeyInput = supabaseAnonKey
        connectionNameInput = supabaseConnectionName
    }

    LaunchedEffect(systemTestSuccess, systemTestError) {
        if (systemTestSuccess) {
            android.widget.Toast.makeText(setupContext, "Connected to Supabase successfully!", android.widget.Toast.LENGTH_SHORT).show()
        } else if (!systemTestError.isNullOrBlank()) {
            android.widget.Toast.makeText(setupContext, "Connection error: $systemTestError", android.widget.Toast.LENGTH_LONG).show()
        }
    }

    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(if (isDarkMode) Color(0xFF111319) else Color(0xFFF3F4F6))
    ) {
        Column(
            modifier = Modifier.fillMaxSize()
        ) {
            // Header Navigation (Sticky top)
            Surface(
                color = if (isDarkMode) Color(0xFF1E1F26) else Color.White,
                shadowElevation = 2.dp,
                modifier = Modifier.fillMaxWidth()
            ) {
                Row(
                    modifier = Modifier
                        .statusBarsPadding()
                        .fillMaxWidth()
                        .padding(horizontal = 16.dp, vertical = 14.dp),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    IconButton(
                        onClick = { viewModel.setTab("Dashboard") },
                        modifier = Modifier.size(36.dp)
                    ) {
                        Icon(
                            imageVector = Icons.AutoMirrored.Filled.ArrowBack,
                            contentDescription = "Back to Dashboard",
                            tint = if (isDarkMode) Color.White else Color(0xFF111827)
                        )
                    }

                    Text(
                        text = t("Supabase Setup", languageState),
                        fontSize = 17.sp,
                        fontWeight = FontWeight.Bold,
                        color = if (isDarkMode) Color.White else Color(0xFF111827)
                    )

                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        // Open Cloud Browser Button
                        Button(
                            onClick = {
                                val intent = android.content.Intent(
                                    android.content.Intent.ACTION_VIEW,
                                    android.net.Uri.parse("https://supabase.com/dashboard")
                                )
                                try {
                                    setupContext.startActivity(intent)
                                } catch (_: android.content.ActivityNotFoundException) {
                                    android.widget.Toast.makeText(
