                                )
                                Divider(color = AppDividerColor, thickness = 1.dp, modifier = Modifier.padding(horizontal = 16.dp))

                                ChecklistItemRow(
                                    step = "7",
                                    title = "Realtime",
                                    desc = "Enable realtime for required tables",
                                    icon = Icons.Default.Radio,
                                    iconColor = Color(0xFFE11D48),
                                    bgColor = Color(0xFFFFF1F2),
                                    isCompleted = isStep7Completed,
                                    onItemClick = {
                                        viewModel.setWizardStep(5)
                                        viewModel.navigateTo("SupabaseSetupGuide")
                                    }
                                )
                                Divider(color = AppDividerColor, thickness = 1.dp, modifier = Modifier.padding(horizontal = 16.dp))

                                ChecklistItemRow(
                                    step = "8",
                                    title = "Environment Variables",
                                    desc = "Set environment variables & secrets",
                                    icon = Icons.Default.Key,
                                    iconColor = Color(0xFFEA580C),
                                    bgColor = Color(0xFFFFF7ED),
                                    isCompleted = isStep8Completed,
                                    onItemClick = {
                                        viewModel.setWizardStep(1)
                                        viewModel.navigateTo("SupabaseSetupGuide")
                                    }
                                )
                                Divider(color = AppDividerColor, thickness = 1.dp, modifier = Modifier.padding(horizontal = 16.dp))

                                ChecklistItemRow(
                                    step = "9",
                                    title = "Test & Finalize",
                                    desc = "Run system test and finalize setup",
                                    icon = Icons.Default.Science,
                                    iconColor = if (isStep9Completed) Color(0xFF059669) else Color(0xFF64748B),
                                    bgColor = if (isStep9Completed) Color(0xFFECFDF5) else Color(0xFFF1F5F9),
                                    isCompleted = isStep9Completed,
                                    onItemClick = {
                                        if (supabaseConnected) {
                                            viewModel.runSupabaseSystemTest()
                                        } else {
                                            viewModel.setWizardStep(7)
                                            viewModel.navigateTo("SupabaseSetupGuide")
                                        }
                                    }
                                )
                            }
                        }
                    }

                    // System Status Card
                    item {
                        Card(
                            shape = RoundedCornerShape(24.dp),
                            colors = CardDefaults.cardColors(containerColor = AppCardBg),
                            border = BorderStroke(1.dp, AppCardBorderColor),
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            Column(
                                modifier = Modifier.padding(20.dp)
                            ) {
                                Text(
                                    text = "System Status",
                                    fontWeight = FontWeight.Bold,
                                    fontSize = 15.sp,
                                    color = AppTextPrimary,
                                    modifier = Modifier.padding(bottom = 12.dp)
                                )

                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.spacedBy(8.dp)
                                ) {
                                    val isApiOk = if (systemTestError != null) false else (supabaseConnected || systemTestSuccess)
                                    val isDbOk = if (systemTestError != null) false else (supabaseConnected || systemTestSuccess)
                                    
                                    // Status Item: API
                                    StatusGridCell(
                                        modifier = Modifier.weight(1f),
                                        label = "API",
                                        status = if (isRunningSystemTest) "Testing" else if (systemTestError != null) "Error" else if (supabaseConnected) "Healthy" else "Unverified",
                                        icon = Icons.Default.ArrowUpward,
                                        isOk = isApiOk
                                    )
                                    // Status Item: Database
                                    StatusGridCell(
                                        modifier = Modifier.weight(1f),
                                        label = "Database",
                                        status = if (isRunningSystemTest) "Testing" else if (systemTestError != null) "Failed" else if (supabaseConnected) "Healthy" else "Unverified",
                                        icon = Icons.Default.Storage,
                                        isOk = isDbOk
                                    )
                                    // Status Item: Functions
                                    StatusGridCell(
                                        modifier = Modifier.weight(1f),
                                        label = "Functions",
                                        status = if (isRunningSystemTest) "Testing" else if (systemTestError != null) "Offline" else "Deployed",
                                        icon = Icons.Default.Bolt,
                                        isOk = isDbOk
                                    )
                                    // Status Item: Realtime
                                    StatusGridCell(
                                        modifier = Modifier.weight(1f),
                                        label = "Realtime",
                                        status = if (isRunningSystemTest) "Testing" else if (systemTestError != null) "Disabled" else "Enabled",
                                        icon = Icons.Default.Radio,
                                        isOk = isDbOk
                                    )
                                }

                                // ERROR DISPLAY CARD IF SYSTEM TEST FAILS
                                AnimatedVisibility(visible = systemTestError != null) {
                                    Column {
                                        Spacer(modifier = Modifier.height(12.dp))
                                        Card(
                                            shape = RoundedCornerShape(16.dp),
                                            colors = CardDefaults.cardColors(containerColor = Color(0xFFFEF2F2)),
                                            border = BorderStroke(1.dp, Color(0xFFFCA5A5)),
                                            modifier = Modifier.fillMaxWidth()
                                        ) {
                                            Row(
                                                modifier = Modifier.padding(14.dp),
                                                verticalAlignment = Alignment.Top
                                            ) {
                                                Icon(
                                                    imageVector = Icons.Default.ErrorOutline,
                                                    contentDescription = null,
                                                    tint = Color(0xFFEF4444),
                                                    modifier = Modifier.size(24.dp).padding(top = 2.dp)
                                                )
                                                Spacer(modifier = Modifier.width(10.dp))
                                                Column {
                                                    Text(
                                                        text = "System Test Verification Failed",
                                                        fontWeight = FontWeight.Bold,
                                                        fontSize = 14.sp,
                                                        color = Color(0xFF991B1B)
                                                    )
                                                    Spacer(modifier = Modifier.height(2.dp))
                                                    Text(
                                                        text = systemTestError ?: "Unknown credentials error.",
                                                        fontSize = 12.sp,
                                                        color = Color(0xFFB91C1C)
                                                    )
                                                }
                                            }
                                        }
                                    }
                                }

                                // SUCCESS ANIMATION IF SYSTEM TEST PASSED
                                AnimatedVisibility(visible = systemTestSuccess) {
                                    Column {
                                        Spacer(modifier = Modifier.height(12.dp))
                                        SystemTestSuccessAnimation(trigger = systemTestSuccessTrigger)
                                    }
                                }

                                Spacer(modifier = Modifier.height(16.dp))

                                // Run System Test Button
                                val buttonBgColor = when {
                                    isRunningSystemTest -> Color(0xFF6B7280)
                                    systemTestError != null -> Color(0xFFEF4444)
                                    systemTestSuccess -> Color(0xFF10B981)
                                    else -> Color(0xFF10B981)
                                }

                                Button(
                                    onClick = { viewModel.runSupabaseSystemTest() },
                                    colors = ButtonDefaults.buttonColors(containerColor = buttonBgColor),
                                    shape = RoundedCornerShape(16.dp),
                                    enabled = !isRunningSystemTest,
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .height(54.dp)
                                ) {
                                    if (isRunningSystemTest) {
                                        CircularProgressIndicator(color = Color.White, modifier = Modifier.size(20.dp))
                                        Spacer(modifier = Modifier.width(8.dp))
                                        Text("Testing Backend...", fontWeight = FontWeight.Bold, fontSize = 15.sp)
                                    } else {
                                        val btnIcon = when {
                                            systemTestError != null -> Icons.Default.Refresh
                                            systemTestSuccess -> Icons.Default.CheckCircle
                                            else -> Icons.Default.Science
                                        }
                                        val btnText = when {
                                            systemTestError != null -> "Retry System Test"
                                            systemTestSuccess -> "System Verified - Re-Run Test"
                                            else -> "Run System Test"
                                        }
                                        Icon(imageVector = btnIcon, contentDescription = null, modifier = Modifier.size(18.dp))
                                        Spacer(modifier = Modifier.width(8.dp))
                                        Text(
                                            text = btnText,
                                            fontWeight = FontWeight.Bold,
                                            fontSize = 15.sp
                                        )
                                    }
                                }

                                Spacer(modifier = Modifier.height(12.dp))

                                // RESET/DISCONNECT BUTTON
                                OutlinedButton(
                                    onClick = { viewModel.disconnectSupabase() },
                                    colors = ButtonDefaults.outlinedButtonColors(contentColor = Color(0xFFEF4444)),
                                    border = BorderStroke(1.dp, Color(0xFFEF4444).copy(alpha = 0.3f)),
                                    shape = RoundedCornerShape(16.dp),
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .height(48.dp)
                                ) {
                                    Text("Disconnect Project", fontWeight = FontWeight.SemiBold, fontSize = 14.sp)
                                }
                            }
                        }
                    }
                }

                // HELP CARD (Always at the bottom)
                item {
                    Card(
                        shape = RoundedCornerShape(24.dp),
                        colors = CardDefaults.cardColors(containerColor = AppCardBg),
                        border = BorderStroke(1.dp, AppCardBorderColor),
                        modifier = Modifier
                            .fillMaxWidth()
                            .clickable { viewModel.navigateTo("SupabaseSetupGuide") }
                    ) {
                        Row(
                            modifier = Modifier.padding(16.dp),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Row(
                                modifier = Modifier.weight(1f),
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.spacedBy(16.dp)
                            ) {
                                Box(
                                    modifier = Modifier
                                        .size(44.dp)
                                        .background(if (isDarkModeGlobal) Color(0xFF1E1F26) else Color(0xFFF9FAFB), RoundedCornerShape(12.dp))
                                        .border(BorderStroke(1.dp, AppCardBorderColor), RoundedCornerShape(12.dp)),
                                    contentAlignment = Alignment.Center
                                ) {
                                    Icon(
                                        imageVector = Icons.Default.Headset,
                                        contentDescription = null,
                                        tint = AppTextPrimary,
                                        modifier = Modifier.size(22.dp)
                                    )
                                }

                                Column(modifier = Modifier.weight(1f)) {
                                    Text(
                                        text = "Need Help?",
                                        fontWeight = FontWeight.Bold,
                                        fontSize = 14.sp,
                                        color = AppTextPrimary
                                    )
                                    Spacer(modifier = Modifier.height(2.dp))
                                    Text(
                                        text = "Watch our step-by-step guide on how to create and configure a Supabase project.",
                                        fontSize = 11.sp,
                                        color = AppTextSecondary,
                                        lineHeight = 14.sp
                                    )
                                }
                            }
                            Icon(
                                imageVector = Icons.Default.ChevronRight,
                                contentDescription = null,
                                tint = AppTextSecondary,
                                modifier = Modifier.size(16.dp)
                            )
                        }
                    }
                }
            }
        }

        // --- Dialogs ---

        // Supabase Setup Help Dialog
        if (showHelpDialog) {
            EnterpriseGestureModal(
                onDismissRequest = { showHelpDialog = false },
                title = "Supabase Connection Guide",
                subtitle = "Swipe down or drag handle to dismiss",
                icon = Icons.Default.HelpOutline
            ) {
                Column(
                    verticalArrangement = Arrangement.spacedBy(12.dp),
                    modifier = Modifier.fillMaxWidth()
                ) {
                    Text(
                        text = "To power your SwapnoPay bKash / Nagad automated logger, you need a backend database. Supabase provides a free Postgres database in under 2 minutes.",
                        fontSize = 13.sp,
                        color = AppTextSecondary,
                        lineHeight = 18.sp
                    )

                    Text(
                        text = "Setup Steps:",
                        fontWeight = FontWeight.Bold,
                        fontSize = 14.sp,
                        color = AppTextPrimary
                    )

                    StepHelpRow(number = "1", text = "Create a project on supabase.com")
                    StepHelpRow(number = "2", text = "Apply the production SQL migration and deploy the Edge Functions from this project")
                    StepHelpRow(number = "3", text = "Copy the Project URL and client-safe publishable/anon key from Project Settings > API")
                    StepHelpRow(number = "4", text = "Connect, authenticate, and run the system test to verify backend access")

                    Spacer(modifier = Modifier.height(12.dp))

                    Button(
                        onClick = { showHelpDialog = false },
                        colors = ButtonDefaults.buttonColors(containerColor = BrandPurple),
                        shape = RoundedCornerShape(12.dp),
                        modifier = Modifier.fillMaxWidth().height(48.dp)
                    ) {
                        Text("Got it", fontWeight = FontWeight.Bold, fontSize = 15.sp)
                    }
                }
            }
        }
    }
}

@Composable
fun SupabaseSetupGuideScreen(viewModel: AppViewModel) {
    val context = androidx.compose.ui.platform.LocalContext.current
    val scope = rememberCoroutineScope()
    val clipboardManager = androidx.compose.ui.platform.LocalClipboardManager.current

    // Steps: 0 to 6 (7 steps total)
    val currentStep by viewModel.currentWizardStep.collectAsState()
    val totalSteps = 7

    val supabaseUrlInput by viewModel.supabaseUrlInput.collectAsState()
    val supabaseAnonKeyInput by viewModel.supabaseAnonKeyInput.collectAsState()
    var showGraduationDialog by remember { mutableStateOf(false) }

    // Dynamic extraction of project reference ID
    val projectRef = remember(supabaseUrlInput) {
        if (supabaseUrlInput.startsWith("https://")) {
            supabaseUrlInput.removePrefix("https://").substringBefore(".")
        } else {
            supabaseUrlInput.substringBefore(".")
        }
    }.ifEmpty { "<YOUR_PROJECT_REF>" }

    val isDarkMode by viewModel.isDarkMode.collectAsState()
    SideEffect { isDarkModeGlobal = isDarkMode }
    val accentColor = when (currentStep) {
        0 -> Color(0xFF818CF8) // Indigo
        1 -> Color(0xFF0D9488) // Teal
        2 -> Color(0xFF8B5CF6) // Purple
        3 -> Color(0xFFF43F5E) // Rose
        4 -> Color(0xFFF97316) // Orange
        5 -> Color(0xFF3B82F6) // Blue
        6 -> Color(0xFFD946EF) // Fuchsia
        7 -> Color(0xFF10B981) // Emerald
        else -> Color(0xFF818CF8)
    }

    val animatedTopColor by androidx.compose.animation.animateColorAsState(targetValue = accentColor, animationSpec = tween(500))

    // Background gradient: black/dark if dark mode, white/light if light mode
    val bgTopColor = if (isDarkMode) Color(0xFF111319) else Color(0xFFFFFFFF)
    val bgBottomColor = if (isDarkMode) Color(0xFF000000) else Color(0xFFF3F4F6)
    val animatedBgTopColor by androidx.compose.animation.animateColorAsState(targetValue = bgTopColor, animationSpec = tween(500))
    val animatedBgBottomColor by androidx.compose.animation.animateColorAsState(targetValue = bgBottomColor, animationSpec = tween(500))
    val gradientBrush = Brush.verticalGradient(colors = listOf(animatedBgTopColor, animatedBgBottomColor))

    // Mascot animations (floating, bouncing!)
    val infiniteTransition = rememberInfiniteTransition(label = "SmartyMotion")
    val bounceOffset by infiniteTransition.animateFloat(
        initialValue = 0f,
        targetValue = -12f,
        animationSpec = infiniteRepeatable(
            animation = tween(1100, easing = FastOutSlowInEasing),
            repeatMode = RepeatMode.Reverse
        ),
        label = "MascotBounce"
    )
    val wiggleAngle by infiniteTransition.animateFloat(
        initialValue = -3f,
        targetValue = 3f,
        animationSpec = infiniteRepeatable(
            animation = tween(1300, easing = LinearOutSlowInEasing),
            repeatMode = RepeatMode.Reverse
        ),
        label = "MascotWiggle"
    )
    val pulseScale by infiniteTransition.animateFloat(
        initialValue = 0.8f,
        targetValue = 1.4f,
        animationSpec = infiniteRepeatable(
            animation = tween(1800, easing = LinearEasing),
            repeatMode = RepeatMode.Restart
        ),
        label = "PulseScale"
    )
    val pulseAlpha by infiniteTransition.animateFloat(
        initialValue = 0.6f,
        targetValue = 0.0f,
        animationSpec = infiniteRepeatable(
            animation = tween(1800, easing = LinearEasing),
            repeatMode = RepeatMode.Restart
        ),
        label = "PulseAlpha"
    )
    val rotationAngle by infiniteTransition.animateFloat(
        initialValue = 0f,
        targetValue = 360f,
        animationSpec = infiniteRepeatable(
            animation = tween(4000, easing = LinearEasing),
            repeatMode = RepeatMode.Restart
        ),
        label = "RotateGlow"
    )

    // Interactive simulator states connected to ViewModel
    val step1ProvisionState by viewModel.step1ProvisionState.collectAsState()
    val step1Progress by viewModel.step1Progress.collectAsState()
    val step1Logs by viewModel.step1Logs.collectAsState()

    val step2EmailAuth by viewModel.step2EmailAuth.collectAsState()
    val step2GoogleAuth by viewModel.step2GoogleAuth.collectAsState()

    val step3SqlState by viewModel.step3SqlState.collectAsState()
    val step3Progress by viewModel.step3Progress.collectAsState()
    val step3Logs by viewModel.step3Logs.collectAsState()

    val step4CliState by viewModel.step4CliState.collectAsState()
    val step4Progress by viewModel.step4Progress.collectAsState()
    val step4Logs by viewModel.step4Logs.collectAsState()

    val step5HookState by viewModel.step5HookState.collectAsState()
    val step5Progress by viewModel.step5Progress.collectAsState()
    val step5Logs by viewModel.step5Logs.collectAsState()

    val step6CreatedBucket by viewModel.step6CreatedBucket.collectAsState()

    val bubbleText = viewModel.mascotSpeeches.getOrDefault(currentStep, "All systems live! 🥳")

    Scaffold(
        modifier = Modifier.fillMaxSize(),
        bottomBar = {
            Surface(
                color = if (isDarkModeGlobal) Color(0xFF1E202B) else Color.White,
                shadowElevation = 8.dp,
                modifier = Modifier.fillMaxWidth()
            ) {
                Row(
                    modifier = Modifier
                        .navigationBarsPadding()
                        .fillMaxWidth()
                        .padding(16.dp),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    if (currentStep > 0) {
                        Button(
                            onClick = { viewModel.setWizardStep(currentStep - 1) },
                            colors = ButtonDefaults.buttonColors(containerColor = if (isDarkModeGlobal) Color(0xFF374151) else Color(0xFFE5E7EB)),
                            shape = RoundedCornerShape(14.dp),
                            modifier = Modifier
                                .height(48.dp)
                                .weight(0.4f)
                        ) {
                            Text("Back", color = if (isDarkModeGlobal) Color.White else Color.DarkGray, fontWeight = FontWeight.Bold)
                        }
                        Spacer(modifier = Modifier.width(12.dp))
                    }

                    val buttonColor by androidx.compose.animation.animateColorAsState(
                        targetValue = if (currentStep == 1 && (supabaseUrlInput.isEmpty() || supabaseAnonKeyInput.isEmpty())) Color.Gray else accentColor,
                        animationSpec = tween(500)
                    )

                    Button(
                        onClick = {
                            if (currentStep < totalSteps - 1) {
                                if (currentStep == 1 && (supabaseUrlInput.isEmpty() || supabaseAnonKeyInput.isEmpty())) {
                                    android.widget.Toast.makeText(context, "Please enter your Supabase credentials first!", android.widget.Toast.LENGTH_SHORT).show()
                                } else {
                                    viewModel.setWizardStep(currentStep + 1)
                                }
                            } else {
                                if (supabaseUrlInput.isNotEmpty() && supabaseAnonKeyInput.isNotEmpty()) {
                                    viewModel.connectSupabase(
                                        url = supabaseUrlInput,
                                        anonKey = supabaseAnonKeyInput,
                                        name = "Self-Hosted Supabase Store"
                                    )
                                    viewModel.runSupabaseSystemTest()
                                    showGraduationDialog = true
                                } else {
                                    android.widget.Toast.makeText(context, "Please fill in URL and Anon Key!", android.widget.Toast.LENGTH_SHORT).show()
                                }
                            }
                        },
                        colors = ButtonDefaults.buttonColors(containerColor = buttonColor),
                        shape = RoundedCornerShape(14.dp),
                        modifier = Modifier
                            .height(48.dp)
                            .weight(0.6f)
                    ) {
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.Center
                        ) {
                            Text(
                                text = if (currentStep == totalSteps - 1) "Finalize & Connect" else "Continue to Step ${currentStep + 2}",
                                color = Color.White,
                                fontWeight = FontWeight.Bold,
                                fontSize = 14.sp
                            )
                            Spacer(modifier = Modifier.width(6.dp))
                            Icon(
                                imageVector = Icons.Default.ArrowForward,
                                contentDescription = null,
                                tint = Color.White,
                                modifier = Modifier.size(16.dp)
                            )
                        }
                    }
                }
            }
        }
    ) { innerPadding ->
        Box(
            modifier = Modifier
                .fillMaxSize()
                .background(gradientBrush)
                .padding(innerPadding)
        ) {
            Column(modifier = Modifier.fillMaxSize()) {
                // Header with Progress Bar
                Row(
                    modifier = Modifier
                        .statusBarsPadding()
                        .fillMaxWidth()
                        .padding(horizontal = 16.dp, vertical = 12.dp),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.SpaceBetween
                ) {
                    IconButton(
                        onClick = {
                            viewModel.setTab("Setup")
                            viewModel.navigateTo("Main")
                        }
                    ) {
                        Icon(
                            imageVector = Icons.Default.Close, 
                            contentDescription = "Close", 
                            tint = if (isDarkMode) Color.White else Color(0xFF111827)
                        )
                    }

                    Box(
                        modifier = Modifier
                            .weight(1f)
                            .height(16.dp)
                            .padding(horizontal = 12.dp)
                            .background(if (isDarkMode) Color.White.copy(alpha = 0.2f) else Color.Black.copy(alpha = 0.1f), RoundedCornerShape(8.dp))
                    ) {
                        val animatedProgress by animateFloatAsState(
                            targetValue = (currentStep + 1) / totalSteps.toFloat(),
                            animationSpec = spring(dampingRatio = Spring.DampingRatioMediumBouncy)
                        )
                        Box(
                            modifier = Modifier
                                .fillMaxWidth(animatedProgress)
                                .fillMaxHeight()
                                .background(
                                    Brush.horizontalGradient(
                                        colors = listOf(Color(0xFF3B82F6), Color(0xFF06B6D4))
                                    ),
                                    RoundedCornerShape(8.dp)
                                )
                        ) {
                            Box(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .height(3.dp)
                                    .background(Color.White.copy(alpha = 0.3f), RoundedCornerShape(topStart = 8.dp, topEnd = 8.dp))
                            )
                        }
                    }

                    Text(
                        text = "${currentStep + 1}/$totalSteps",
                        color = if (isDarkMode) Color.White else Color(0xFF111827),
                        fontWeight = FontWeight.Bold,
                        fontSize = 14.sp
                    )
                }

                // Scrollable wizard body
                Column(
                    modifier = Modifier
                        .fillMaxSize()
                        .verticalScroll(rememberScrollState())
                        .padding(horizontal = 20.dp, vertical = 8.dp),
                    horizontalAlignment = Alignment.CenterHorizontally
                ) {
                    // Merchant Assistant Speech Banner
                    Card(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(bottom = 20.dp),
                        shape = RoundedCornerShape(24.dp),
                        colors = CardDefaults.cardColors(
                            containerColor = if (isDarkMode) Color.Black.copy(alpha = 0.35f) else Color(0xFFF3F4F6)
                        ),
                        border = BorderStroke(1.5.dp, animatedTopColor.copy(alpha = 0.4f))
                    ) {
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(16.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            // Pulsating & Rotating High Graphic Avatar
                            Box(
                                modifier = Modifier.size(68.dp),
                                contentAlignment = Alignment.Center
                            ) {
                                // Pulsating Radar Aura
                                Box(
                                    modifier = Modifier
                                        .size(54.dp)
                                        .graphicsLayer {
                                            scaleX = pulseScale
                                            scaleY = pulseScale
                                            alpha = pulseAlpha
                                        }
                                        .background(
                                            brush = Brush.radialGradient(
                                                colors = listOf(animatedTopColor, Color.Transparent)
                                            ),
                                            shape = CircleShape
                                        )
                                )

                                // Rotating Gradient Ring
                                Box(
                                    modifier = Modifier
                                        .size(60.dp)
                                        .graphicsLayer {
                                            rotationZ = rotationAngle
                                        }
                                        .border(
                                            width = 2.dp,
                                            brush = Brush.sweepGradient(
                                                colors = listOf(animatedTopColor, Color(0xFF38BDF8), Color(0xFFF472B6), animatedTopColor)
                                            ),
                                            shape = CircleShape
                                        )
                  
                                )

                                // Character Avatar Circle
                                Box(
                                    modifier = Modifier
                                        .size(46.dp)
                                        .graphicsLayer {
                                            translationY = bounceOffset
                                            rotationZ = wiggleAngle
                                        }
                                        .shadow(4.dp, CircleShape)
                                        .background(
                                            Brush.linearGradient(
                                                colors = listOf(Color(0xFF1E293B), Color(0xFF0F172A))
                                            ),
                                            shape = CircleShape
                                        ),
                                    contentAlignment = Alignment.Center
                                ) {
                                    Text("🧑‍💻", fontSize = 24.sp)
                                }
                            }

                            Spacer(modifier = Modifier.width(16.dp))

                            Column(
                                modifier = Modifier.weight(1f)
                            ) {
                                Text(
                                    text = "MERCHANT ASSISTANT",
                                    color = animatedTopColor,
                                    fontSize = 10.sp,
                                    fontWeight = FontWeight.ExtraBold,
                                    letterSpacing = 1.5.sp
                                )
                                Spacer(modifier = Modifier.height(4.dp))
                                // Animated Text transition between step instructions
                                androidx.compose.animation.Crossfade(
                                    targetState = bubbleText,
                                    label = "TextAnimation"
                                ) { targetText ->
                                    Text(
                                        text = targetText,
                                        fontSize = 12.sp,
                                        fontWeight = FontWeight.Medium,
                                        color = Color.White.copy(alpha = 0.9f),
