                                            val legacyDevelopmentSchemaReference = """
                                                -- SwapnoPay Enterprise Database Schema (All Screens Connected)
                                                create extension if not exists "pgcrypto";

                                                -- 1. Merchant Profile
                                                create table if not exists merchant_profile (
                                                  id text primary key,
                                                  business_name text not null,
                                                  email text,
                                                  phone text,
                                                  business_type text,
                                                  website text,
                                                  primary_bank text,
                                                  account_holder text,
                                                  account_number text,
                                                  kyc_status text default 'UNVERIFIED',
                                                  photo_url text,
                                                  updated_at bigint default extract(epoch from now())::bigint
                                                );

                                                -- 2. Customers
                                                create table if not exists customers (
                                                  id text primary key,
                                                  merchant_id text default 'profile_1',
                                                  name text not null,
                                                  phone text not null,
                                                  email text,
                                                  address text,
                                                  opening_balance numeric(12,2) default 0,
                                                  current_balance numeric(12,2) default 0,
                                                  status text default 'VIP',
                                                  created_at bigint default extract(epoch from now())::bigint
                                                );

                                                -- 3. Suppliers
                                                create table if not exists suppliers (
                                                  id text primary key,
                                                  merchant_id text default 'profile_1',
                                                  name text not null,
                                                  phone text not null,
                                                  email text,
                                                  address text,
                                                  opening_balance numeric(12,2) default 0,
                                                  current_balance numeric(12,2) default 0,
                                                  created_at bigint default extract(epoch from now())::bigint
                                                );

                                                -- 4. Products & Inventory
                                                create table if not exists products (
                                                  id text primary key,
                                                  merchant_id text default 'profile_1',
                                                  name text not null,
                                                  code text,
                                                  category text default 'General',
                                                  purchase_price numeric(12,2) default 0,
                                                  sale_price numeric(12,2) default 0,
                                                  stock_quantity numeric(12,2) default 0,
                                                  min_stock_threshold numeric(12,2) default 5,
                                                  unit text default 'pcs',
                                                  qr_code text,
                                                  image_url text,
                                                  created_at bigint default extract(epoch from now())::bigint
                                                );

                                                -- 5. Product Variants
                                                create table if not exists product_variants (
                                                  id text primary key,
                                                  merchant_id text default 'profile_1',
                                                  product_id text references products(id) on delete cascade,
                                                  variant_name text not null,
                                                  supplier_id text,
                                                  qr_code text,
                                                  cost_price numeric(12,2) default 0,
                                                  asking_price numeric(12,2) default 0,
                                                  sale_price numeric(12,2) default 0,
                                                  stock_quantity numeric(12,2) default 0,
                                                  created_at bigint default extract(epoch from now())::bigint
                                                );

                                                -- 6. Stock Transactions
                                                create table if not exists stock_transactions (
                                                  id text primary key,
                                                  merchant_id text default 'profile_1',
                                                  product_id text not null,
                                                  type text not null,
                                                  quantity numeric(12,2) not null,
                                                  price numeric(12,2) default 0,
                                                  created_at bigint default extract(epoch from now())::bigint
                                                );

                                                -- 7. Ledger Transactions
                                                create table if not exists ledger_transactions (
                                                  id text primary key,
                                                  merchant_id text default 'profile_1',
                                                  customer_id text,
                                                  supplier_id text,
                                                  type text not null,
                                                  amount numeric(12,2) not null,
                                                  date bigint default extract(epoch from now())::bigint,
                                                  note text,
                                                  payment_method text default 'Cash',
                                                  invoice_no text
                                                );

                                                -- 8. POS Sales
                                                create table if not exists pos_sales (
                                                  id text primary key,
                                                  merchant_id text default 'profile_1',
                                                  invoice_no text not null,
                                                  customer_name text default 'Walk-in Customer',
                                                  customer_phone text default '',
                                                  subtotal numeric(12,2) not null,
                                                  discount numeric(12,2) default 0,
                                                  net_total numeric(12,2) not null,
                                                  cash_received numeric(12,2) default 0,
                                                  change_due numeric(12,2) default 0,
                                                  payment_method text default 'Cash',
                                                  payment_status text default 'PAID',
                                                  item_count integer default 1,
                                                  timestamp bigint default extract(epoch from now())::bigint
                                                );

                                                -- 9. Expenses
                                                create table if not exists expenses (
                                                  id text primary key,
                                                  merchant_id text default 'profile_1',
                                                  category text not null,
                                                  amount numeric(12,2) not null,
                                                  date bigint default extract(epoch from now())::bigint,
                                                  description text,
                                                  payment_method text default 'Cash'
                                                );

                                                -- 10. Business Loans
                                                create table if not exists loans (
                                                  id text primary key,
                                                  merchant_id text default 'profile_1',
                                                  principal_amount numeric(12,2) not null,
                                                  interest_rate numeric(6,2) not null,
                                                  interest_type text not null,
                                                  duration_months integer not null,
                                                  monthly_installment numeric(12,2) not null,
                                                  status text default 'applied',
                                                  applied_at bigint default extract(epoch from now())::bigint
                                                );

                                                -- 11. Payment Forms & Dynamic Forms
                                                create table if not exists payment_forms (
                                                  id text primary key default gen_random_uuid()::text,
                                                  merchant_id text not null,
                                                  title text not null,
                                                  description text,
                                                  logo_url text,
                                                  amount numeric(12,2) not null,
                                                  fields jsonb default '[]'::jsonb,
                                                  created_at timestamptz default now()
                                                );

                                                -- 12. Form Submissions
                                                create table if not exists form_submissions (
                                                  id text primary key default gen_random_uuid()::text,
                                                  form_id text references payment_forms(id) on delete cascade,
                                                  customer_name text not null,
                                                  customer_phone text not null,
                                                  customer_email text,
                                                  amount_bdt numeric(12,2) not null,
                                                  payment_method text default 'bKash',
                                                  payment_status text default 'PAID',
                                                  trx_id text unique not null,
                                                  submitted_at timestamptz default now()
                                                );

                                                -- 13. Orders
                                                create table if not exists orders (
                                                  id text primary key,
                                                  customer_name text not null,
                                                  customer_phone text not null,
                                                  amount numeric(12,2) not null,
                                                  status text default 'PENDING',
                                                  method text default 'bKash',
                                                  created_at bigint default extract(epoch from now())::bigint,
                                                  expires_at bigint,
                                                  notes text
                                                );

                                                -- 14. Payments
                                                create table if not exists payments (
                                                  id text primary key,
                                                  amount numeric(12,2) not null,
                                                  sender text not null,
                                                  timestamp bigint default extract(epoch from now())::bigint,
                                                  status text default 'UNMATCHED',
                                                  method text default 'bKash',
