                                            Spacer(modifier = Modifier.height(6.dp))
                                            Text(
                                                "Your parameters are saved. Click the Finalize button below to finalize configuration and begin matching real payments directly inside your app!",
                                                color = Color.White,
                                                fontSize = 13.sp,
                                                lineHeight = 18.sp
                                            )
                                            Spacer(modifier = Modifier.height(16.dp))

                                            Card(
                                                shape = RoundedCornerShape(16.dp),
                                                colors = CardDefaults.cardColors(containerColor = if (isDarkMode) Color.Black.copy(alpha = 0.2f) else Color(0xFFF9FAFB)),
                                                border = BorderStroke(1.dp, if (isDarkMode) Color.White.copy(alpha = 0.15f) else Color(0xFFE5E7EB)),
                                                modifier = Modifier.fillMaxWidth()
                                            ) {
                                                Column(modifier = Modifier.padding(14.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                                                    Text("DATABASE CONFIGURATION SUMMARY:", color = Color.White.copy(alpha = 0.6f), fontSize = 11.sp, fontWeight = FontWeight.Bold)
                                                    Divider(color = Color.White.copy(alpha = 0.1f))
                                                    Text("Endpoint: $supabaseUrlInput", color = Color.White, fontSize = 12.sp, maxLines = 1)
                                                    Text("Client Key: ${supabaseAnonKeyInput.take(24)}...", color = Color.White, fontSize = 12.sp)
                                                    Text("Project ID: $projectRef", color = Color.White, fontSize = 12.sp)
                                                }
                                            }
                                        }


                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    // Success Celebration Dialog
    if (showGraduationDialog) {
        EnterpriseGestureModal(
            onDismissRequest = {
                showGraduationDialog = false
                viewModel.setTab("Setup")
                viewModel.navigateTo("Main")
            },
            title = "Congratulations!",
            subtitle = "Swipe down or drag handle to dismiss",
            icon = Icons.Default.School
        ) {
            Column(horizontalAlignment = Alignment.CenterHorizontally) {
                Text(
                    "You successfully completed the Supabase Merchant database setup guide! SwapnoPay is now fully configured and synchronized with your private PostgreSQL cloud backend.",
                    fontSize = 14.sp,
                    color = AppTextSecondary,
                    lineHeight = 20.sp,
                    textAlign = TextAlign.Center
                )
                Spacer(modifier = Modifier.height(12.dp))
                Text("Welcome to SwapnoPay merchant network!", fontWeight = FontWeight.Bold, color = Color(0xFF10B981), fontSize = 14.sp)

                Spacer(modifier = Modifier.height(20.dp))

                Button(
                    onClick = {
                        showGraduationDialog = false
                        viewModel.setTab("Setup")
                        viewModel.navigateTo("Main")
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF58CC02)),
                    shape = RoundedCornerShape(12.dp),
                    modifier = Modifier.fillMaxWidth().height(48.dp)
                ) {
                    Text("Start Processing Payments", color = Color.White, fontWeight = FontWeight.Bold, fontSize = 15.sp)
                }
            }
        }
    }
}

