                            fontWeight = FontWeight.SemiBold,
                            color = Color(0xFF6366F1),
                            modifier = Modifier
                                .fillMaxWidth()
                                .background(if (isDarkMode) Color(0xFF1A1A24) else Color(0xFFF1F5F9), RoundedCornerShape(8.dp))
