                        val priorities = listOf("LOW", "MEDIUM", "HIGH", "CRITICAL")
                        Row(horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                            priorities.forEach { p ->
                                val isSelected = featurePriority == p
                                val pColor = when (p) {
                                    "CRITICAL" -> Color(0xFFDC2626)
                                    "HIGH" -> Color(0xFFF59E0B)
                                    "MEDIUM" -> Color(0xFF3B82F6)
                                    else -> Color(0xFF10B981)
                                }
                                Surface(
                                    onClick = { featurePriority = p },
                                    shape = RoundedCornerShape(8.dp),
                                    color = if (isSelected) pColor.copy(alpha = 0.18f) else if (isDarkMode) Color(0xFF1A1A1E) else Color(0xFFF8FAFC),
                                    border = BorderStroke(1.dp, if (isSelected) pColor else cardBorder)
                                ) {
                                    Text(
                                        text = p,
                                        fontSize = 10.5.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = if (isSelected) pColor else secondaryText,
                                        modifier = Modifier.padding(horizontal = 10.dp, vertical = 6.dp)
                                    )
                                }
                            }
                        }
                    }

                    // Description text area
                    Column(verticalArrangement = Arrangement.spacedBy(4.dp)) {
                        Text("Description & Business Use Case:", fontSize = 12.sp, fontWeight = FontWeight.SemiBold, color = primaryText)
                        OutlinedTextField(
                            value = featureDesc,
                            onValueChange = { featureDesc = it },
                            placeholder = { Text("Explain how this feature will help your business and workflow in detail...", color = secondaryText, fontSize = 12.5.sp) },
                            modifier = Modifier.fillMaxWidth().height(100.dp),
                            shape = RoundedCornerShape(12.dp)
                        )
                    }

                    Spacer(modifier = Modifier.height(4.dp))

                    // Submit Button
                    Button(
                        onClick = {
                            if (featureTitle.trim().isNotEmpty() && featureDesc.trim().isNotEmpty()) {
                                viewModel.submitFeatureRequest(
                                    title = featureTitle.trim(),
                                    category = featureCategory,
                                    description = featureDesc.trim(),
                                    priority = featurePriority
                                ) { success ->
                                    if (success) {
                                        featureSubmitted = true
                                    }
                                }
                            }
                        },
                        enabled = featureTitle.trim().isNotEmpty() && featureDesc.trim().isNotEmpty(),
                        colors = ButtonDefaults.buttonColors(containerColor = goldPrimary),
                        shape = RoundedCornerShape(12.dp),
                        modifier = Modifier.fillMaxWidth().height(48.dp)
                    ) {
                        Icon(Icons.Default.Send, null, tint = Color.Black, modifier = Modifier.size(16.dp))
                        Spacer(modifier = Modifier.width(6.dp))
                        Text("Submit Feature Request to Admin", fontWeight = FontWeight.Bold, fontSize = 13.5.sp, color = Color.Black)
                    }
                }
            }
        }
    }
}

private data class AdminItemData(
    val title: String,
    val subtitle: String,
    val icon: androidx.compose.ui.graphics.vector.ImageVector,
    val accentColor: Color,
    val onClick: () -> Unit
)

@Composable
fun SettingsScreen(viewModel: AppViewModel) {
    val isDarkMode by viewModel.isDarkMode.collectAsState()
    val themeState = if (isDarkMode) "Dark" else "Light"
    val languageState by viewModel.language.collectAsState()
    val isBiometricLocked by viewModel.isBiometricLocked.collectAsState()
    val isSecuritySyncing by viewModel.isSecuritySyncing.collectAsState()
    val securitySyncError by viewModel.securitySyncError.collectAsState()
    val appPin by viewModel.appPin.collectAsState()

    var sessionTimeoutState by remember { mutableStateOf("15 Mins") }
    var showChangePinDialog by remember { mutableStateOf(false) }
    var currentPinInput by remember { mutableStateOf("") }
    var newPinInput by remember { mutableStateOf("") }
    var confirmPinInput by remember { mutableStateOf("") }
    var pinErrorMessage by remember { mutableStateOf("") }
    var pinSuccessMessage by remember { mutableStateOf("") }

    var showAboutDialog by remember { mutableStateOf(false) }
    var showLanguageDialog by remember { mutableStateOf(false) }
    var showTimeoutDialog by remember { mutableStateOf(false) }

    SideEffect { isDarkModeGlobal = isDarkMode }

    val screenBg = if (isDarkMode) Color(0xFF0C0C0E) else Color(0xFFF8FAFC)
    val cardBg = if (isDarkMode) Color(0xFF141418) else Color(0xFFFFFFFF)
    val cardBorder = if (isDarkMode) Color(0xFF27272E) else Color(0xFFE2E8F0)
    val primaryText = if (isDarkMode) Color.White else Color(0xFF0F172A)
    val secondaryText = if (isDarkMode) Color(0xFF9CA3AF) else Color(0xFF64748B)
    val dividerColor = if (isDarkMode) Color(0xFF27272E) else Color(0xFFF1F5F9)

    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(screenBg)
    ) {
        Column(
            modifier = Modifier.fillMaxSize()
        ) {
            // HEADER NAVIGATION
            GradientTopBar(
                title = t("Settings", languageState),
                subtitle = "App Configuration & Security",
                onBack = {
                    viewModel.goBack()
                },
                gradient = if (isDarkMode) listOf(Color(0xFF1E1E24), Color(0xFF141418)) else GradPrimary
            )

            // MAIN SCROLLABLE CONTENT
            LazyColumn(
                modifier = Modifier
                    .fillMaxWidth()
                    .weight(1f),
                contentPadding = PaddingValues(start = 24.dp, end = 24.dp, bottom = 24.dp, top = 16.dp),
                verticalArrangement = Arrangement.spacedBy(20.dp)
            ) {


                // APP PREFERENCES SECTION
                item {
                    Column {
                        Text(
                            text = t("APP PREFERENCES", languageState),
                            fontSize = 11.sp,
                            fontWeight = FontWeight.Bold,
                            color = secondaryText,
                            letterSpacing = 1.sp,
                            modifier = Modifier.padding(horizontal = 4.dp, vertical = 8.dp)
                        )
                        Card(
                            shape = RoundedCornerShape(24.dp),
                            colors = CardDefaults.cardColors(containerColor = cardBg),
                            border = BorderStroke(1.dp, cardBorder),
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            Column {
                                // Theme Selector Row
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .clickable { viewModel.setDarkMode(!isDarkMode) }
                                        .padding(16.dp),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Row(
                                        verticalAlignment = Alignment.CenterVertically,
                                        horizontalArrangement = Arrangement.spacedBy(16.dp)
                                    ) {
                                        GradientIcon(
                                            icon = Icons.Outlined.NightsStay,
                                            gradient = listOf(Color(0xFFA78BFA), Color(0xFF8B5CF6)),
                                            size = 36.dp,
                                            iconSize = 18.dp,
                                            cornerRadius = 10.dp
                                        )
                                        Text(
                                            text = t("Theme", languageState),
                                            fontSize = 14.sp,
                                            fontWeight = FontWeight.SemiBold,
                                            color = primaryText
                                        )
                                    }
                                    Box(
                                        modifier = Modifier
                                            .background(if (isDarkMode) Color(0xFF3730A3) else Color(0xFFE0E7FF), RoundedCornerShape(100.dp))
                                            .padding(horizontal = 12.dp, vertical = 6.dp)
                                    ) {
                                        Text(
                                            text = themeState,
                                            fontSize = 11.sp,
                                            fontWeight = FontWeight.Bold,
                                            color = if (isDarkMode) Color.White else Color(0xFF4F46E5)
                                        )
                                    }
                                }

                                HorizontalDivider(color = dividerColor, thickness = 1.dp, modifier = Modifier.padding(horizontal = 16.dp))

                                // Language Selector Row
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .clickable { showLanguageDialog = true }
                                        .padding(16.dp),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Row(
                                        verticalAlignment = Alignment.CenterVertically,
                                        horizontalArrangement = Arrangement.spacedBy(16.dp)
                                    ) {
                                        GradientIcon(
                                            icon = Icons.Outlined.Language,
                                            gradient = listOf(Color(0xFF34D399), Color(0xFF10B981)),
                                            size = 36.dp,
                                            iconSize = 18.dp,
                                            cornerRadius = 10.dp
                                        )
                                        Text(
                                            text = t("Language", languageState),
                                            fontSize = 14.sp,
                                            fontWeight = FontWeight.SemiBold,
                                            color = primaryText
                                        )
                                    }
                                    Box(
                                        modifier = Modifier
                                            .background(if (isDarkMode) Color(0xFF065F46) else Color(0xFFD1FAE5), RoundedCornerShape(100.dp))
                                            .padding(horizontal = 12.dp, vertical = 6.dp)
                                    ) {
                                        Text(
                                            text = languageState,
                                            fontSize = 11.sp,
                                            fontWeight = FontWeight.Bold,
                                            color = if (isDarkMode) Color.White else Color(0xFF059669)
                                        )
                                    }
                                }
                            }
                        }
                    }
                }



                // SECURITY SECTION
                item {
                    Column {
                        Text(
                            text = t("SECURITY", languageState),
                            fontSize = 11.sp,
                            fontWeight = FontWeight.Bold,
                            color = secondaryText,
                            letterSpacing = 1.sp,
                            modifier = Modifier.padding(horizontal = 4.dp, vertical = 8.dp)
                        )
                        Card(
                            shape = RoundedCornerShape(24.dp),
                            colors = CardDefaults.cardColors(containerColor = cardBg),
                            border = BorderStroke(1.dp, cardBorder),
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            Column {
                                // Change PIN Row
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .clickable {
                                            showChangePinDialog = true
                                            currentPinInput = ""
                                            newPinInput = ""
                                            confirmPinInput = ""
                                            pinErrorMessage = ""
                                            pinSuccessMessage = ""
                                        }
                                        .padding(16.dp),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Row(
                                        verticalAlignment = Alignment.CenterVertically,
                                        horizontalArrangement = Arrangement.spacedBy(16.dp)
                                    ) {
                                        GradientIcon(
                                            icon = Icons.Outlined.VpnKey,
                                            gradient = listOf(Color(0xFFFBBF24), Color(0xFFD97706)),
                                            size = 36.dp,
                                            iconSize = 18.dp,
                                            cornerRadius = 10.dp
                                        )
                                        Text(
                                            text = t("Change PIN", languageState),
                                            fontSize = 14.sp,
                                            fontWeight = FontWeight.SemiBold,
                                            color = primaryText
                                        )
                                    }
                                    Icon(imageVector = Icons.Default.ChevronRight, contentDescription = null, tint = secondaryText, modifier = Modifier.size(18.dp))
                                }

                                HorizontalDivider(color = dividerColor, thickness = 1.dp, modifier = Modifier.padding(horizontal = 16.dp))

                                // Biometric Lock Row
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(16.dp),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Row(
                                        verticalAlignment = Alignment.CenterVertically,
                                        horizontalArrangement = Arrangement.spacedBy(16.dp)
                                    ) {
                                        GradientIcon(
                                            icon = Icons.Outlined.Fingerprint,
                                            gradient = listOf(Color(0xFF818CF8), Color(0xFF6366F1)),
                                            size = 36.dp,
                                            iconSize = 18.dp,
                                            cornerRadius = 10.dp
                                        )
                                        Text(
                                            text = t("Biometric Lock", languageState),
                                            fontSize = 14.sp,
                                            fontWeight = FontWeight.SemiBold,
                                            color = primaryText
                                        )
                                    }
                                    Switch(
                                        checked = isBiometricLocked,
                                        onCheckedChange = { viewModel.setBiometricLock(it) },
                                        colors = SwitchDefaults.colors(
                                            checkedThumbColor = Color.White,
                                            checkedTrackColor = BrandPurple,
                                            uncheckedThumbColor = Color.White,
                                            uncheckedTrackColor = if (isDarkMode) Color(0xFF3F3F46) else Color(0xFFE2E8F0)
                                        )
                                    )
                                }

                                HorizontalDivider(color = dividerColor, thickness = 1.dp, modifier = Modifier.padding(horizontal = 16.dp))

                                // Session Timeout Row
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .clickable { showTimeoutDialog = true }
                                        .padding(16.dp),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Row(
                                        verticalAlignment = Alignment.CenterVertically,
                                        horizontalArrangement = Arrangement.spacedBy(16.dp)
                                    ) {
                                        GradientIcon(
                                            icon = Icons.Outlined.Timer,
                                            gradient = listOf(Color(0xFFEC4899), Color(0xFFDB2777)),
                                            size = 36.dp,
                                            iconSize = 18.dp,
                                            cornerRadius = 10.dp
                                        )
                                        Text(
                                            text = t("Session Timeout", languageState),
                                            fontSize = 14.sp,
                                            fontWeight = FontWeight.SemiBold,
                                            color = primaryText
                                        )
                                    }
                                    Box(
                                        modifier = Modifier
                                            .background(if (isDarkMode) Color(0xFF9D174D) else Color(0xFFFCE7F3), RoundedCornerShape(100.dp))
                                            .padding(horizontal = 12.dp, vertical = 6.dp)
                                    ) {
                                        Text(
                                            text = sessionTimeoutState,
                                            fontSize = 11.sp,
                                            fontWeight = FontWeight.Bold,
                                            color = if (isDarkMode) Color.White else Color(0xFFC2185B)
                                        )
                                    }
                                }
                            }
                        }
                    }
                }

                // SMS & OTP GATEWAY SECTION
                item {
                    Column {
                        Text(
                            text = t("SMS & OTP GATEWAY", languageState),
                            fontSize = 11.sp,
                            fontWeight = FontWeight.Bold,
                            color = secondaryText,
                            letterSpacing = 1.sp,
                            modifier = Modifier.padding(horizontal = 4.dp, vertical = 8.dp)
                        )
                        Card(
                            shape = RoundedCornerShape(24.dp),
                            colors = CardDefaults.cardColors(containerColor = cardBg),
                            border = BorderStroke(1.dp, cardBorder),
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            Column {
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .clickable { viewModel.navigateTo("SmsGateway") }
                                        .padding(16.dp),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Row(
                                        verticalAlignment = Alignment.CenterVertically,
                                        horizontalArrangement = Arrangement.spacedBy(16.dp),
                                        modifier = Modifier.weight(1f)
                                    ) {
                                        GradientIcon(
                                            icon = Icons.Outlined.Sms,
                                            gradient = listOf(Color(0xFF10B981), Color(0xFF059669)),
                                            size = 36.dp,
                                            iconSize = 18.dp,
                                            cornerRadius = 10.dp
                                        )
                                        Column {
                                            Text(
                                                text = "সিম এসএমএস ও ওটিপি গেটওয়ে",
                                                fontSize = 14.sp,
                                                fontWeight = FontWeight.SemiBold,
                                                color = primaryText
                                            )
                                            Text(
                                                text = "অটো বাকি তাগাদা, মার্কেটিং ও এপিআই সেটিংস",
                                                fontSize = 11.sp,
                                                color = secondaryText
                                            )
                                        }
                                    }
                                    Icon(imageVector = Icons.Default.ChevronRight, contentDescription = null, tint = secondaryText, modifier = Modifier.size(18.dp))
                                }
                            }
                        }
                    }
                }

                // APP VERSION FOOTER
                item {
                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(vertical = 12.dp),
                        contentAlignment = Alignment.Center
                    ) {
                        Text(
                            text = "SwapnoPay MFS Gateway & Business POS v1.2.4",
                            fontSize = 12.sp,
                            fontWeight = FontWeight.Medium,
                            color = secondaryText
                        )
                    }
                }
            }
        }

        // DIALOG: CHANGE PIN
        if (showChangePinDialog) {
            EnterpriseGestureModal(
                onDismissRequest = { showChangePinDialog = false },
                title = t("Change PIN", languageState),
                subtitle = "Swipe down or drag handle to dismiss",
                icon = Icons.Default.Lock
            ) {
                Column(verticalArrangement = Arrangement.spacedBy(12.dp)) {
                    Text("Enter your current PIN and set a new 4-digit PIN:", fontSize = 13.sp, color = secondaryText)
                    val textFieldColors = OutlinedTextFieldDefaults.colors(
                        focusedTextColor = primaryText,
                        unfocusedTextColor = primaryText,
                        focusedBorderColor = BrandPurple,
                        unfocusedBorderColor = cardBorder,
                        focusedLabelColor = BrandPurple,
                        unfocusedLabelColor = secondaryText
                    )
                    OutlinedTextField(
                        value = currentPinInput,
                        onValueChange = { currentPinInput = it },
                        label = { Text("Current PIN") },
                        singleLine = true,
                        colors = textFieldColors,
                        modifier = Modifier.fillMaxWidth()
                    )
                    OutlinedTextField(
                        value = newPinInput,
                        onValueChange = { if (it.length <= 4) newPinInput = it },
                        label = { Text("New 4-Digit PIN") },
                        singleLine = true,
                        colors = textFieldColors,
                        modifier = Modifier.fillMaxWidth()
                    )
                    OutlinedTextField(
                        value = confirmPinInput,
                        onValueChange = { if (it.length <= 4) confirmPinInput = it },
                        label = { Text("Confirm New PIN") },
                        singleLine = true,
                        colors = textFieldColors,
                        modifier = Modifier.fillMaxWidth()
                    )
                    if (pinErrorMessage.isNotEmpty()) {
                        Text(pinErrorMessage, color = Color(0xFFEF4444), fontSize = 12.sp)
                    }
                    if (pinSuccessMessage.isNotEmpty()) {
                        Text(pinSuccessMessage, color = Color(0xFF10B981), fontSize = 12.sp)
                    }

                    Spacer(modifier = Modifier.height(8.dp))

                    Button(
                        onClick = {
                            if (!viewModel.verifyPin(currentPinInput)) {
                                pinErrorMessage = "Current PIN is incorrect!"
                            } else if (newPinInput.length < 4) {
                                pinErrorMessage = "New PIN must be 4 digits"
                            } else if (newPinInput != confirmPinInput) {
                                pinErrorMessage = "New PINs do not match"
                            } else {
                                viewModel.updatePin(newPinInput)
                                pinErrorMessage = ""
                                pinSuccessMessage = "PIN updated and synced to cloud!"
                                showChangePinDialog = false
                            }
                        },
                        colors = ButtonDefaults.buttonColors(containerColor = BrandPurple),
                        shape = RoundedCornerShape(12.dp),
                        modifier = Modifier.fillMaxWidth().height(48.dp)
                    ) {
                        Text("Update PIN", fontWeight = FontWeight.Bold, fontSize = 15.sp)
                    }
                }
            }
        }

        // DIALOG: LANGUAGE SELECTOR
        if (showLanguageDialog) {
            EnterpriseGestureModal(
                onDismissRequest = { showLanguageDialog = false },
                title = t("Language", languageState),
                subtitle = "Swipe down or drag handle to dismiss",
                icon = Icons.Default.Language
            ) {
                Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .clickable {
                                viewModel.setLanguage("English")
                                showLanguageDialog = false
                            }
                            .padding(12.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text("English", fontWeight = FontWeight.Bold, fontSize = 15.sp, color = primaryText)
                        if (languageState == "English") {
                            Spacer(modifier = Modifier.weight(1f))
                            Icon(Icons.Default.Check, contentDescription = null, tint = BrandPurple)
                        }
                    }
                    HorizontalDivider(color = dividerColor)
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .clickable {
                                viewModel.setLanguage("Bangla")
                                showLanguageDialog = false
                            }
                            .padding(12.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text("বাংলা (Bangla)", fontWeight = FontWeight.Bold, fontSize = 15.sp, color = primaryText)
                        if (languageState == "Bangla") {
                            Spacer(modifier = Modifier.weight(1f))
                            Icon(Icons.Default.Check, contentDescription = null, tint = BrandPurple)
                        }
                    }
                }
            }
        }

        // DIALOG: SESSION TIMEOUT
        if (showTimeoutDialog) {
            EnterpriseGestureModal(
                onDismissRequest = { showTimeoutDialog = false },
                title = t("Session Timeout", languageState),
                subtitle = "Swipe down or drag handle to dismiss",
                icon = Icons.Default.Timer
            ) {
                Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                    listOf("5 Mins", "15 Mins", "30 Mins", "1 Hour").forEach { timeoutOption ->
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .clickable {
                                    sessionTimeoutState = timeoutOption
                                    showTimeoutDialog = false
                                }
                                .padding(12.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Text(timeoutOption, fontWeight = FontWeight.SemiBold, fontSize = 14.sp, color = primaryText)
                            if (sessionTimeoutState == timeoutOption) {
                                Spacer(modifier = Modifier.weight(1f))
                                Icon(Icons.Default.Check, contentDescription = null, tint = BrandPurple)
                            }
                        }
                    }
                }
            }
        }

        // DIALOG: ABOUT APP
        if (showAboutDialog) {
            EnterpriseGestureModal(
                onDismissRequest = { showAboutDialog = false },
                title = "About SwapnoPay Gateway",
                subtitle = "Swipe down or drag handle to dismiss",
                icon = Icons.Default.Info
            ) {
                Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                    Text("SwapnoPay MFS Gateway & Business POS", fontWeight = FontWeight.Bold, fontSize = 15.sp, color = primaryText)
                    Text("Version 1.2.4 (Enterprise Edition)", fontSize = 12.sp, color = secondaryText)
                    Spacer(modifier = Modifier.height(4.dp))
                    Text("Automated MFS Payment Matching (bKash, Nagad, Rocket, Upay) with Supabase Cloud Database Sync.", fontSize = 13.sp, color = primaryText, lineHeight = 18.sp)

                    Spacer(modifier = Modifier.height(16.dp))

                    Button(
                        onClick = { showAboutDialog = false },
                        colors = ButtonDefaults.buttonColors(containerColor = BrandPurple),
                        shape = RoundedCornerShape(12.dp),
                        modifier = Modifier.fillMaxWidth().height(48.dp)
                    ) {
                        Text("Got It", fontWeight = FontWeight.Bold, fontSize = 15.sp)
                    }
                }
            }
        }
    }
}

@Composable
fun MoreMenuItem(
    icon: androidx.compose.ui.graphics.vector.ImageVector,
    label: String,
    gradient: List<Color> = listOf(Color.Gray, Color.Gray),
    onClick: () -> Unit
) {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .clickable(onClick = onClick)
            .padding(16.dp),
        horizontalArrangement = Arrangement.SpaceBetween,
        verticalAlignment = Alignment.CenterVertically
    ) {
        Row(verticalAlignment = Alignment.CenterVertically) {
            GradientIcon(
                icon = icon,
                gradient = gradient,
                size = 36.dp,
                iconSize = 18.dp,
                cornerRadius = 10.dp
            )
            Spacer(modifier = Modifier.width(16.dp))
            Text(label, fontSize = 14.sp, fontWeight = FontWeight.Bold, color = AppTextPrimary)
        }
        Icon(imageVector = Icons.Default.ChevronRight, contentDescription = null, tint = AppTextSecondary, modifier = Modifier.size(18.dp))
    }
}

// 11. DETAILED ORDER SCREEN
@Composable
fun OrderDetailScreen(viewModel: AppViewModel) {
    val isDarkMode by viewModel.isDarkMode.collectAsState()
    SideEffect { isDarkModeGlobal = isDarkMode }

    val order by viewModel.activeOrderDetails.collectAsState()

    Scaffold(
        topBar = {
            GradientTopBar(
                title = "Order Details",
                onBack = { viewModel.goBack() }
            )
        }
    ) { innerPadding ->
        if (order != null) {
            val ord = order!!
            Column(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(innerPadding)
                    .background(AppScreenBg)
                    .padding(24.dp),
                verticalArrangement = Arrangement.SpaceBetween
            ) {
                Column(verticalArrangement = Arrangement.spacedBy(16.dp)) {
                    // Hero card status
                    Card(
                        shape = RoundedCornerShape(24.dp),
                        colors = CardDefaults.cardColors(containerColor = AppCardBg),
                        modifier = Modifier.fillMaxWidth()
                    ) {
                        Column(
                            modifier = Modifier.padding(24.dp),
                            horizontalAlignment = Alignment.CenterHorizontally
                        ) {
                            Box(
                                modifier = Modifier
                                    .size(64.dp)
                                    .background(
                                        if (ord.status == "PAID") Color(0xFFD1FAE5) else Color(0xFFFEF3C7),
                                        CircleShape
                                    ),
                                contentAlignment = Alignment.Center
                            ) {
                                Icon(
                                    imageVector = if (ord.status == "PAID") Icons.Default.Check else Icons.Default.Pending,
                                    contentDescription = null,
                                    tint = if (ord.status == "PAID") SuccessGreen else Color(0xFFD97706),
                                    modifier = Modifier.size(36.dp)
                                )
                            }
                            Spacer(modifier = Modifier.height(16.dp))
                            Text(
                                text = if (ord.status == "PAID") "Payment Matched" else "Awaiting Payment",
                                fontSize = 18.sp,
                                fontWeight = FontWeight.Bold,
                                color = if (ord.status == "PAID") SuccessGreen else Color(0xFFD97706)
                            )
                            Text("${ord.method} • Personal Account", fontSize = 13.sp, color = AppTextSecondary)
                            Spacer(modifier = Modifier.height(12.dp))
                            Text(
                                text = "৳ ${ord.amount}",
                                fontSize = 32.sp,
                                fontWeight = FontWeight.Black,
                                color = AppTextPrimary
                            )
                        }
                    }

                    // Order Info Particulars
                    Card(
                        shape = RoundedCornerShape(20.dp),
                        colors = CardDefaults.cardColors(containerColor = AppCardBg),
                        modifier = Modifier.fillMaxWidth()
                    ) {
                        Column(modifier = Modifier.padding(16.dp), verticalArrangement = Arrangement.spacedBy(12.dp)) {
                            Row(verticalAlignment = Alignment.CenterVertically) {
                                Icon(imageVector = Icons.Default.Assignment, contentDescription = null, tint = BrandPurple)
                                Spacer(modifier = Modifier.width(12.dp))
                                Text("Order Specifications", fontWeight = FontWeight.Bold, fontSize = 14.sp, color = AppTextPrimary)
                            }
                            HorizontalDivider(color = AppDividerColor)
                            OrderDetailSpecificationRow(label = "Order ID", value = ord.id)
                            OrderDetailSpecificationRow(label = "Customer Name", value = ord.customerName)
                            OrderDetailSpecificationRow(label = "Customer Phone", value = ord.customerPhone)
                            OrderDetailSpecificationRow(label = "Order Created", value = formatTime(ord.createdAt))
                            OrderDetailSpecificationRow(label = "Expiry Timer", value = formatTime(ord.expiresAt))
                        }
                    }
                }

                // Expiry and Cancel Action buttons
                Column(verticalArrangement = Arrangement.spacedBy(12.dp)) {
                    if (ord.status == "PENDING") {
                        Button(
                            onClick = { viewModel.extendOrderExpiry(ord.id) },
                            colors = ButtonDefaults.buttonColors(containerColor = BrandPurple),
                            shape = RoundedCornerShape(14.dp),
                            modifier = Modifier.fillMaxWidth().height(52.dp)
                        ) {
                            Text("Extend Expiry (+15 min)", color = Color.White, fontWeight = FontWeight.Bold)
                        }
                        OutlinedButton(
                            onClick = {
                                viewModel.cancelOrder(ord.id)
                                viewModel.navigateTo("Main")
                            },
                            colors = ButtonDefaults.outlinedButtonColors(contentColor = ErrorRed),
                            shape = RoundedCornerShape(14.dp),
                            modifier = Modifier.fillMaxWidth().height(52.dp)
                        ) {
                            Text("Cancel Order", fontWeight = FontWeight.Bold)
                        }
                    } else {
                        Button(
                            onClick = { viewModel.navigateTo("Main") },
                            colors = ButtonDefaults.buttonColors(containerColor = BrandPurple),
                            shape = RoundedCornerShape(14.dp),
                            modifier = Modifier.fillMaxWidth().height(52.dp)
                        ) {
                            Text("Return to Dashboard", color = Color.White, fontWeight = FontWeight.Bold)
                        }
                    }
                }
            }
        }
    }
}

@Composable
fun OrderDetailSpecificationRow(label: String, value: String) {
    Row(
        modifier = Modifier.fillMaxWidth(),
        horizontalArrangement = Arrangement.SpaceBetween
    ) {
        Text(label, fontSize = 12.sp, color = AppTextSecondary)
        Text(value, fontSize = 13.sp, fontWeight = FontWeight.Bold, color = AppTextPrimary)
    }
}

// 12. DETAILED TRANSACTION / PAYMENT SCREEN
@Composable
fun PaymentDetailScreen(viewModel: AppViewModel) {
    val isDarkMode by viewModel.isDarkMode.collectAsState()
    SideEffect { isDarkModeGlobal = isDarkMode }
    val payment by viewModel.activePaymentDetails.collectAsState()
    val clipboardManager = LocalClipboardManager.current

    Scaffold(
        topBar = {
            GradientTopBar(
                title = "Payment Specifications",
                onBack = { viewModel.goBack() }
            )
        }
    ) { innerPadding ->
        if (payment != null) {
            val pay = payment!!
            Column(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(innerPadding)
                    .background(AppScreenBg)
                    .padding(24.dp),
                verticalArrangement = Arrangement.SpaceBetween
            ) {
                Column(verticalArrangement = Arrangement.spacedBy(16.dp)) {
                    // Success badge
                    Card(
                        shape = RoundedCornerShape(24.dp),
                        colors = CardDefaults.cardColors(containerColor = AppCardBg),
                        modifier = Modifier.fillMaxWidth()
                    ) {
                        Column(
                            modifier = Modifier.padding(24.dp),
                            horizontalAlignment = Alignment.CenterHorizontally
                        ) {
                            Box(
                                modifier = Modifier
                                    .size(64.dp)
                                    .background(Color(0xFFD1FAE5), CircleShape),
                                contentAlignment = Alignment.Center
                            ) {
                                Icon(
                                    imageVector = Icons.Default.Check,
                                    contentDescription = null,
                                    tint = SuccessGreen,
                                    modifier = Modifier.size(36.dp)
                                )
                            }
                            Spacer(modifier = Modifier.height(16.dp))
                            Text("Payment Matched", fontSize = 18.sp, fontWeight = FontWeight.Bold, color = SuccessGreen)
                            Text("${pay.method} • Gateway Verified", fontSize = 13.sp, color = AppTextSecondary)
                            Spacer(modifier = Modifier.height(12.dp))
                            Text(
                                text = "৳ ${pay.amount}",
                                fontSize = 32.sp,
                                fontWeight = FontWeight.Black,
                                color = AppTextPrimary
                            )
                        }
                    }

                    // Payment details particulars
                    Card(
                        shape = RoundedCornerShape(20.dp),
                        colors = CardDefaults.cardColors(containerColor = AppCardBg),
                        modifier = Modifier.fillMaxWidth()
                    ) {
                        Column(modifier = Modifier.padding(16.dp), verticalArrangement = Arrangement.spacedBy(12.dp)) {
                            OrderDetailSpecificationRow(label = "Payment Gateway", value = pay.method)
                            OrderDetailSpecificationRow(label = "Sender Number", value = pay.sender)
                            OrderDetailSpecificationRow(label = "TrxID", value = pay.id)
                            OrderDetailSpecificationRow(label = "Time Received", value = formatTime(pay.timestamp))
                            OrderDetailSpecificationRow(label = "Linked Order ID", value = pay.orderId ?: "Auto-matched")
                        }
                    }
                }

                // Actions row
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(12.dp)
                ) {
                    Button(
                        onClick = {
                            clipboardManager.setText(AnnotatedString(pay.id))
                        },
                        colors = ButtonDefaults.buttonColors(containerColor = BrandLightPurple, contentColor = BrandPurple),
                        shape = RoundedCornerShape(12.dp),
                        modifier = Modifier.weight(1f).height(48.dp)
                    ) {
                        Icon(imageVector = Icons.Default.ContentCopy, contentDescription = null, modifier = Modifier.size(18.dp))
                        Spacer(modifier = Modifier.width(6.dp))
                        Text("Copy TrxID", fontSize = 12.sp, fontWeight = FontWeight.Bold)
                    }

                    Button(
                        onClick = { viewModel.goBack() },
                        colors = ButtonDefaults.buttonColors(containerColor = BrandPurple),
                        shape = RoundedCornerShape(12.dp),
                        modifier = Modifier.weight(1f).height(48.dp)
                    ) {
                        Text("Back", color = Color.White, fontWeight = FontWeight.Bold)
                    }
                }
            }
        }
    }
}

// 13. BUSINESS PROFILE SCREEN
@Composable
fun BusinessProfileScreen(viewModel: AppViewModel) {
    val activeProfile by viewModel.activeProfile.collectAsState()
    var showEditDialog by remember { mutableStateOf(false) }

    // State for the edit form
    var editName by remember(activeProfile) { mutableStateOf(activeProfile.businessName) }
    var editType by remember(activeProfile) { mutableStateOf(activeProfile.businessType) }
    var editEmail by remember(activeProfile) { mutableStateOf(activeProfile.email) }
    var editPhone by remember(activeProfile) { mutableStateOf(activeProfile.phone) }
    var editWebsite by remember(activeProfile) { mutableStateOf(activeProfile.website) }
    var editPhotoUrl by remember(activeProfile) { mutableStateOf(activeProfile.photoUrl) }

    val isDarkMode by viewModel.isDarkMode.collectAsState()
    SideEffect { isDarkModeGlobal = isDarkMode }
    val languageState by viewModel.language.collectAsState()
    val isBangla = languageState.lowercase() == "bangla" || languageState == "বাংলা"

    var activeTabState by remember { mutableStateOf("General") } // "General", "API Keys", "Security"
    val isRefreshingKyc by viewModel.isRefreshingKyc.collectAsState()
    val clipboardManager = androidx.compose.ui.platform.LocalClipboardManager.current
    val context = androidx.compose.ui.platform.LocalContext.current

    LaunchedEffect(Unit) {
        viewModel.refreshMerchantKycStatus()
    }

    var isUploadingPhoto by remember { mutableStateOf(false) }

    val photoPickerLauncher = rememberLauncherForActivityResult(
        contract = ActivityResultContracts.GetContent()
    ) { uri: Uri? ->
        if (uri != null) {
            isUploadingPhoto = true
            try {
                val bytes = context.contentResolver.openInputStream(uri)?.use { it.readBytes() }
                if (bytes != null && bytes.isNotEmpty()) {
                    viewModel.uploadMerchantPhoto(bytes) { savedPath ->
                        isUploadingPhoto = false
                        if (savedPath != null) {
                            editPhotoUrl = savedPath
                            Toast.makeText(
                                context,
                                if (isBangla) "মার্চেন্ট ফটো সফলভাবে আপডেট করা হয়েছে" else "Merchant photo updated successfully",
                                Toast.LENGTH_SHORT
                            ).show()
                        } else {
                            Toast.makeText(
                                context,
                                if (isBangla) "ছবি সংরক্ষণে সমস্যা হয়েছে" else "Failed to save photo",
                                Toast.LENGTH_SHORT
                            ).show()
                        }
                    }
                } else {
                    isUploadingPhoto = false
                    Toast.makeText(context, if (isBangla) "ছবিটি লোড করা সম্ভব হয়নি" else "Unable to read selected image", Toast.LENGTH_SHORT).show()
                }
            } catch (e: Exception) {
                isUploadingPhoto = false
                Toast.makeText(context, "Error: ${e.message}", Toast.LENGTH_SHORT).show()
            }
        }
    }

    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(AppScreenBg)
    ) {
        Column(
            modifier = Modifier.fillMaxSize()
        ) {
            // Immersive Header Area with Gradient
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .background(
                        Brush.linearGradient(
                            colors = if (isDarkMode) listOf(Color(0xFF1E1B4B), Color(0xFF312E81)) else GradPrimary
                        )
                    )
                    .statusBarsPadding()
                    .padding(bottom = 24.dp)
            ) {
                Column(
                    modifier = Modifier.fillMaxWidth()
                ) {
                    // Header Bar (Back, Title, Edit)
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(horizontal = 24.dp, vertical = 16.dp),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        // Glass back button
                        Box(
                            modifier = Modifier
                                .size(40.dp)
                                .background(Color.White.copy(alpha = 0.15f), CircleShape)
                                .clip(CircleShape)
                                .clickable { viewModel.goBack() },
                            contentAlignment = Alignment.Center
                        ) {
                            Icon(
                                imageVector = Icons.AutoMirrored.Filled.ArrowBack,
                                contentDescription = "Back",
                                tint = Color.White,
                                modifier = Modifier.size(20.dp)
                            )
                        }

                        Text(
                            text = "Merchant Profile",
                            color = Color.White,
                            fontSize = 18.sp,
                            fontWeight = FontWeight.Bold
                        )

                        // Glass edit button
                        Box(
                            modifier = Modifier
                                .size(40.dp)
                                .background(Color.White.copy(alpha = 0.15f), CircleShape)
                                .clip(CircleShape)
                                .clickable { showEditDialog = true },
                            contentAlignment = Alignment.Center
                        ) {
                            Icon(
                                imageVector = Icons.Default.Edit,
                                contentDescription = "Edit Profile",
                                tint = Color.White,
                                modifier = Modifier.size(18.dp)
                            )
                        }
                    }

                    Spacer(modifier = Modifier.height(8.dp))

                    // Store Icon / Image & Verified Badge
                    Column(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalAlignment = Alignment.CenterHorizontally
                    ) {
                        Box(
                            modifier = Modifier.size(100.dp),
                            contentAlignment = Alignment.Center
                        ) {
                            // Logo Box or Custom Merchant Image
                            Box(
                                modifier = Modifier
                                    .size(100.dp)
                                    .shadow(8.dp, CircleShape)
                                    .background(Color.White, CircleShape)
                                    .border(BorderStroke(2.dp, Color.White), CircleShape)
                                    .clickable {
                                        viewModel.isExternalActivityExpected = true
                                        photoPickerLauncher.launch("image/*")
                                    },
                                contentAlignment = Alignment.Center
                            ) {
                                if (isUploadingPhoto) {
                                    CircularProgressIndicator(
                                        color = BrandPurple,
                                        modifier = Modifier.size(36.dp),
                                        strokeWidth = 3.dp
                                    )
                                } else if (activeProfile.photoUrl.isNotEmpty()) {
                                    AsyncImage(
                                        model = activeProfile.photoUrl,
                                        contentDescription = "Merchant Photo",
                                        modifier = Modifier
                                            .fillMaxSize()
                                            .clip(CircleShape),
                                        contentScale = androidx.compose.ui.layout.ContentScale.Crop
                                    )
                                } else {
                                    Box(
                                        modifier = Modifier
                                            .fillMaxSize()
                                            .background(Color(0xFFE0E7FF), CircleShape),
                                        contentAlignment = Alignment.Center
                                    ) {
                                        Icon(
                                            imageVector = Icons.Default.Storefront,
                                            contentDescription = null,
                                            tint = Color(0xFF4F46E5),
                                            modifier = Modifier.size(44.dp)
                                        )
                                    }
                                }
                            }

                            // Camera photo upload icon overlay badge
                            Box(
                                modifier = Modifier
                                    .size(32.dp)
                                    .align(Alignment.BottomEnd)
                                    .offset(x = 2.dp, y = 2.dp)
                                    .shadow(4.dp, CircleShape)
                                    .background(Brush.linearGradient(GradAccent), CircleShape)
                                    .border(BorderStroke(1.5.dp, Color.White), CircleShape)
                                    .clickable {
                                        viewModel.isExternalActivityExpected = true
                                        photoPickerLauncher.launch("image/*")
                                    },
                                contentAlignment = Alignment.Center
                            ) {
                                Icon(
                                    imageVector = Icons.Default.CameraAlt,
                                    contentDescription = "Upload Photo",
                                    tint = Color.White,
                                    modifier = Modifier.size(14.dp)
                                )
                            }
                        }

                        Spacer(modifier = Modifier.height(12.dp))

                        // Business Details
                        Row(verticalAlignment = Alignment.CenterVertically) {
                            Text(
                                text = activeProfile.businessName,
                                color = Color.White,
                                fontSize = 18.sp,
                                fontWeight = FontWeight.Bold
                            )
                            Spacer(modifier = Modifier.width(6.dp))
                            // Verified blue checkmark
                            Box(
                                modifier = Modifier
                                    .size(16.dp)
                                    .background(Color(0xFF3B82F6), CircleShape),
                                contentAlignment = Alignment.Center
                            ) {
                                Icon(
                                    imageVector = Icons.Default.Check,
                                    contentDescription = "Verified",
                                    tint = Color.White,
                                    modifier = Modifier.size(10.dp)
                                )
                            }
                        }
                        Spacer(modifier = Modifier.height(2.dp))
                        Text(
                            text = activeProfile.email,
                            color = Color.White.copy(alpha = 0.8f),
                            fontSize = 12.sp,
                            fontWeight = FontWeight.Medium
                        )
                    }
                }
            }

            // Tab Navigation Selector Row
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = 24.dp, vertical = 12.dp)
                    .background(AppCardBg, RoundedCornerShape(16.dp))
                    .border(BorderStroke(1.dp, AppCardBorderColor), RoundedCornerShape(16.dp))
                    .padding(4.dp),
                horizontalArrangement = Arrangement.SpaceAround
            ) {
                val tabs = listOf(
                    "General" to Icons.Default.Storefront,
                    "Security & KYC" to Icons.Default.VerifiedUser
                )
                tabs.forEach { (tabName, icon) ->
                    val selected = activeTabState == tabName
                    Row(
                        modifier = Modifier
                            .clip(RoundedCornerShape(12.dp))
                            .background(if (selected) BrandLightPurple else Color.Transparent)
                            .clickable { activeTabState = tabName }
                            .padding(horizontal = 16.dp, vertical = 8.dp),
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.Center
                    ) {
                        Icon(
                            imageVector = icon,
                            contentDescription = null,
                            tint = if (selected) BrandPurple else AppTextSecondary,
                            modifier = Modifier.size(18.dp)
                        )
                        Spacer(modifier = Modifier.width(6.dp))
                        Text(
                            text = tabName,
                            fontWeight = FontWeight.Bold,
                            fontSize = 12.sp,
                            color = if (selected) BrandPurple else AppTextSecondary
                        )
                    }
                }
            }

            // Scrollable Content
            LazyColumn(
                modifier = Modifier
                    .fillMaxWidth()
                    .weight(1f),
                contentPadding = PaddingValues(start = 24.dp, end = 24.dp, bottom = 40.dp),
                verticalArrangement = Arrangement.spacedBy(16.dp)
            ) {
                when (activeTabState) {
                    "General" -> {
                        item {
                            Card(
                                shape = RoundedCornerShape(24.dp),
                                colors = CardDefaults.cardColors(containerColor = AppCardBg),
                                modifier = Modifier.fillMaxWidth(),
                                border = BorderStroke(1.dp, AppCardBorderColor),
                                elevation = CardDefaults.cardElevation(defaultElevation = 1.dp)
                            ) {
                                Column {
                                    ProfileRowItem(
                                        icon = Icons.Default.CorporateFare,
                                        label = "BUSINESS NAME",
                                        value = activeProfile.businessName,
                                        onClick = { showEditDialog = true }
                                    )
                                    HorizontalDivider(color = AppDividerColor, thickness = 1.dp)
                                    ProfileRowItem(
                                        icon = Icons.Default.Sell,
                                        label = "BUSINESS TYPE",
                                        value = activeProfile.businessType,
                                        onClick = { showEditDialog = true }
                                    )
                                    HorizontalDivider(color = AppDividerColor, thickness = 1.dp)
                                    ProfileRowItem(
                                        icon = Icons.Default.Language,
                                        label = "WEBSITE",
                                        value = activeProfile.website,
                                        valueColor = BrandPurple,
                                        onClick = { showEditDialog = true }
                                    )
                                    HorizontalDivider(color = AppDividerColor, thickness = 1.dp)
                                    ProfileRowItem(
                                        icon = Icons.Default.Phone,
                                        label = "CONTACT PHONE",
                                        value = activeProfile.phone,
                                        onClick = { showEditDialog = true },
                                        isLast = true
                                    )
                                }
                            }
                        }
                        item {
                            Spacer(modifier = Modifier.height(8.dp))
                            Card(
                                shape = RoundedCornerShape(24.dp),
                                colors = CardDefaults.cardColors(containerColor = AppCardBg),
                                modifier = Modifier.fillMaxWidth(),
                                border = BorderStroke(1.dp, AppCardBorderColor),
                                elevation = CardDefaults.cardElevation(defaultElevation = 1.dp)
                            ) {
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .clickable {
                                            val intent = android.content.Intent(android.content.Intent.ACTION_VIEW, android.net.Uri.parse("https://docs.swapnopay.org"))
                                            context.startActivity(intent)
                                        }
                                        .padding(20.dp),
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Box(
                                        modifier = Modifier
                                            .size(40.dp)
                                            .background(BrandPurple.copy(alpha = 0.15f), RoundedCornerShape(12.dp)),
                                        contentAlignment = Alignment.Center
                                    ) {
                                        Icon(
                                            imageVector = Icons.Default.Book,
                                            contentDescription = null,
                                            tint = BrandPurple,
                                            modifier = Modifier.size(22.dp)
                                        )
                                    }
                                    Spacer(modifier = Modifier.width(16.dp))
                                    Column(modifier = Modifier.weight(1f)) {
                                        Text(
                                            text = if (isBangla) "ডেভেলপার ডকুমেন্টেশন" else "DEVELOPER DOCUMENTATION",
                                            fontSize = 11.sp,
                                            color = AppTextSecondary,
                                            fontWeight = FontWeight.Bold,
                                            letterSpacing = 0.5.sp
                                        )
                                        Spacer(modifier = Modifier.height(2.dp))
                                        Text(
                                            text = if (isBangla) "ইন্টিগ্রেশন গাইড ও এপিআই রেফারেন্স পড়ুন" else "Read Integration Guide & API Reference",
                                            fontSize = 13.sp,
                                            fontWeight = FontWeight.Bold,
                                            color = if (isDarkMode) Color.White else Color(0xFF1F2937)
                                        )
                                    }
                                    Icon(
                                        imageVector = Icons.Default.ChevronRight,
                                        contentDescription = null,
                                        tint = AppTextSecondary,
                                        modifier = Modifier.size(20.dp)
                                    )
                                }
                            }
                        }
                    }
                    "Security", "Security & KYC", "Security & Sync" -> {
                        item {
                            Column(verticalArrangement = Arrangement.spacedBy(14.dp)) {
                                val kycStatusState = activeProfile.kycStatus.uppercase()
                                val isVerified = kycStatusState in listOf("VERIFIED", "APPROVED")
                                val isPending = kycStatusState == "PENDING"
                                val isRejected = kycStatusState == "REJECTED"

                                val statusColor = when {
                                    isVerified -> Color(0xFF10B981)
                                    isPending -> Color(0xFFF59E0B)
                                    isRejected -> Color(0xFFEF4444)
                                    else -> Color(0xFF6B7280)
                                }

                                val statusBg = when {
                                    isVerified -> Color(0xFF10B981).copy(alpha = 0.1f)
                                    isPending -> Color(0xFFF59E0B).copy(alpha = 0.1f)
                                    isRejected -> Color(0xFFEF4444).copy(alpha = 0.1f)
                                    else -> if (isDarkMode) Color(0xFF1E293B) else Color(0xFFF1F5F9)
                                }

                                val statusBorder = when {
                                    isVerified -> Color(0xFF10B981).copy(alpha = 0.35f)
                                    isPending -> Color(0xFFF59E0B).copy(alpha = 0.35f)
                                    isRejected -> Color(0xFFEF4444).copy(alpha = 0.35f)
                                    else -> if (isDarkMode) Color(0xFF334155) else Color(0xFFE2E8F0)
                                }

                                // 1. Main NID Verification Status & Sync Card
                                Card(
                                    shape = RoundedCornerShape(24.dp),
                                    colors = CardDefaults.cardColors(containerColor = AppCardBg),
                                    modifier = Modifier.fillMaxWidth(),
                                    border = BorderStroke(1.2.dp, statusBorder),
                                    elevation = CardDefaults.cardElevation(defaultElevation = 2.dp)
                                ) {
                                    Column(
                                        modifier = Modifier.padding(18.dp),
                                        verticalArrangement = Arrangement.spacedBy(14.dp)
                                    ) {
                                        // Header Row with Icon, Status Label, and Sync Button
                                        Row(
                                            modifier = Modifier.fillMaxWidth(),
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            Box(
                                                modifier = Modifier
                                                    .size(46.dp)
                                                    .background(statusBg, RoundedCornerShape(14.dp)),
                                                contentAlignment = Alignment.Center
                                            ) {
                                                Icon(
                                                    imageVector = when {
                                                        isVerified -> Icons.Default.Verified
                                                        isPending -> Icons.Default.Pending
                                                        isRejected -> Icons.Default.GppBad
                                                        else -> Icons.Default.Shield
                                                    },
                                                    contentDescription = null,
                                                    tint = statusColor,
                                                    modifier = Modifier.size(24.dp)
                                                )
                                            }

                                            Spacer(modifier = Modifier.width(14.dp))

                                            Column(modifier = Modifier.weight(1f)) {
                                                Text(
                                                    text = if (isBangla) "এনআইডি ভেরিফিকেশন স্ট্যাটাস" else "NID VERIFICATION STATUS",
                                                    fontSize = 11.sp,
                                                    color = AppTextSecondary,
                                                    fontWeight = FontWeight.Bold,
                                                    letterSpacing = 0.5.sp
                                                )
                                                Spacer(modifier = Modifier.height(2.dp))
                                                Text(
                                                    text = when {
                                                        isVerified -> if (isBangla) "যাচাইকৃত (লেভেল ২ অ্যাক্টিভ)" else "Fully Verified (Level 2 Active)"
                                                        isPending -> if (isBangla) "পর্যালোচনার জন্য অপেক্ষারত" else "Under Compliance Review"
                                                        isRejected -> if (isBangla) "যাচাইকরণ প্রত্যাখ্যাত" else "Verification Rejected"
                                                        else -> if (isBangla) "যাচাই করা হয়নি" else "Unverified (Action Required)"
                                                    },
                                                    fontSize = 14.5.sp,
                                                    fontWeight = FontWeight.Bold,
                                                    color = statusColor
                                                )
                                            }

                                            // Sync KYC / NID Status Button
                                            IconButton(
                                                onClick = {
                                                    viewModel.refreshMerchantKycStatus { s, _ ->
                                                        Toast.makeText(
                                                            context,
                                                            if (isBangla) "এনআইডি স্ট্যাটাস সিঙ্ক হয়েছে: $s" else "NID status refreshed: $s",
                                                            Toast.LENGTH_SHORT
                                                        ).show()
                                                    }
                                                },
                                                modifier = Modifier
                                                    .size(36.dp)
                                                    .background(if (isDarkMode) Color(0xFF1E293B) else Color(0xFFF1F5F9), CircleShape)
                                            ) {
                                                if (isRefreshingKyc) {
                                                    CircularProgressIndicator(
                                                        modifier = Modifier.size(16.dp),
                                                        strokeWidth = 2.dp,
                                                        color = BrandPurple
                                                    )
                                                } else {
                                                    Icon(
                                                        imageVector = Icons.Default.Sync,
                                                        contentDescription = "Sync NID Status",
                                                        tint = BrandPurple,
                                                        modifier = Modifier.size(18.dp)
                                                    )
                                                }
                                            }
                                        }

                                        HorizontalDivider(color = AppDividerColor, thickness = 1.dp)

                                        // Detailed NID Information Grid
                                        Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                                            Row(
                                                modifier = Modifier.fillMaxWidth(),
                                                horizontalArrangement = Arrangement.SpaceBetween,
                                                verticalAlignment = Alignment.CenterVertically
                                            ) {
                                                Text(
                                                    text = if (isBangla) "জাতীয় পরিচয়পত্র (NID) নম্বর:" else "National ID (NID) Number:",
                                                    fontSize = 12.5.sp,
                                                    color = AppTextSecondary
                                                )
                                                Text(
                                                    text = activeProfile.nidNumber.takeIf { it.isNotBlank() } ?: (if (isBangla) "প্রদান করা হয়নি" else "Not submitted"),
                                                    fontSize = 13.sp,
                                                    fontWeight = FontWeight.SemiBold,
                                                    color = if (isDarkMode) Color.White else Color(0xFF0F172A)
                                                )
                                            }

                                            Row(
                                                modifier = Modifier.fillMaxWidth(),
                                                horizontalArrangement = Arrangement.SpaceBetween,
                                                verticalAlignment = Alignment.CenterVertically
                                            ) {
                                                Text(
                                                    text = if (isBangla) "হোল্ডারের নাম:" else "Holder Legal Name:",
                                                    fontSize = 12.5.sp,
                                                    color = AppTextSecondary
                                                )
                                                Text(
                                                    text = activeProfile.accountHolder.ifBlank { activeProfile.businessName },
                                                    fontSize = 13.sp,
                                                    fontWeight = FontWeight.SemiBold,
                                                    color = if (isDarkMode) Color.White else Color(0xFF0F172A)
                                                )
                                            }

                                            Row(
                                                modifier = Modifier.fillMaxWidth(),
                                                horizontalArrangement = Arrangement.SpaceBetween,
                                                verticalAlignment = Alignment.CenterVertically
                                            ) {
                                                Text(
                                                    text = if (isBangla) "সেটেলমেন্ট টায়ার:" else "Settlement Tier:",
                                                    fontSize = 12.5.sp,
                                                    color = AppTextSecondary
                                                )
                                                Surface(
                                                    shape = RoundedCornerShape(6.dp),
                                                    color = if (isVerified) Color(0xFF10B981).copy(alpha = 0.15f) else Color(0xFF6B7280).copy(alpha = 0.15f)
                                                ) {
                                                    Text(
                                                        text = if (isVerified) "Tier 2 (Unlimited BDT)" else "Tier 1 (Restricted)",
                                                        fontSize = 11.5.sp,
                                                        fontWeight = FontWeight.Bold,
                                                        color = if (isVerified) Color(0xFF10B981) else Color(0xFF6B7280),
                                                        modifier = Modifier.padding(horizontal = 8.dp, vertical = 3.dp)
                                                    )
                                                }
                                            }
                                        }

                                        // Conditional Status Banner & Action Buttons
                                        if (isRejected) {
                                            Surface(
                                                shape = RoundedCornerShape(12.dp),
                                                color = Color(0xFFEF4444).copy(alpha = 0.08f),
                                                border = BorderStroke(1.dp, Color(0xFFEF4444).copy(alpha = 0.25f)),
                                                modifier = Modifier.fillMaxWidth()
                                            ) {
                                                Column(modifier = Modifier.padding(12.dp), verticalArrangement = Arrangement.spacedBy(6.dp)) {
                                                    Text(
                                                        text = if (isBangla) "প্রত্যাখ্যানের কারণ:" else "Rejection Reason:",
                                                        fontSize = 11.5.sp,
                                                        fontWeight = FontWeight.Bold,
                                                        color = Color(0xFFEF4444)
                                                    )
                                                    Text(
                                                        text = activeProfile.kycRejectionReason.ifBlank {
                                                            if (isBangla) "এনআইডি ছবি পরিষ্কার ছিল না বা তথ্য মেলেনি। অনুগ্রহ করে আবার আবেদন করুন।"
                                                            else "NID photo was unclear or details did not match. Please re-apply."
                                                        },
                                                        fontSize = 12.sp,
                                                        color = if (isDarkMode) Color.White.copy(alpha = 0.9f) else Color(0xFF7F1D1D)
                                                    )
                                                }
                                            }

                                            Button(
                                                onClick = { viewModel.navigateTo("KycVerification") },
                                                colors = ButtonDefaults.buttonColors(containerColor = Color(0xFFEF4444)),
                                                shape = RoundedCornerShape(12.dp),
                                                modifier = Modifier.fillMaxWidth().height(44.dp)
                                            ) {
                                                Icon(Icons.Default.Refresh, null, modifier = Modifier.size(16.dp), tint = Color.White)
                                                Spacer(modifier = Modifier.width(8.dp))
                                                Text(
                                                    text = if (isBangla) "এনআইডি পুনরায় জমা দিন (Re-apply)" else "Re-apply NID Verification",
                                                    fontWeight = FontWeight.Bold,
                                                    fontSize = 13.sp,
                                                    color = Color.White
                                                )
                                            }
                                        } else if (isPending) {
                                            Surface(
                                                shape = RoundedCornerShape(12.dp),
                                                color = Color(0xFFF59E0B).copy(alpha = 0.08f),
                                                border = BorderStroke(1.dp, Color(0xFFF59E0B).copy(alpha = 0.25f)),
                                                modifier = Modifier.fillMaxWidth()
                                            ) {
                                                Row(
                                                    modifier = Modifier.padding(12.dp),
                                                    verticalAlignment = Alignment.CenterVertically,
                                                    horizontalArrangement = Arrangement.spacedBy(10.dp)
                                                ) {
                                                    Icon(Icons.Default.Pending, null, tint = Color(0xFFF59E0B), modifier = Modifier.size(20.dp))
                                                    Text(
                                                        text = if (isBangla) "আপনার এনআইডি নথি পর্যালোচনা চলছে। সাধারণত ২-৬ ঘণ্টার মধ্যে যাচাই সম্পন্ন হয়।"
                                                        else "Your NID documents are under compliance review. Review usually completes within 2-6 hours.",
                                                        fontSize = 12.sp,
                                                        color = if (isDarkMode) Color.White.copy(alpha = 0.9f) else Color(0xFF78350F)
                                                    )
                                                }
                                            }
                                        } else if (!isVerified) {
                                            Surface(
                                                shape = RoundedCornerShape(12.dp),
                                                color = BrandPurple.copy(alpha = 0.08f),
                                                border = BorderStroke(1.dp, BrandPurple.copy(alpha = 0.25f)),
                                                modifier = Modifier.fillMaxWidth()
                                            ) {
                                                Text(
                                                    text = if (isBangla) "আনলিমিটেড মোবাইল ব্যাংকিং সেটেলমেন্ট এবং পেমেন্ট ফর্ম সক্রিয় করতে এনআইডি ভেরিফিকেশন সম্পন্ন করুন।"
                                                    else "Verify your National ID (NID) to unlock unlimited payments, instant settlements, and hosted form branding.",
                                                    fontSize = 12.sp,
                                                    color = if (isDarkMode) Color.White.copy(alpha = 0.9f) else Color(0xFF312E81),
                                                    modifier = Modifier.padding(12.dp)
                                                )
                                            }

                                            Button(
                                                onClick = { viewModel.navigateTo("KycVerification") },
                                                colors = ButtonDefaults.buttonColors(containerColor = BrandPurple),
                                                shape = RoundedCornerShape(12.dp),
                                                modifier = Modifier.fillMaxWidth().height(44.dp)
                                            ) {
                                                Icon(Icons.Default.VerifiedUser, null, modifier = Modifier.size(16.dp), tint = Color.White)
                                                Spacer(modifier = Modifier.width(8.dp))
                                                Text(
                                                    text = if (isBangla) "এনআইডি ভেরিফাই করুন (Verify NID Now)" else "Verify NID Now",
                                                    fontWeight = FontWeight.Bold,
                                                    fontSize = 13.sp,
                                                    color = Color.White
                                                )
                                            }
                                        } else {
                                            Surface(
                                                shape = RoundedCornerShape(12.dp),
                                                color = Color(0xFF10B981).copy(alpha = 0.08f),
                                                border = BorderStroke(1.dp, Color(0xFF10B981).copy(alpha = 0.25f)),
                                                modifier = Modifier.fillMaxWidth()
                                            ) {
                                                Column(modifier = Modifier.padding(12.dp), verticalArrangement = Arrangement.spacedBy(4.dp)) {
                                                    Text(
                                                        text = if (isBangla) "✓ এনআইডি নথি ও বায়োমেট্রিক অনুমোদিত" else "✓ NID Document & Biometrics Approved",
                                                        fontSize = 12.sp,
                                                        fontWeight = FontWeight.SemiBold,
                                                        color = Color(0xFF10B981)
                                                    )
                                                    Text(
                                                        text = if (isBangla) "✓ আনলিমিটেড অটো-সেটেলমেন্ট ও ওয়েব স্টোরফ্রন্ট লাইভ" else "✓ Unlimited Auto-Settlements & Web Storefront Live",
                                                        fontSize = 12.sp,
                                                        fontWeight = FontWeight.SemiBold,
                                                        color = Color(0xFF10B981)
                                                    )
                                                }
                                            }
                                        }
                                    }
                                }

                                // 2. Security Controls Card
                                Card(
                                    shape = RoundedCornerShape(24.dp),
                                    colors = CardDefaults.cardColors(containerColor = AppCardBg),
                                    modifier = Modifier.fillMaxWidth(),
                                    border = BorderStroke(1.dp, AppCardBorderColor),
                                    elevation = CardDefaults.cardElevation(defaultElevation = 1.dp)
                                ) {
                                    Column(modifier = Modifier.padding(18.dp), verticalArrangement = Arrangement.spacedBy(12.dp)) {
                                        Text(
                                            text = if (isBangla) "ডিভাইস ও সিকিউরিটি কন্ট্রোল" else "DEVICE & SECURITY CONTROLS",
                                            fontSize = 11.sp,
                                            color = AppTextSecondary,
                                            fontWeight = FontWeight.Bold,
                                            letterSpacing = 0.5.sp
                                        )
                                        Spacer(modifier = Modifier.height(2.dp))

                                        Row(
                                            modifier = Modifier.fillMaxWidth(),
                                            horizontalArrangement = Arrangement.SpaceBetween,
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            Column {
                                                Text(
                                                    text = if (isBangla) "বায়োমেট্রিক সাইন ইন" else "Biometric Sign In",
                                                    fontSize = 14.sp,
                                                    color = AppTextPrimary,
                                                    fontWeight = FontWeight.Medium
                                                )
                                                Text(
                                                    text = if (isBangla) "ফিঙ্গারপ্রিন্ট বা ফেস আনলক সক্রিয় রাখুন" else "Fingerprint or Face unlock on app launch",
                                                    fontSize = 11.5.sp,
                                                    color = AppTextSecondary
                                                )
                                            }
                                            val isBioLocked by viewModel.isBiometricLocked.collectAsState()
                                            Switch(
                                                checked = isBioLocked,
                                                onCheckedChange = { viewModel.setBiometricLock(it) },
                                                colors = SwitchDefaults.colors(
                                                    checkedThumbColor = Color.White,
                                                    checkedTrackColor = BrandPurple,
                                                    uncheckedThumbColor = Color.White,
                                                    uncheckedTrackColor = Color(0xFFE2E8F0)
                                                )
                                            )
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    // EDIT PROFILE DIALOG
    if (showEditDialog) {
        EnterpriseGestureModal(
            onDismissRequest = { showEditDialog = false },
            title = "Edit Merchant Profile",
            subtitle = "Swipe down or drag handle to dismiss",
            icon = Icons.Default.Edit
        ) {
            Column(
                verticalArrangement = Arrangement.spacedBy(12.dp)
            ) {
                OutlinedTextField(
                    value = editName,
                    onValueChange = { editName = it },
                    label = { Text("Business Name") },
                    modifier = Modifier.fillMaxWidth()
                )
                OutlinedTextField(
                    value = editType,
                    onValueChange = { editType = it },
                    label = { Text("Business Type") },
                    modifier = Modifier.fillMaxWidth()
                )
                OutlinedTextField(
                    value = editEmail,
                    onValueChange = { editEmail = it },
                    label = { Text("Email Address") },
                    modifier = Modifier.fillMaxWidth()
                )
                OutlinedTextField(
                    value = editPhone,
                    onValueChange = { editPhone = it },
                    label = { Text("Contact Phone") },
                    modifier = Modifier.fillMaxWidth()
                )
                OutlinedTextField(
                    value = editWebsite,
                    onValueChange = { editWebsite = it },
                    label = { Text("Website") },
                    modifier = Modifier.fillMaxWidth()
                )
                // Interactive Photo Upload & Preview Card
                Card(
                    shape = RoundedCornerShape(16.dp),
                    colors = CardDefaults.cardColors(
                        containerColor = if (isDarkMode) Color(0xFF1E1E22) else Color(0xFFF8FAFC)
                    ),
                    border = BorderStroke(1.dp, if (isDarkMode) Color(0xFF2C2C30) else Color(0xFFE2E8F0)),
                    modifier = Modifier.fillMaxWidth()
                ) {
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(12.dp),
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(14.dp)
                    ) {
                        Box(
                            modifier = Modifier
                                .size(56.dp)
                                .clip(CircleShape)
                                .background(if (isDarkMode) Color(0xFF27272A) else Color(0xFFEEF2F6))
                                .border(1.5.dp, BrandPurple, CircleShape),
                            contentAlignment = Alignment.Center
                        ) {
                            if (isUploadingPhoto) {
                                CircularProgressIndicator(
                                    color = BrandPurple,
                                    modifier = Modifier.size(24.dp),
                                    strokeWidth = 2.dp
                                )
                            } else if (editPhotoUrl.isNotEmpty()) {
                                AsyncImage(
                                    model = editPhotoUrl,
                                    contentDescription = "Merchant Photo Preview",
                                    modifier = Modifier.fillMaxSize().clip(CircleShape),
                                    contentScale = androidx.compose.ui.layout.ContentScale.Crop
                                )
                            } else {
                                Icon(
                                    imageVector = Icons.Default.Storefront,
                                    contentDescription = null,
                                    tint = BrandPurple,
                                    modifier = Modifier.size(28.dp)
                                )
                            }
                        }

                        Column(modifier = Modifier.weight(1f)) {
                            Text(
                                text = if (isBangla) "মার্চেন্ট ছবি / লোগো" else "Merchant Photo / Logo",
                                fontSize = 13.sp,
                                fontWeight = FontWeight.SemiBold,
                                color = if (isDarkMode) Color.White else Color(0xFF0F172A)
                            )
                            Spacer(modifier = Modifier.height(6.dp))
                            Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                                Button(
                                    onClick = {
                                        viewModel.isExternalActivityExpected = true
                                        photoPickerLauncher.launch("image/*")
                                    },
                                    colors = ButtonDefaults.buttonColors(containerColor = BrandPurple),
                                    shape = RoundedCornerShape(8.dp),
                                    contentPadding = PaddingValues(horizontal = 12.dp, vertical = 6.dp),
                                    modifier = Modifier.height(34.dp)
                                ) {
                                    Icon(
                                        imageVector = Icons.Default.CameraAlt,
                                        contentDescription = null,
                                        modifier = Modifier.size(14.dp),
                                        tint = Color.White
                                    )
                                    Spacer(modifier = Modifier.width(6.dp))
                                    Text(
                                        text = if (isBangla) "ছবি আপলোড" else "Upload Photo",
                                        fontSize = 11.5.sp,
                                        color = Color.White,
                                        fontWeight = FontWeight.Bold
                                    )
                                }

                                if (editPhotoUrl.isNotEmpty()) {
                                    OutlinedButton(
                                        onClick = {
                                            editPhotoUrl = ""
                                            viewModel.removeMerchantPhoto()
                                            Toast.makeText(context, if (isBangla) "ছবি সরানো হয়েছে" else "Photo removed", Toast.LENGTH_SHORT).show()
                                        },
                                        shape = RoundedCornerShape(8.dp),
                                        border = BorderStroke(1.dp, Color(0xFFEF4444)),
                                        contentPadding = PaddingValues(horizontal = 8.dp, vertical = 6.dp),
                                        modifier = Modifier.height(34.dp)
                                    ) {
                                        Text(
                                            text = if (isBangla) "মুছুন" else "Remove",
                                            fontSize = 11.5.sp,
                                            color = Color(0xFFEF4444),
                                            fontWeight = FontWeight.SemiBold
                                        )
                                    }
                                }
                            }
                        }
                    }
                }

                OutlinedTextField(
                    value = editPhotoUrl,
                    onValueChange = { editPhotoUrl = it },
                    label = { Text("Merchant Photo URL") },
                    modifier = Modifier.fillMaxWidth()
                )

                Spacer(modifier = Modifier.height(12.dp))

                Button(
                    onClick = {
                        val updated = activeProfile.copy(
                            businessName = editName,
                            businessType = editType,
                            email = editEmail,
                            phone = editPhone,
                            website = editWebsite,
                            photoUrl = editPhotoUrl
                        )
                        viewModel.updateMerchantProfile(updated)
                        showEditDialog = false
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = BrandPurple),
                    modifier = Modifier.fillMaxWidth().height(48.dp),
                    shape = RoundedCornerShape(12.dp)
                ) {
                    Text("Save", color = Color.White, fontWeight = FontWeight.Bold, fontSize = 15.sp)
                }
            }
        }
    }
}

@Composable
fun ApiCredentialRow(
    label: String,
    value: String,
    isSecret: Boolean = false,
    onCopy: () -> Unit
) {
    var isHidden by remember { mutableStateOf(isSecret) }
    Column(modifier = Modifier.fillMaxWidth()) {
        Text(
            text = label,
            fontSize = 10.sp,
            color = AppTextSecondary,
            fontWeight = FontWeight.Bold,
            letterSpacing = 1.sp
        )
        Spacer(modifier = Modifier.height(4.dp))
        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.SpaceBetween,
            verticalAlignment = Alignment.CenterVertically
        ) {
            val displayValue = if (isHidden) "••••••••••••••••••••" else value
            Text(
                text = displayValue,
                fontSize = 13.sp,
                fontWeight = FontWeight.Bold,
                color = AppTextPrimary,
                fontFamily = FontFamily.Monospace,
                modifier = Modifier.weight(1f),
                maxLines = 1
            )
            Row(horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                if (isSecret) {
                    IconButton(
                        onClick = { isHidden = !isHidden },
                        modifier = Modifier.size(32.dp)
                    ) {
                        Icon(
                            imageVector = if (isHidden) Icons.Default.VisibilityOff else Icons.Default.Visibility,
                            contentDescription = "Toggle Visibility",
                            tint = AppTextSecondary,
                            modifier = Modifier.size(16.dp)
                        )
                    }
                }
                IconButton(
                    onClick = onCopy,
                    modifier = Modifier.size(32.dp)
                ) {
                    Icon(
                        imageVector = Icons.Default.ContentCopy,
                        contentDescription = "Copy to Clipboard",
                        tint = AppTextSecondary,
                        modifier = Modifier.size(16.dp)
                    )
                }
            }
        }
    }
}

@Composable
fun ProfileRowItem(
    icon: androidx.compose.ui.graphics.vector.ImageVector,
    label: String,
    value: String,
    onClick: () -> Unit,
    valueColor: Color = Color(0xFF191C1E),
    isLast: Boolean = false
) {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .clickable { onClick() }
            .padding(16.dp),
        verticalAlignment = Alignment.CenterVertically
    ) {
        Box(
            modifier = Modifier
                .size(40.dp)
                .background(Color(0xFF431FE7).copy(alpha = 0.05f), RoundedCornerShape(12.dp)),
            contentAlignment = Alignment.Center
        ) {
            Icon(
                imageVector = icon,
                contentDescription = null,
                tint = Color(0xFF431FE7),
                modifier = Modifier.size(22.dp)
            )
        }

        Spacer(modifier = Modifier.width(16.dp))

        Column(modifier = Modifier.weight(1f)) {
            Text(
                text = label,
                fontSize = 11.sp,
                color = Color(0xFF787588),
                fontWeight = FontWeight.Bold,
                letterSpacing = 0.5.sp
            )
            Spacer(modifier = Modifier.height(2.dp))
            Text(
                text = value,
                fontSize = 14.sp,
                fontWeight = FontWeight.Bold,
                color = valueColor
            )
        }

        Icon(
            imageVector = Icons.Default.ChevronRight,
            contentDescription = "Edit field",
            tint = Color(0xFFC8C4D9),
            modifier = Modifier.size(20.dp)
        )
    }
}

@Composable
fun ProfileBankRowItem(
    label: String,
    mainValue: String,
    subValue: String?,
    onClick: () -> Unit,
    isLast: Boolean = false
) {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .clickable { onClick() }
            .padding(16.dp),
        verticalAlignment = Alignment.CenterVertically
    ) {
        Column(modifier = Modifier.weight(1f)) {
            Text(
                text = label,
                fontSize = 11.sp,
                color = Color(0xFF787588),
                fontWeight = FontWeight.Bold,
                letterSpacing = 0.5.sp
            )
            Spacer(modifier = Modifier.height(4.dp))
            Text(
                text = mainValue,
                fontSize = 15.sp,
                fontWeight = FontWeight.Bold,
                color = Color(0xFF191C1E)
            )
            if (subValue != null) {
                Spacer(modifier = Modifier.height(2.dp))
                Text(
                    text = subValue,
                    fontSize = 12.sp,
                    color = Color(0xFF787588),
                    fontWeight = FontWeight.Medium
                )
            }
        }

        Icon(
            imageVector = Icons.Default.ChevronRight,
            contentDescription = "Edit field",
            tint = Color(0xFFC8C4D9),
            modifier = Modifier.size(20.dp)
        )
    }
}

// 14. PAYMENT METHODS / NUMBERS SCREEN
@Composable
fun PaymentMethodsScreen(viewModel: AppViewModel) {
    val numbers by viewModel.merchantNumbers.collectAsState()
    var selectedTab by remember { mutableStateOf("All") }
    var showAddNumberDialog by remember { mutableStateOf(false) }

    // Filtered numbers based on selection
    val filteredNumbers = remember(numbers, selectedTab) {
        if (selectedTab == "All") {
            numbers
        } else {
            numbers.filter { it.method.equals(selectedTab, ignoreCase = true) }
        }
    }

    val isDarkMode by viewModel.isDarkMode.collectAsState()
    SideEffect { isDarkModeGlobal = isDarkMode }

    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(AppScreenBg)
    ) {
        Column(
            modifier = Modifier
                .fillMaxSize()
        ) {
            // HEADER SECTION
            GradientTopBar(
                title = "Payment Methods",
                subtitle = "Manage recipient MFS accounts",
                onBack = { viewModel.goBack() },
                gradient = GradPrimary
            )

            // FILTER TABS
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = 24.dp, vertical = 12.dp)
                    .horizontalScroll(rememberScrollState()),
                horizontalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                listOf("All", "bKash", "Nagad", "Rocket").forEach { tab ->
                    val isSelected = selectedTab == tab
                    Box(
                        modifier = Modifier
                            .background(
                                color = if (isSelected) BrandPurple else AppCardBg,
                                shape = RoundedCornerShape(12.dp)
                            )
                            .border(BorderStroke(1.dp, if (isSelected) Color.Transparent else AppCardBorderColor), RoundedCornerShape(12.dp))
                            .clickable { selectedTab = tab }
                            .padding(horizontal = 20.dp, vertical = 8.dp)
                    ) {
                        Text(
                            text = tab,
                            color = if (isSelected) Color.White else AppTextSecondary,
                            fontWeight = FontWeight.Bold,
                            fontSize = 13.sp
                        )
                    }
                }
            }

            // MAIN LIST
            LazyColumn(
                modifier = Modifier
                    .fillMaxWidth()
                    .weight(1f),
                contentPadding = PaddingValues(horizontal = 24.dp, vertical = 8.dp),
                verticalArrangement = Arrangement.spacedBy(16.dp)
            ) {
                // Render payments methods
                items(filteredNumbers) { num ->
                    Card(
                        shape = RoundedCornerShape(24.dp),
                        colors = CardDefaults.cardColors(containerColor = AppCardBg),
                        border = BorderStroke(1.dp, AppCardBorderColor),
                        modifier = Modifier.fillMaxWidth()
                    ) {
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(20.dp),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Row(
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.spacedBy(16.dp)
                            ) {
                                // Branded Logo Box
                                Box(
                                    modifier = Modifier
                                        .size(48.dp)
                                        .background(
                                            color = when (num.method) {
                                                "bKash" -> Color(0xFFE2136E)
                                                "Nagad" -> Color(0xFFF7941D)
                                                else -> Color(0xFF8C3494)
                                            },
                                            shape = RoundedCornerShape(12.dp)
                                        ),
                                    contentAlignment = Alignment.Center
                                ) {
                                    Text(
                                        text = when (num.method) {
                                            "bKash" -> "bK"
                                            "Nagad" -> "N"
                                            else -> "R"
                                        },
                                        color = Color.White,
                                        fontWeight = FontWeight.Bold,
                                        fontSize = 18.sp
                                    )
                                }

                                Column {
                                    Text(
                                        text = num.method,
                                        fontSize = 16.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = AppTextPrimary
                                    )
                                    Spacer(modifier = Modifier.height(4.dp))
                                    Text(
                                        text = num.number,
                                        fontSize = 14.sp,
                                        fontWeight = FontWeight.SemiBold,
                                        color = AppTextPrimary
                                    )
                                    Spacer(modifier = Modifier.height(2.dp))
                                    Text(
                                        text = "${num.type} Account",
                                        fontSize = 11.sp,
                                        color = AppTextSecondary
                                    )
                                    if (!num.qrCodeUrl.isNullOrBlank()) {
                                        Spacer(modifier = Modifier.height(2.dp))
                                        Row(verticalAlignment = Alignment.CenterVertically) {
                                            Icon(Icons.Outlined.QrCode, contentDescription = null, tint = BrandPurple, modifier = Modifier.size(12.dp))
                                            Spacer(modifier = Modifier.width(4.dp))
                                            Text(
                                                text = "QR Code Attached",
                                                fontSize = 10.sp,
                                                fontWeight = FontWeight.Bold,
                                                color = BrandPurple
                                            )
                                        }
                                    }
                                }
                            }

                            // Right-side controls (Active status + default switcher)
                            Column(
                                horizontalAlignment = Alignment.End,
                                verticalArrangement = Arrangement.spacedBy(8.dp)
                            ) {
                                Row(
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.spacedBy(6.dp)
                                ) {
                                    Box(
                                        modifier = Modifier
                                            .size(8.dp)
                                            .background(
                                                color = if (num.isActive) SuccessGreen else Color.Gray,
                                                shape = CircleShape
                                            )
                                    )
                                    Text(
                                        text = if (num.isActive) "Active" else "Inactive",
                                        color = if (num.isActive) SuccessGreen else Color.Gray,
                                        fontWeight = FontWeight.Bold,
                                        fontSize = 11.sp
                                    )
                                }

                                Row(
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.spacedBy(8.dp)
                                ) {
                                    if (num.isDefault) {
                                        Box(
                                            modifier = Modifier
                                                .background(BrandLightPurple, RoundedCornerShape(8.dp))
                                                .padding(horizontal = 8.dp, vertical = 4.dp)
                                        ) {
                                            Text(
                                                text = "DEFAULT",
                                                color = BrandPurple,
                                                fontSize = 9.sp,
                                                fontWeight = FontWeight.Bold
                                            )
                                        }
                                    } else {
                                        TextButton(
                                            onClick = { viewModel.setMerchantNumberDefault(num.number) },
                                            contentPadding = PaddingValues(0.dp),
                                            modifier = Modifier.height(24.dp)
                                        ) {
                                            Text(
                                                text = "Set Default",
                                                color = BrandPurple,
                                                fontSize = 11.sp,
                                                fontWeight = FontWeight.Bold
                                            )
                                        }
                                    }

                                    Switch(
                                        checked = num.isActive,
                                        onCheckedChange = { viewModel.toggleMerchantNumber(num.number) },
                                        colors = SwitchDefaults.colors(
                                            checkedThumbColor = Color.White,
                                            checkedTrackColor = BrandPurple,
                                            uncheckedThumbColor = Color.White,
                                            uncheckedTrackColor = Color(0xFFE2E8F0)
                                        )
                                    )
                                }
                            }
                        }
                    }
                }

                // ADD NEW NUMBER DASHED BUTTON
                item {
                    Spacer(modifier = Modifier.height(8.dp))
                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .background(Color.Transparent)
                            .border(
                                BorderStroke(2.dp, BrandPurple.copy(alpha = 0.2f)),
                                RoundedCornerShape(24.dp)
                            )
                            .clickable { showAddNumberDialog = true }
                            .padding(28.dp),
                        contentAlignment = Alignment.Center
                    ) {
                        Column(
                            horizontalAlignment = Alignment.CenterHorizontally,
                            verticalArrangement = Arrangement.Center
                        ) {
                            Row(
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.spacedBy(8.dp)
                            ) {
                                Icon(
                                    imageVector = Icons.Default.Add,
                                    contentDescription = null,
                                    tint = BrandPurple,
                                    modifier = Modifier.size(20.dp)
                                )
                                Text(
                                    text = "Add New Number",
                                    color = BrandPurple,
                                    fontWeight = FontWeight.Bold,
                                    fontSize = 16.sp
                                )
                            }
                            Spacer(modifier = Modifier.height(8.dp))
                            Text(
                                text = "Add bKash, Nagad or Rocket number & custom QR code to receive payments",
                                color = AppTextSecondary,
                                fontSize = 12.sp,
                                textAlign = TextAlign.Center,
                                modifier = Modifier.padding(horizontal = 16.dp)
                            )
                        }
                    }
                }
            }
        }

        // Add Number Overlay
        if (showAddNumberDialog) {
            AddNumberDialog(viewModel) { showAddNumberDialog = false }
        }
    }
}

@Composable
fun AddNumberDialog(viewModel: AppViewModel, onDismiss: () -> Unit) {
    var number by remember { mutableStateOf("") }
    var selectedMethod by remember { mutableStateOf("bKash") }
    var selectedType by remember { mutableStateOf("Personal") }
    var qrCodeUrl by remember { mutableStateOf("") }

    EnterpriseGestureModal(
        onDismissRequest = onDismiss,
        title = "Add Payment Number",
        subtitle = "Set MFS number & optional custom QR code image",
        icon = Icons.Outlined.Phone
    ) {
        Column(horizontalAlignment = Alignment.CenterHorizontally) {
            OutlinedTextField(
                value = number,
                onValueChange = { number = it },
                label = { Text("Mobile Number") },
                placeholder = { Text("017XXXXXXXX") },
                modifier = Modifier.fillMaxWidth()
            )
            Spacer(modifier = Modifier.height(12.dp))

            // Method Selector
            Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceEvenly) {
                listOf("bKash", "Nagad", "Rocket", "Upay").forEach { m ->
                    val sel = selectedMethod == m
                    OutlinedButton(
                        onClick = { selectedMethod = m },
                        colors = ButtonDefaults.outlinedButtonColors(
                            containerColor = if (sel) BrandLightPurple else Color.White,
                            contentColor = if (sel) BrandPurple else Color.DarkGray
                        )
                    ) {
                        Text(m, fontSize = 9.sp, fontWeight = FontWeight.Bold)
                    }
                }
            }

            Spacer(modifier = Modifier.height(12.dp))

            // Type Selector
            Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceEvenly) {
                listOf("Personal", "Agent", "Merchant").forEach { t ->
                    val sel = selectedType == t
                    OutlinedButton(
                        onClick = { selectedType = t },
                        colors = ButtonDefaults.outlinedButtonColors(
                            containerColor = if (sel) BrandLightPurple else Color.White,
                            contentColor = if (sel) BrandPurple else Color.DarkGray
                        )
                    ) {
                        Text(t, fontSize = 10.sp, fontWeight = FontWeight.Bold)
                    }
                }
            }

            Spacer(modifier = Modifier.height(12.dp))

            // QR Code Image URL field
            OutlinedTextField(
                value = qrCodeUrl,
                onValueChange = { qrCodeUrl = it },
                label = { Text("QR Code Image URL (Optional)") },
                placeholder = { Text("https://...") },
                leadingIcon = { Icon(Icons.Outlined.QrCode, contentDescription = null, tint = BrandPurple) },
                singleLine = true,
                modifier = Modifier.fillMaxWidth()
            )
            Text(
                text = "Custom QR image URL for $selectedMethod checkout widget",
                fontSize = 10.sp,
                color = Color.Gray,
                modifier = Modifier.padding(top = 2.dp, start = 4.dp).align(Alignment.Start)
            )

            Spacer(modifier = Modifier.height(20.dp))

            Button(
                onClick = {
                    if (number.isNotEmpty()) {
                        viewModel.addMerchantNumber(number, selectedMethod, selectedType, qrCodeUrl.ifBlank { null })
                        onDismiss()
                    }
                },
                colors = ButtonDefaults.buttonColors(containerColor = BrandPurple),
                shape = RoundedCornerShape(12.dp),
                modifier = Modifier.fillMaxWidth().height(48.dp)
            ) {
                Text("Add Number & Sync Admin DB", color = Color.White, fontWeight = FontWeight.Bold, fontSize = 15.sp)
            }
        }
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// DEVICE MANAGER SCREEN — Fully Dynamic Hardware & SIM Receiver Monitor
// ─────────────────────────────────────────────────────────────────────────────
@Composable
fun DeviceManagerScreen(viewModel: AppViewModel) {
    val isDarkMode by viewModel.isDarkMode.collectAsState()
    SideEffect { isDarkModeGlobal = isDarkMode }

    val devices by viewModel.devices.collectAsState()
    var isSendingHeartbeat by remember { mutableStateOf(false) }
    var selectedFilter by remember { mutableStateOf("All") }

    val context = LocalContext.current
    val currentDeviceId = remember { viewModel.installationId }
    val currentModel = remember { "${android.os.Build.MANUFACTURER} ${android.os.Build.MODEL}" }

    val filteredDevices = remember(devices, selectedFilter) {
        when (selectedFilter) {
            "Online" -> devices.filter { it.status == "ONLINE" }
            "Offline" -> devices.filter { it.status == "OFFLINE" }
            else -> devices
        }
    }

    val pageBg = if (isDarkMode) Color(0xFF09090B) else Color(0xFFF8FAFC)
    val cardBg = if (isDarkMode) Color(0xFF141416) else Color(0xFFFFFFFF)
    val cardBorder = if (isDarkMode) Color(0xFF27272A) else Color(0xFFE2E8F0)
    val textMain = if (isDarkMode) Color(0xFFF8FAFC) else Color(0xFF0F172A)
    val textMuted = if (isDarkMode) Color(0xFFA1A1AA) else Color(0xFF64748B)

    LaunchedEffect(Unit) {
        viewModel.sendDeviceHeartbeat()
    }

    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(pageBg)
    ) {
        Column(
            modifier = Modifier
                .fillMaxSize()
                .statusBarsPadding()
                .navigationBarsPadding()
        ) {
            // TOP BAR
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = 16.dp, vertical = 12.dp),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(12.dp)
                ) {
                    IconButton(
                        onClick = { viewModel.goBack() },
                        modifier = Modifier
                            .size(38.dp)
                            .clip(CircleShape)
                            .background(if (isDarkMode) Color(0xFF1E1E22) else Color(0xFFEDF2F7))
                    ) {
                        Icon(
                            imageVector = Icons.AutoMirrored.Filled.ArrowBack,
                            contentDescription = "Back",
                            tint = textMain,
                            modifier = Modifier.size(20.dp)
                        )
                    }

                    Column {
                        Text(
                            text = "Device Manager (ডিভাইস ম্যানেজার)",
                            fontSize = 17.sp,
                            fontWeight = FontWeight.Bold,
                            color = textMain
                        )
                        Text(
                            text = "Active SMS receiver phones & POS terminals",
                            fontSize = 11.5.sp,
                            color = textMuted
                        )
                    }
                }

                IconButton(
                    onClick = {
                        isSendingHeartbeat = true
                        viewModel.sendDeviceHeartbeat {
                            isSendingHeartbeat = false
                            viewModel.triggerSync()
                        }
                    },
                    modifier = Modifier
                        .size(38.dp)
                        .clip(CircleShape)
                        .background(if (isDarkMode) Color(0xFF1E1E22) else Color(0xFFEDF2F7))
                ) {
                    Icon(
                        imageVector = Icons.Default.Refresh,
                        contentDescription = "Refresh",
                        tint = textMain,
                        modifier = Modifier.size(20.dp)
                    )
                }
            }

            // CONTENT BODY
            Column(
                modifier = Modifier
                    .weight(1f)
                    .fillMaxWidth()
                    .verticalScroll(rememberScrollState())
                    .padding(horizontal = 16.dp, vertical = 8.dp),
                verticalArrangement = Arrangement.spacedBy(16.dp)
            ) {
                // CURRENT THIS DEVICE HEADER CARD
                Card(
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(20.dp),
                    colors = CardDefaults.cardColors(containerColor = cardBg),
                    border = BorderStroke(1.dp, cardBorder)
                ) {
                    Column(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(16.dp),
                        verticalArrangement = Arrangement.spacedBy(12.dp)
                    ) {
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Row(
                                modifier = Modifier
                                    .weight(1f)
                                    .padding(end = 8.dp),
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.spacedBy(12.dp)
                            ) {
                                Box(
                                    modifier = Modifier
                                        .size(46.dp)
                                        .clip(RoundedCornerShape(12.dp))
                                        .background(Color(0xFF8B5CF6).copy(alpha = 0.12f)),
                                    contentAlignment = Alignment.Center
                                ) {
                                    Icon(
                                        imageVector = Icons.Outlined.Smartphone,
                                        contentDescription = null,
                                        tint = Color(0xFF8B5CF6),
                                        modifier = Modifier.size(24.dp)
                                    )
                                }
                                Column(modifier = Modifier.weight(1f, fill = false)) {
                                    Row(
                                        verticalAlignment = Alignment.CenterVertically,
                                        horizontalArrangement = Arrangement.spacedBy(6.dp)
                                    ) {
                                        Text(
                                            text = currentModel,
                                            fontSize = 15.sp,
                                            fontWeight = FontWeight.Bold,
                                            color = textMain,
                                            maxLines = 1,
                                            overflow = TextOverflow.Ellipsis,
                                            modifier = Modifier.weight(1f, fill = false)
                                        )
                                        Surface(
                                            shape = RoundedCornerShape(8.dp),
                                            color = BrandLightPurple
                                        ) {
                                            Text(
                                                text = "THIS PHONE",
                                                fontSize = 9.sp,
                                                fontWeight = FontWeight.Black,
                                                color = BrandPurple,
                                                modifier = Modifier.padding(horizontal = 6.dp, vertical = 2.dp),
                                                softWrap = false,
                                                maxLines = 1
                                            )
                                        }
                                    }
                                    Text(
                                        text = "ID: ${currentDeviceId.take(12)}...",
                                        fontSize = 11.sp,
                                        color = textMuted,
                                        maxLines = 1
                                    )
                                }
                            }

                            // Status Indicator
                            Surface(
                                shape = RoundedCornerShape(12.dp),
                                color = Color(0xFF10B981).copy(alpha = 0.15f),
                                border = BorderStroke(0.8.dp, Color(0xFF10B981).copy(alpha = 0.4f))
                            ) {
                                Row(
                                    modifier = Modifier.padding(horizontal = 8.dp, vertical = 4.dp),
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.spacedBy(4.dp)
                                ) {
                                    Box(
                                        modifier = Modifier
                                            .size(6.dp)
                                            .clip(CircleShape)
                                            .background(Color(0xFF10B981))
                                    )
                                    Text(
                                        text = "ACTIVE RECEIVER",
                                        fontSize = 9.5.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = Color(0xFF10B981),
                                        softWrap = false,
                                        maxLines = 1
                                    )
                                }
                            }
                        }

                        HorizontalDivider(color = cardBorder, thickness = 0.8.dp)

                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Text(
                                text = "Keep phone powered ON & connected for automatic payment verification",
                                fontSize = 11.sp,
                                color = textMuted,
                                modifier = Modifier.weight(1f)
                            )
                            Button(
                                onClick = {
                                    isSendingHeartbeat = true
                                    viewModel.sendDeviceHeartbeat {
                                        isSendingHeartbeat = false
                                        Toast.makeText(context, "Live device heartbeat sent!", Toast.LENGTH_SHORT).show()
                                    }
                                },
                                colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF8B5CF6)),
                                shape = RoundedCornerShape(12.dp),
                                contentPadding = PaddingValues(horizontal = 12.dp, vertical = 6.dp),
                                modifier = Modifier.height(34.dp),
                                enabled = !isSendingHeartbeat
                            ) {
                                Text(
                                    text = if (isSendingHeartbeat) "Syncing..." else "Send Heartbeat",
                                    fontSize = 11.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = Color.White
                                )
                            }
                        }
                    }
                }

                // FILTER TABS & COUNT
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Text(
                        text = "Registered Devices (${filteredDevices.size})",
                        fontSize = 15.sp,
                        fontWeight = FontWeight.Bold,
                        color = textMain
                    )

                    Row(horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                        listOf("All", "Online", "Offline").forEach { tab ->
                            val isSel = selectedFilter == tab
                            Box(
                                modifier = Modifier
                                    .clip(RoundedCornerShape(8.dp))
                                    .background(if (isSel) BrandPurple else if (isDarkMode) Color(0xFF1E1E22) else Color(0xFFEDF2F7))
                                    .clickable { selectedFilter = tab }
                                    .padding(horizontal = 10.dp, vertical = 4.dp)
                            ) {
                                Text(
                                    text = tab,
                                    fontSize = 11.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = if (isSel) Color.White else textMuted
                                )
                            }
                        }
                    }
                }

                // DYNAMIC DEVICES LIST
                if (filteredDevices.isEmpty()) {
                    Card(
                        modifier = Modifier.fillMaxWidth(),
                        shape = RoundedCornerShape(16.dp),
                        colors = CardDefaults.cardColors(containerColor = cardBg),
                        border = BorderStroke(1.dp, cardBorder)
                    ) {
                        Column(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(32.dp),
                            horizontalAlignment = Alignment.CenterHorizontally,
                            verticalArrangement = Arrangement.spacedBy(8.dp)
                        ) {
                            Icon(
                                imageVector = Icons.Outlined.PhonelinkOff,
                                contentDescription = null,
                                tint = textMuted,
                                modifier = Modifier.size(36.dp)
                            )
                            Text(
                                text = "No registered devices found",
                                fontSize = 14.sp,
                                fontWeight = FontWeight.Bold,
                                color = textMain
                            )
                            Text(
                                text = "Devices running the SwapnoPay app automatically register here when online.",
                                fontSize = 11.5.sp,
                                color = textMuted,
                                textAlign = TextAlign.Center
                            )
                        }
                    }
                } else {
                    Column(verticalArrangement = Arrangement.spacedBy(10.dp)) {
                        filteredDevices.forEach { dev ->
                            val isThisDevice = dev.id == currentDeviceId
                            val isOnline = dev.status == "ONLINE"

                            Card(
                                modifier = Modifier.fillMaxWidth(),
                                shape = RoundedCornerShape(16.dp),
                                colors = CardDefaults.cardColors(containerColor = cardBg),
                                border = BorderStroke(1.dp, cardBorder)
                            ) {
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(14.dp),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Row(
                                        modifier = Modifier
                                            .weight(1f)
                                            .padding(end = 8.dp),
                                        verticalAlignment = Alignment.CenterVertically,
                                        horizontalArrangement = Arrangement.spacedBy(12.dp)
                                    ) {
                                        Box(
                                            modifier = Modifier
                                                .size(42.dp)
                                                .clip(CircleShape)
                                                .background(
                                                    if (isOnline) Color(0xFF10B981).copy(alpha = 0.12f)
                                                    else Color(0xFFEF4444).copy(alpha = 0.12f)
                                                ),
                                            contentAlignment = Alignment.Center
                                        ) {
                                            Icon(
                                                imageVector = if (isOnline) Icons.Default.PhoneAndroid else Icons.Outlined.PhonelinkErase,
                                                contentDescription = null,
                                                tint = if (isOnline) Color(0xFF10B981) else Color(0xFFEF4444),
                                                modifier = Modifier.size(20.dp)
                                            )
                                        }

                                        Column(
                                            modifier = Modifier.weight(1f, fill = false),
                                            verticalArrangement = Arrangement.spacedBy(2.dp)
                                        ) {
                                            Row(
                                                verticalAlignment = Alignment.CenterVertically,
                                                horizontalArrangement = Arrangement.spacedBy(6.dp)
                                            ) {
                                                Text(
                                                    text = dev.deviceName.ifBlank { "Android Device" },
                                                    fontSize = 14.sp,
                                                    fontWeight = FontWeight.Bold,
                                                    color = textMain,
                                                    maxLines = 1,
                                                    overflow = TextOverflow.Ellipsis,
                                                    modifier = Modifier.weight(1f, fill = false)
                                                )
                                                if (isThisDevice) {
                                                    Text(
                                                        text = "(This Phone)",
                                                        fontSize = 10.sp,
                                                        fontWeight = FontWeight.Bold,
                                                        color = BrandPurple,
                                                        softWrap = false,
                                                        maxLines = 1
                                                    )
                                                }
                                            }
                                            Row(
                                                verticalAlignment = Alignment.CenterVertically,
                                                horizontalArrangement = Arrangement.spacedBy(8.dp)
                                            ) {
                                                Row(
                                                    verticalAlignment = Alignment.CenterVertically,
                                                    horizontalArrangement = Arrangement.spacedBy(3.dp)
                                                ) {
                                                    Icon(
                                                        imageVector = Icons.Default.BatteryStd,
                                                        contentDescription = null,
                                                        tint = when {
                                                            dev.batteryLevel > 50 -> Color(0xFF10B981)
                                                            dev.batteryLevel > 20 -> Color(0xFFF59E0B)
                                                            else -> Color(0xFFEF4444)
                                                        },
                                                        modifier = Modifier.size(13.dp)
                                                    )
                                                    Text(
                                                        text = "${dev.batteryLevel}%",
                                                        fontSize = 11.sp,
                                                        color = textMuted
                                                    )
                                                }
                                                Text(
                                                    text = "•",
                                                    fontSize = 11.sp,
                                                    color = textMuted
                                                )
                                                Text(
                                                    text = "Last sync: ${formatTime(dev.lastSyncTime)}",
                                                    fontSize = 11.sp,
                                                    color = textMuted,
                                                    maxLines = 1,
                                                    overflow = TextOverflow.Ellipsis
                                                )
                                            }
                                        }
                                    }

                                    // Right Status Badge
                                    Surface(
                                        shape = RoundedCornerShape(8.dp),
                                        color = if (isOnline) Color(0xFF10B981).copy(alpha = 0.12f) else Color(0xFF64748B).copy(alpha = 0.12f)
                                    ) {
                                        Text(
                                            text = if (isOnline) "ONLINE" else "OFFLINE",
                                            fontSize = 10.sp,
                                            fontWeight = FontWeight.Bold,
                                            color = if (isOnline) Color(0xFF10B981) else Color(0xFF64748B),
                                            modifier = Modifier.padding(horizontal = 8.dp, vertical = 3.dp),
                                            softWrap = false,
                                            maxLines = 1
                                        )
                                    }
                                }
                            }
                        }
                    }
                }

                // MULTI-DEVICE GUIDANCE BANNER
                Card(
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(16.dp),
                    colors = CardDefaults.cardColors(containerColor = BrandPurple.copy(alpha = 0.06f)),
                    border = BorderStroke(1.dp, BrandPurple.copy(alpha = 0.18f))
                ) {
                    Row(
                        modifier = Modifier.padding(14.dp),
                        verticalAlignment = Alignment.Top,
                        horizontalArrangement = Arrangement.spacedBy(10.dp)
                    ) {
                        Icon(
                            imageVector = Icons.Default.Info,
                            contentDescription = null,
                            tint = BrandPurple,
                            modifier = Modifier.size(18.dp)
                        )
                        Column(verticalArrangement = Arrangement.spacedBy(4.dp)) {
                            Text(
                                text = "Multi-Device SIM Gateway Setup",
                                fontSize = 12.5.sp,
                                fontWeight = FontWeight.Bold,
                                color = BrandPurple
                            )
                            Text(
                                text = "You can install the SwapnoPay Android app on multiple smartphones (e.g. bKash SIM on Phone 1, Nagad SIM on Phone 2). All active devices will appear here dynamically.",
                                fontSize = 11.sp,
                                color = textMuted,
                                lineHeight = 16.sp
                            )
                        }
                    }
                }
            }
        }
    }
}

@Composable
fun PaymentGatewaySettingsScreen(viewModel: AppViewModel) {
    val isDarkMode by viewModel.isDarkMode.collectAsState()
    val isTestingConnection by viewModel.isRunningSystemTest.collectAsState()
    val gatewayTestError by viewModel.systemTestError.collectAsState()
    val gatewayConnected by viewModel.supabaseConnected.collectAsState()
    val supabaseUrlValue by viewModel.supabaseUrl.collectAsState()
    val isRealDb = supabaseUrlValue.isNotBlank() && !supabaseUrlValue.contains("abc123xyz") && !supabaseUrlValue.contains("def456uvw")
    val isDbOnline = gatewayConnected || isRealDb
    val gatewayOrders by viewModel.orders.collectAsState()
    val gatewayPayments by viewModel.payments.collectAsState()
    val gatewayProfile by viewModel.activeProfile.collectAsState()
    val gatewayNumbers by viewModel.merchantNumbers.collectAsState()
    val gatewaySettingsStatus by viewModel.gatewaySettingsStatus.collectAsState()
    val gatewayReceiptStatus by viewModel.gatewayReceiptStatus.collectAsState()
    val gatewayServiceStatus by viewModel.gatewayServiceStatus.collectAsState()
    val merchantApiKey by viewModel.merchantApiKey.collectAsState()
    val merchantApiKeyPreview by viewModel.merchantApiKeyPreview.collectAsState()
    val isGeneratingApiKey by viewModel.isGeneratingApiKey.collectAsState()
    var isKeyRevealed by remember { mutableStateOf(false) }
    var showRegenerateDialog by remember { mutableStateOf(false) }
    SideEffect { isDarkModeGlobal = isDarkMode }
    LaunchedEffect(gatewayProfile.id) {
        viewModel.refreshGatewayConfig()
        viewModel.fetchMerchantApiKey()
        if (!gatewayConnected && isRealDb) {
            viewModel.runSupabaseSystemTest()
        }
    }

    val context = LocalContext.current
    val clipboardManager = LocalClipboardManager.current

    val isGatewayPermissionGranted by viewModel.isGatewayPermissionGranted.collectAsState()
    val gatewayConfigState by viewModel.gatewayConfig.collectAsState()

    // Only non-secret merchant database policy is editable on the device.
    var minAmount by remember(gatewayConfigState) { mutableStateOf(gatewayConfigState.minAmount.toString()) }
    var maxAmount by remember(gatewayConfigState) { mutableStateOf(gatewayConfigState.maxAmount.toString()) }
    var dailyLimit by remember(gatewayConfigState) { mutableStateOf(gatewayConfigState.dailyLimit.toString()) }
    var retryCount by remember(gatewayConfigState) { mutableStateOf(gatewayConfigState.retryCount.toString()) }
    var autoFailover by remember(gatewayConfigState) { mutableStateOf(gatewayConfigState.autoFailover) }

    val webhookUrl = "https://api.swapnopay.top/v1/payment-receipts"
    var successCallbackUrl by remember(gatewayConfigState) { mutableStateOf(gatewayConfigState.successCallbackUrl) }
    var failureCallbackUrl by remember(gatewayConfigState) { mutableStateOf(gatewayConfigState.failureCallbackUrl) }
    var cancelCallbackUrl by remember(gatewayConfigState) { mutableStateOf(gatewayConfigState.cancelCallbackUrl) }

    // Official verified-payment receipt states
    var emailNotificationsEnabled by remember(gatewayConfigState) { mutableStateOf(gatewayConfigState.emailNotificationsEnabled) }
    var customerReceiptsEnabled by remember(gatewayConfigState) { mutableStateOf(gatewayConfigState.customerReceiptsEnabled) }
    var notificationEmail by remember(gatewayConfigState) { mutableStateOf(gatewayConfigState.notificationEmail.ifBlank { gatewayProfile.email }) }
    var emailOnSuccess by remember(gatewayConfigState) { mutableStateOf(gatewayConfigState.emailOnSuccess) }

    val paidGatewayOrders = gatewayOrders.count { it.status == "PAID" }
    val gatewaySuccessRate = if (gatewayOrders.isEmpty()) 0.0 else paidGatewayOrders * 100.0 / gatewayOrders.size
    val todayStart = remember {
        java.util.Calendar.getInstance().apply {
            set(java.util.Calendar.HOUR_OF_DAY, 0)
            set(java.util.Calendar.MINUTE, 0)
            set(java.util.Calendar.SECOND, 0)
            set(java.util.Calendar.MILLISECOND, 0)
        }.timeInMillis
    }
    val todayGatewayPayments = gatewayPayments.filter { it.timestamp >= todayStart && it.status == "MATCHED" }

    var showEditRulesDialog by remember { mutableStateOf(false) }
    var showEditWebhookDialog by remember { mutableStateOf(false) }
    var showEditNotificationsDialog by remember { mutableStateOf(false) }
    val activeMethods = remember(gatewayNumbers) {
        listOf("bKash", "Nagad", "Rocket", "Upay").associateWith { method ->
            gatewayNumbers.any { it.method.equals(method, ignoreCase = true) && it.isActive }
        }
    }
    val gatewayOperational = isDbOnline && isGatewayPermissionGranted && activeMethods.values.any { it } &&
        gatewayServiceStatus.endsWith("ready")

    // Color Theme Mapping (Dynamic White Mode & Dark Mode)
    val pageBg = if (isDarkMode) Color(0xFF09090B) else Color(0xFFF8FAFC)
    val cardBg = if (isDarkMode) Color(0xFF141416) else Color(0xFFFFFFFF)
    val cardBorder = if (isDarkMode) Color(0xFF27272A) else Color(0xFFE2E8F0)
    val textMain = if (isDarkMode) Color(0xFFF8FAFC) else Color(0xFF0F172A)
    val textMuted = if (isDarkMode) Color(0xFFA1A1AA) else Color(0xFF64748B)
    val goldColor = Color(0xFFF59E0B) // Pixel-perfect Golden Primary
    val greenColor = Color(0xFF22C55E)

    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(pageBg)
    ) {
        Column(
            modifier = Modifier
                .fillMaxSize()
                .statusBarsPadding()
                .navigationBarsPadding()
        ) {
            // ── TOP APP BAR ────────────────────────────────────────────────────────
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = 16.dp, vertical = 12.dp),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(12.dp)
                ) {
                    IconButton(
                        onClick = { viewModel.goBack() },
                        modifier = Modifier
                            .size(38.dp)
                            .clip(CircleShape)
                            .background(if (isDarkMode) Color(0xFF1E1E22) else Color(0xFFEDF2F7))
                    ) {
                        Icon(
                            imageVector = Icons.AutoMirrored.Filled.ArrowBack,
                            contentDescription = "Back",
                            tint = textMain,
                            modifier = Modifier.size(20.dp)
                        )
                    }

                    Column {
                        Text(
                            text = "Payment Gateway Settings",
                            fontSize = 18.sp,
                            fontWeight = FontWeight.Bold,
                            color = textMain
                        )
                        Text(
                            text = "Merchant-database payment verification and receipts",
                            fontSize = 12.sp,
                            color = textMuted
                        )
                    }
                }

                // Notification shortcut. No fabricated unread counter is shown.
                Box(contentAlignment = Alignment.TopEnd) {
                    IconButton(
                        onClick = { viewModel.navigateTo("Notifications") },
                        modifier = Modifier
                            .size(38.dp)
                            .clip(CircleShape)
                            .background(if (isDarkMode) Color(0xFF1E1E22) else Color(0xFFEDF2F7))
                    ) {
                        Icon(
                            imageVector = Icons.Outlined.Notifications,
                            contentDescription = "Notifications",
                            tint = textMain,
                            modifier = Modifier.size(20.dp)
                        )
                    }
                }
            }

            // ── SCROLLABLE CONTENT BODY ──────────────────────────────────────────
            Column(
                modifier = Modifier
                    .weight(1f)
                    .fillMaxWidth()
                    .verticalScroll(rememberScrollState())
                    .padding(horizontal = 16.dp, vertical = 8.dp),
                verticalArrangement = Arrangement.spacedBy(18.dp)
            ) {
                // 1. ACTIVE VERIFIED MFS GATEWAY
                Card(
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(20.dp),
                    colors = CardDefaults.cardColors(containerColor = cardBg),
                    border = BorderStroke(1.dp, cardBorder)
                ) {
                    Column(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(16.dp)
                    ) {
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.Top
                        ) {
                            // Avatar + Brand Info
                            Row(
                                modifier = Modifier
                                    .weight(1f)
                                    .padding(end = 8.dp),
                                horizontalArrangement = Arrangement.spacedBy(12.dp),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                // Avatar Circle 'S' with badge
                                Box(contentAlignment = Alignment.BottomEnd) {
                                    Box(
                                        modifier = Modifier
                                            .size(48.dp)
                                            .clip(CircleShape)
                                            .background(if (isDarkMode) Color(0xFF261D0C) else Color(0xFFFEF3C7))
                                            .border(1.5.dp, goldColor, CircleShape),
                                        contentAlignment = Alignment.Center
                                    ) {
                                        Text(
                                            text = "S",
                                            fontSize = 22.sp,
                                            fontWeight = FontWeight.Black,
                                            color = goldColor
                                        )
                                    }
                                    // Golden Checkmark badge
                                    Box(
                                        modifier = Modifier
                                            .size(16.dp)
                                            .clip(CircleShape)
                                            .background(goldColor),
                                        contentAlignment = Alignment.Center
                                    ) {
                                        Icon(
                                            imageVector = Icons.Default.Check,
                                            contentDescription = null,
                                            tint = Color.Black,
                                            modifier = Modifier.size(11.dp)
                                        )
                                    }
                                }

                                Column(
                                    modifier = Modifier.weight(1f, fill = false),
                                    verticalArrangement = Arrangement.spacedBy(2.dp)
                                ) {
                                    Text(
                                        text = "SwapnoPay Verified MFS",
                                        fontSize = 16.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = textMain,
                                        maxLines = 1,
                                        overflow = TextOverflow.Ellipsis
                                    )
                                    Text(
                                        text = "Merchant ID: ${gatewayProfile.id}",
                                        fontSize = 11.5.sp,
                                        color = textMuted,
                                        maxLines = 1,
                                        overflow = TextOverflow.Ellipsis
                                    )
                                    Text(
                                        text = "Payment truth: merchant database",
                                        fontSize = 11.sp,
                                        color = textMuted,
                                        maxLines = 1
                                    )
                                }
                            }

                            // Test Connection Button
                            OutlinedButton(
                                onClick = {
                                    viewModel.runSupabaseSystemTest()
                                    viewModel.refreshGatewayConfig()
                                },
                                shape = RoundedCornerShape(20.dp),
                                border = BorderStroke(1.dp, goldColor.copy(alpha = 0.8f)),
                                colors = ButtonDefaults.outlinedButtonColors(
                                    containerColor = if (isDarkMode) Color(0xFF1E180E) else Color(0xFFFFFBEB)
                                ),
                                contentPadding = PaddingValues(horizontal = 10.dp, vertical = 4.dp),
                                modifier = Modifier.height(34.dp)
                            ) {
                                Row(
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.spacedBy(4.dp)
                                ) {
                                    Icon(
                                        imageVector = Icons.Default.Leaderboard,
                                        contentDescription = null,
                                        tint = goldColor,
                                        modifier = Modifier.size(14.dp)
                                    )
                                    Text(
                                        text = if (isTestingConnection) "Verifying..." else "Verify DB",
                                        fontSize = 11.sp,
                                        fontWeight = FontWeight.SemiBold,
                                        color = goldColor,
                                        softWrap = false,
                                        maxLines = 1
                                    )
                                }
                            }
                        }

                        Spacer(modifier = Modifier.height(10.dp))

                        // Dedicated Status and Verification Badges Row (never collapses)
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .horizontalScroll(rememberScrollState()),
                            horizontalArrangement = Arrangement.spacedBy(8.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            // Active Status Badge
                            Surface(
                                shape = RoundedCornerShape(12.dp),
                                color = if (gatewayOperational) greenColor.copy(alpha = 0.15f) else Color(0xFFEF4444).copy(alpha = 0.15f),
                                border = BorderStroke(0.8.dp, if (gatewayOperational) greenColor.copy(alpha = 0.4f) else Color(0xFFEF4444).copy(alpha = 0.4f))
                            ) {
                                Row(
                                    modifier = Modifier.padding(horizontal = 8.dp, vertical = 4.dp),
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.spacedBy(5.dp)
                                ) {
                                    Box(
                                        modifier = Modifier
                                            .size(6.dp)
                                            .clip(CircleShape)
                                            .background(if (gatewayOperational) greenColor else Color(0xFFEF4444))
                                    )
                                    Text(
                                        text = when {
                                            !isGatewayPermissionGranted -> "Platform permission required"
                                            !isDbOnline -> "Merchant database offline"
                                            activeMethods.values.none { it } -> "Add an active MFS number"
                                            !gatewayServiceStatus.endsWith("ready") -> "Receipt service not ready"
                                            else -> "Production path ready"
                                        },
                                        fontSize = 10.5.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = if (gatewayOperational) greenColor else Color(0xFFEF4444),
                                        softWrap = false,
                                        maxLines = 1
                                    )
                                }
                            }

                            // Platform Fee Badge
                            Surface(
                                shape = RoundedCornerShape(12.dp),
                                color = if (isDarkMode) Color(0xFF27272A) else Color(0xFFF1F5F9),
                                border = BorderStroke(0.8.dp, cardBorder)
                            ) {
                                Text(
                                    text = "Server verified",
                                    fontSize = 10.5.sp,
                                    fontWeight = FontWeight.Medium,
                                    color = goldColor,
                                    modifier = Modifier.padding(horizontal = 8.dp, vertical = 4.dp),
                                    softWrap = false,
                                    maxLines = 1
                                )
                            }
                        }

                        if (isTestingConnection) {
                            Spacer(modifier = Modifier.height(12.dp))
                            LinearProgressIndicator(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .height(3.dp)
                                    .clip(CircleShape),
                                color = goldColor,
                                trackColor = cardBorder
                            )
                        }

                        Spacer(modifier = Modifier.height(16.dp))
                        HorizontalDivider(color = cardBorder, thickness = 0.8.dp)
                        Spacer(modifier = Modifier.height(12.dp))

                        // Stats Summary Row (4 columns)
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Column(horizontalAlignment = Alignment.Start) {
                                Text("Success Rate", fontSize = 11.sp, color = textMuted)
                                Spacer(modifier = Modifier.height(2.dp))
                                Text(String.format(java.util.Locale.US, "%.1f%%", gatewaySuccessRate), fontSize = 14.sp, fontWeight = FontWeight.Bold, color = greenColor)
                            }
                            Column(horizontalAlignment = Alignment.Start) {
                                Text("Today's Txn", fontSize = 11.sp, color = textMuted)
                                Spacer(modifier = Modifier.height(2.dp))
                                Text(todayGatewayPayments.size.toString(), fontSize = 14.sp, fontWeight = FontWeight.Bold, color = textMain)
                            }
                            Column(horizontalAlignment = Alignment.Start) {
                                Text("Total Volume", fontSize = 11.sp, color = textMuted)
                                Spacer(modifier = Modifier.height(2.dp))
                                Text("৳ ${String.format("%,.2f", todayGatewayPayments.sumOf { it.amount })}", fontSize = 14.sp, fontWeight = FontWeight.Bold, color = textMain)
                            }
                            Column(horizontalAlignment = Alignment.Start) {
                                Text("Last Txn", fontSize = 11.sp, color = textMuted)
                                Spacer(modifier = Modifier.height(2.dp))
                                Text(todayGatewayPayments.maxOfOrNull { it.timestamp }?.let(::formatTime) ?: "No payments", fontSize = 14.sp, fontWeight = FontWeight.Bold, color = textMain)
                            }
                        }
                    }
                }

                // 1b. DYNAMIC API KEY & GATEWAY ACCESS SECTION
                Column(verticalArrangement = Arrangement.spacedBy(10.dp)) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text(
                            text = "Dynamic API Key (গেটওয়ে এক্সেস কি)",
                            fontSize = 16.sp,
                            fontWeight = FontWeight.Bold,
                            color = textMain
                        )
                        Surface(
                            shape = RoundedCornerShape(12.dp),
                            color = if (merchantApiKey.isNotBlank()) greenColor.copy(alpha = 0.15f) else goldColor.copy(alpha = 0.15f),
                            border = BorderStroke(0.8.dp, if (merchantApiKey.isNotBlank()) greenColor.copy(alpha = 0.4f) else goldColor.copy(alpha = 0.4f))
                        ) {
                            Text(
                                text = if (merchantApiKey.isNotBlank()) "Active & Verified" else "Auto-Generating...",
                                fontSize = 10.5.sp,
                                fontWeight = FontWeight.Bold,
                                color = if (merchantApiKey.isNotBlank()) greenColor else goldColor,
                                modifier = Modifier.padding(horizontal = 8.dp, vertical = 4.dp)
                            )
                        }
                    }

                    Card(
                        modifier = Modifier.fillMaxWidth(),
                        shape = RoundedCornerShape(18.dp),
                        colors = CardDefaults.cardColors(containerColor = cardBg),
                        border = BorderStroke(1.dp, cardBorder)
                    ) {
                        Column(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(16.dp),
                            verticalArrangement = Arrangement.spacedBy(12.dp)
                        ) {
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Column(modifier = Modifier.weight(1f)) {
                                    Text(
                                        text = "Payment Gateway Dynamic Access Key",
                                        fontSize = 13.5.sp,
                                        fontWeight = FontWeight.SemiBold,
                                        color = textMain
                                    )
                                    Text(
                                        text = "ওয়েবসাইট বা অ্যাপে পেমেন্ট প্রসেস করতে এই ডায়নামিক কী ব্যবহার করুন",
                                        fontSize = 11.5.sp,
                                        color = textMuted
                                    )
                                }
                                IconButton(
                                    onClick = { isKeyRevealed = !isKeyRevealed },
                                    modifier = Modifier.size(32.dp)
                                ) {
                                    Icon(
                                        imageVector = if (isKeyRevealed) Icons.Default.VisibilityOff else Icons.Default.Visibility,
                                        contentDescription = if (isKeyRevealed) "Hide Key" else "Show Key",
                                        tint = goldColor,
                                        modifier = Modifier.size(18.dp)
                                    )
                                }
                            }

                            val displayKey = when {
                                merchantApiKey.isNotBlank() -> if (isKeyRevealed) merchantApiKey else merchantApiKeyPreview.ifBlank { merchantApiKey.take(12) + "••••••••••••" }
                                else -> "Generating secure key..."
                            }

                            Surface(
                                shape = RoundedCornerShape(12.dp),
                                color = if (isDarkMode) Color(0xFF1E1E24) else Color(0xFFF1F5F9),
                                border = BorderStroke(1.dp, cardBorder),
                                modifier = Modifier.fillMaxWidth()
                            ) {
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(horizontal = 12.dp, vertical = 10.dp),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Text(
                                        text = displayKey,
                                        fontSize = 12.sp,
                                        fontFamily = FontFamily.Monospace,
                                        fontWeight = FontWeight.Medium,
                                        color = if (merchantApiKey.isNotBlank()) textMain else textMuted,
                                        modifier = Modifier.weight(1f),
                                        maxLines = 1,
                                        overflow = TextOverflow.Ellipsis
                                    )
                                    Spacer(modifier = Modifier.width(8.dp))
                                    IconButton(
                                        onClick = {
                                            if (merchantApiKey.isNotBlank()) {
                                                clipboardManager.setText(AnnotatedString(merchantApiKey))
                                                android.widget.Toast.makeText(context, "API Key copied to clipboard!", android.widget.Toast.LENGTH_SHORT).show()
                                            }
                                        },
                                        enabled = merchantApiKey.isNotBlank(),
                                        modifier = Modifier.size(28.dp)
                                    ) {
                                        Icon(
                                            imageVector = Icons.Outlined.ContentCopy,
                                            contentDescription = "Copy API Key",
                                            tint = goldColor,
                                            modifier = Modifier.size(16.dp)
                                        )
                                    }
                                }
                            }

                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.spacedBy(8.dp)
                            ) {
                                Button(
                                    onClick = {
                                        if (merchantApiKey.isNotBlank()) {
                                            clipboardManager.setText(AnnotatedString(merchantApiKey))
                                            android.widget.Toast.makeText(context, "API Key copied to clipboard!", android.widget.Toast.LENGTH_SHORT).show()
                                        } else {
                                            viewModel.fetchMerchantApiKey()
                                        }
                                    },
                                    modifier = Modifier.weight(1f).height(40.dp),
                                    shape = RoundedCornerShape(10.dp),
                                    colors = ButtonDefaults.buttonColors(containerColor = goldColor)
                                ) {
