                                    Text("লাইভ ব্যালেন্স", fontSize = 12.sp, color = Color(0xFFD97706), fontWeight = FontWeight.Bold)
                                    Text("রিয়েলটাইম আপডেট", fontSize = 12.sp, color = textSub)
                                }

                                Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(12.dp)) {
