                                    ) {
                                        listOf(
                                            "৳" + String.format("%,.0f", maxChartVal),
                                            "৳" + String.format("%,.0f", maxChartVal * 0.66),
                                            "৳" + String.format("%,.0f", maxChartVal * 0.33),
                                            "৳0"
                                        ).forEach { label ->
                                            Text(label, fontSize = 8.5.sp, color = textSub)
                                        }
                                    }

                                    Spacer(modifier = Modifier.width(8.dp))

                                    // Bar + Line Canvas Area
                                    Box(modifier = Modifier.weight(1f).fillMaxHeight()) {
                                        // Bars
                                        Row(
                                            modifier = Modifier.fillMaxSize(),
                                            horizontalArrangement = Arrangement.SpaceBetween,
                                            verticalAlignment = Alignment.Bottom
                                        ) {
                                            bars.forEach { heightRatio ->
                                                Box(
                                                    modifier = Modifier
                                                        .width(16.dp)
                                                        .fillMaxHeight(heightRatio)
                                                        .clip(RoundedCornerShape(topStart = 6.dp, topEnd = 6.dp))
                                                        .background(
                                                            if (isDarkMode)
                                                                Brush.verticalGradient(listOf(goldAccent, Color(0xFFD97706)))
                                                            else
                                                                Brush.verticalGradient(listOf(Color(0xFF94A3B8), Color(0xFFCBD5E1)))
                                                        )
                                                )
                                            }
                                        }

                                        // Curved Line Overlay
                                        Canvas(modifier = Modifier.fillMaxSize()) {
                                            val w = size.width
                                            val h = size.height
                                            val xStep = if (bars.size > 1) w / (bars.size - 1) else w
                                            val points = bars.mapIndexed { idx, ratio ->
                                                Offset(idx * xStep, h * (1f - ratio))
                                            }

                                            val path = androidx.compose.ui.graphics.Path().apply {
                                                moveTo(points[0].x, points[0].y)
                                                for (i in 0 until points.size - 1) {
                                                    val p1 = points[i]
                                                    val p2 = points[i + 1]
                                                    cubicTo((p1.x + p2.x) / 2, p1.y, (p1.x + p2.x) / 2, p2.y, p2.x, p2.y)
                                                }
                                            }

                                            drawPath(
                                                path = path,
                                                color = if (isDarkMode) goldAccent else Color(0xFF4B5563),
                                                style = androidx.compose.ui.graphics.drawscope.Stroke(
                                                    width = 2.5.dp.toPx(),
                                                    cap = StrokeCap.Round
                                                )
                                            )

                                            // Highlight dots
                                            points.forEach { pt ->
                                                drawCircle(color = if (isDarkMode) goldAccent else Color(0xFF374151), radius = 4.dp.toPx(), center = pt)
                                                drawCircle(color = Color.White, radius = 2.dp.toPx(), center = pt)
                                            }
                                        }
                                    }
                                }
                            }

                            Spacer(modifier = Modifier.height(8.dp))

                            // X-Axis Date Labels
                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(start = 36.dp),
