                            contentAlignment = Alignment.Center
                        ) {
                            Icon(Icons.Default.FilterList, null, tint = if (isDarkMode) Color(0xFFF5C518) else Color(0xFF0F172A), modifier = Modifier.size(18.dp))
                        }

                        // Search Button
