                }
            }

            // ── 4. FILTERS BAR (Date & Account) ─────────────────────────────────
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = 20.dp, vertical = 10.dp),
                horizontalArrangement = Arrangement.spacedBy(10.dp)
            ) {
                // Date Filter Button
                Card(
                    modifier = Modifier
