                    }

                    if (suppliers.isEmpty()) {
                        Text("No suppliers found in database. Tap above to add one.", fontSize = 12.5.sp, color = textMutedColor, modifier = Modifier.padding(vertical = 12.dp))
                    } else {
                        suppliers.forEach { sup ->
