                                    Text(
                                        text = "New Topic",
                                        fontSize = 11.5.sp,
                                        fontWeight = FontWeight.Medium,
                                        color = textMuted,
                                        modifier = Modifier.padding(horizontal = 10.dp, vertical = 5.dp)
                                    )
                                }
                            }
                        }

                        items(chatHistory) { msg: Map<String, String> ->
                            StructuredAiMessageBubble(
                                message = msg,
                                isDarkMode = isDarkMode,
                                viewModel = viewModel
                            )
                        }
                    }

                    if (isThinking) {
                        item {
                            Card(
                                shape = RoundedCornerShape(16.dp),
                                colors = CardDefaults.cardColors(
                                    containerColor = if (isDarkMode) Color(0xFF161A29) else Color(0xFFFAF5FF)
                                ),
                                border = BorderStroke(
                                    1.dp,
                                    if (isDarkMode) Color(0xFF2E2448) else Color(0xFFF3E8FF)
                                ),
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(vertical = 4.dp)
                            ) {
                                Row(
                                    modifier = Modifier.padding(horizontal = 14.dp, vertical = 12.dp),
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.spacedBy(10.dp)
                                ) {
                                    CircularProgressIndicator(
                                        modifier = Modifier.size(18.dp),
                                        strokeWidth = 2.5.dp,
                                        color = Color(0xFFA855F7)
                                    )
                                    Column {
                                        Text(
                                            text = "AI Copilot হিসাব ও ডেটা বিশ্লেষণ করছে...",
                                            fontSize = 12.5.sp,
                                            fontWeight = FontWeight.SemiBold,
                                            color = if (isDarkMode) Color(0xFFE2E8F0) else Color(0xFF475569)
                                        )
                                        Text(
                                            text = "Analyzing business trends & formulating insights",
                                            fontSize = 10.5.sp,
                                            color = textMuted
                                        )
                                    }
                                }
                            }
                        }
                    }
                }

                // ── 3. PIXEL-PERFECT FLOATING MESSAGE INPUT CARD ────────────
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(horizontal = 16.dp, vertical = 2.dp)
                ) {
                    Card(
                        modifier = Modifier.fillMaxWidth(),
                        shape = RoundedCornerShape(22.dp),
                        colors = CardDefaults.cardColors(containerColor = cardBg),
                        border = BorderStroke(1.dp, cardBorder),
                        elevation = CardDefaults.cardElevation(defaultElevation = 2.dp)
                    ) {
                        Column(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(horizontal = 14.dp, vertical = 10.dp)
                        ) {
                            // Message Text Input
                            OutlinedTextField(
                                value = userText,
                                onValueChange = { userText = it },
                                placeholder = {
                                    Text(
                                        text = "Ask AI Copilot about sales, dues, inventory...",
                                        fontSize = 13.5.sp,
                                        color = textMuted
                                    )
                                },
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .heightIn(min = 46.dp, max = 110.dp),
                                colors = OutlinedTextFieldDefaults.colors(
                                    focusedBorderColor = Color.Transparent,
                                    unfocusedBorderColor = Color.Transparent,
                                    disabledBorderColor = Color.Transparent,
                                    errorBorderColor = Color.Transparent,
                                    focusedContainerColor = Color.Transparent,
                                    unfocusedContainerColor = Color.Transparent,
                                    cursorColor = Color(0xFF6366F1),
                                    focusedTextColor = textMain,
                                    unfocusedTextColor = textMain
                                ),
                                textStyle = TextStyle(
                                    fontSize = 14.sp,
                                    color = textMain,
                                    lineHeight = 19.sp
                                ),
                                maxLines = 4
                            )

                            Spacer(modifier = Modifier.height(8.dp))

                            // Bottom Controls Toolbar
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                // Left Controls: (+) and (🌐 Tools)
                                Row(
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.spacedBy(8.dp)
                                ) {
                                    // Plus (+) Circle Button for Document / Receipt OCR
                                    Box(
                                        modifier = Modifier
                                            .size(36.dp)
                                            .clip(CircleShape)
                                            .background(if (isDarkMode) Color(0xFF1E2333) else Color(0xFFF1F5F9))
                                            .clickable { showOcrSimDialog = true },
                                        contentAlignment = Alignment.Center
                                    ) {
                                        Icon(
                                            imageVector = Icons.Default.Add,
                                            contentDescription = "Attach / Scan Document",
                                            tint = textMain,
                                            modifier = Modifier.size(18.dp)
                                        )
                                    }

                                    // 🌐 Tools Pill Button
                                    Surface(
                                        modifier = Modifier
                                            .height(36.dp)
                                            .clip(RoundedCornerShape(18.dp))
                                            .clickable { showToolsModal = true },
                                        shape = RoundedCornerShape(18.dp),
                                        color = if (isDarkMode) Color(0xFF1E2333) else Color(0xFFF1F5F9)
                                    ) {
                                        Row(
                                            modifier = Modifier.padding(horizontal = 10.dp),
                                            verticalAlignment = Alignment.CenterVertically,
                                            horizontalArrangement = Arrangement.spacedBy(5.dp)
                                        ) {
                                            Icon(
                                                imageVector = Icons.Outlined.Language,
                                                contentDescription = null,
                                                tint = textMain,
                                                modifier = Modifier.size(16.dp)
                                            )
                                            Text(
                                                text = "Tools",
                                                fontSize = 12.5.sp,
                                                fontWeight = FontWeight.Medium,
                                                color = textMain
                                            )
                                        }
                                    }
                                }

                                // Right Controls: (Mic) and (↑ Send)
                                Row(
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.spacedBy(8.dp)
                                ) {
                                    // Mic Circle Button
                                    Box(
                                        modifier = Modifier
                                            .size(36.dp)
                                            .clip(CircleShape)
                                            .background(if (isDarkMode) Color(0xFF1E2333) else Color(0xFFF1F5F9))
                                            .clickable { launchVoiceRecognition() },
